// Static checked source bundle; included in the public action code identity.
export const rules = {
  "artifact_rules.py": "\"\"\"Read-only rules extracted from skills/autodev/hooks/artifact_check.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nimport json\nimport re\nfrom pathlib import Path\nfrom typing import NamedTuple\nfrom native_context import HookContext, fail_line, info, is_nonempty, read_text\nfrom hooks.implementation_scope import load_scope, scope_path\nfrom hooks.spec_contract import SPEC_REQUIREMENT_DEF_RE, SPEC_SCENARIO_DEF_RE\nfrom hooks.artifact_ref_validator import design_marker_value\nfrom hooks.design_contract_lock import validate_design_contract_lock as validate_locked_design_contract\nfrom hooks.ui_context import validate_ui_context_data, load_ui_context, ui_context_indexes, ui_context_path\nfrom hooks.plan_json import load_and_validate_plan, load_plan_bundle, plan_json_path\nfrom hooks.artifact_ref_validator import validate_task_artifact_refs, validate_plan_design_coverage\nfrom hooks.design_contract_lock import load_confirmed_design_contract\nfrom hooks.plan_scope import resolve_plan_scope, scope_report\nfrom hooks.plan_granularity import validate_plan_task_granularity_item\nfrom hooks.code_task_context import resolve_task_refs\nfrom hooks.parallel_validation_ownership import validation_ownership_errors\nfrom hooks.frontend_route_constants import ROUTE_NONE, ROUTE_SPEC_DRIVEN, ROUTE_ABSOLUTE, ROUTE_STANDARD, ROUTE_MISSING\n\nREQ_ID = re.compile(r\"\\bREQ-\\d{3}\\b\")\n\n\nSCN_ID = re.compile(r\"\\bSCN-\\d{3}\\b\")\n\n\nSPEC_REQUIREMENT_NUMERIC_RE = re.compile(\n    r\"^###\\s+Requirement\\s+(?=\\[?(REQ-(?P<digits>\\d+))\\]?:\\s+.+$)(?:\\[REQ-\\d+\\]|REQ-\\d+):\\s+.+$\",\n    re.MULTILINE,\n)\n\n\nSPEC_SCENARIO_NUMERIC_RE = re.compile(\n    r\"^####\\s+Scenario\\s+(?=\\[?(SCN-(?P<digits>\\d+))\\]?:\\s+.+$)(?:\\[SCN-\\d+\\]|SCN-\\d+):\\s+.+$\",\n    re.MULTILINE,\n)\n\n\nCONTRACT_HEADING_CANDIDATE = re.compile(r\"^#{1,6}[ \\t]+.*?\\b(?:REQ|SCN)-\\S\")\n\n\nSECTION_HEADING = re.compile(r\"^##(?!#)\\s+\\S\")\n\n\nSPEC_DECISION_ID = re.compile(r\"\\bDEC-\\d{3}\\b\")\n\n\nSPEC_DECISION_HEADING = re.compile(r\"^###\\s+(DEC-\\d{3})\\s*[:：]\", re.MULTILINE)\n\n\nDECISION_LOG_SECTION = re.compile(\n    r\"^##\\s+Decision Log\\s*$\\n(?P<body>.*?)(?=^##\\s|\\Z)\",\n    re.MULTILINE | re.DOTALL,\n)\n\n\nCAPABILITIES_SECTION = re.compile(\n    r\"^##\\s+Capabilities\\s*$\\n(?P<body>.*?)(?=^##\\s|\\Z)\",\n    re.MULTILINE | re.DOTALL,\n)\n\n\nCAPABILITY_ITEM = re.compile(\n    r\"^[ \\t]*[-*][ \\t]+`?(?P<name>[a-z0-9]+(?:-[a-z0-9]+)*)`?[ \\t]*[:：]\",\n    re.MULTILINE,\n)\n\n\nDESIGN_API_DEF_RE = re.compile(r\"^\\|\\s*(API-\\d{3})\\s*\\|\", re.MULTILINE)\n\n\nDESIGN_DATA_DEF_RE = re.compile(r\"^\\|\\s*(DATA-\\d{3})\\s*\\|\", re.MULTILINE)\n\n\nDESIGN_DECISION_DEF_RE = re.compile(r\"^\\|\\s*(D-\\d{3})\\s*\\|\", re.MULTILINE)\n\n\nPENDING_CELL = re.compile(r\"\\|\\s*(待确认|读码差异)\\s*\\|\")\n\n\nFENCE_OPEN_LINE = re.compile(r\"^[ \\t]{0,3}(?P<fence>`{3,}|~{3,})(?P<info>.*)$\")\n\n\nBLOCKQUOTE_LINE = re.compile(r\"^[ \\t]{0,3}>\")\n\n\nTEMPLATE_WRAPPER_HEADINGS = {\"# 技术设计模板\", \"# 计划模板\"}\n\n\ndef find_template_guidance_residue(text: str) -> list[tuple[int, str]]:\n    \"\"\"Return ``(line number, kind)`` for template-only markup in an artifact.\n\n    Autodev contract artifacts use paragraphs, lists, and tables for explanatory\n    content. Markdown blockquotes are reserved for template authoring guidance\n    and must not survive generation. Fenced code blocks are ignored so examples\n    containing shell redirects or quoted Markdown do not false-positive.\n    \"\"\"\n    residues: list[tuple[int, str]] = []\n    fence_char = \"\"\n    fence_length = 0\n    seen_content = False\n\n    for lineno, line in enumerate(text.splitlines(), 1):\n        if fence_char:\n            stripped = line.lstrip(\" \\t\")\n            run_length = len(stripped) - len(stripped.lstrip(fence_char))\n            if run_length >= fence_length and not stripped[run_length:].strip():\n                fence_char = \"\"\n                fence_length = 0\n            continue\n\n        fence_match = FENCE_OPEN_LINE.match(line)\n        if fence_match:\n            fence = fence_match.group(\"fence\")\n            info = fence_match.group(\"info\").strip().lower()\n            if info in {\"markdown\", \"md\"} and not seen_content:\n                residues.append((lineno, \"outer_markdown_fence\"))\n            fence_char = fence[0]\n            fence_length = len(fence)\n            seen_content = True\n            continue\n\n        stripped = line.strip()\n        if stripped in TEMPLATE_WRAPPER_HEADINGS:\n            residues.append((lineno, \"wrapper_heading\"))\n        if BLOCKQUOTE_LINE.match(line):\n            residues.append((lineno, \"blockquote\"))\n        if stripped:\n            seen_content = True\n\n    return residues\n\n\ndef validate_no_template_guidance(\n    ctx: HookContext,\n    path: Path,\n    text: str,\n) -> int:\n    \"\"\"Reject template authoring guidance copied into a generated artifact.\"\"\"\n    try:\n        artifact = path.relative_to(ctx.feature_dir).as_posix()\n    except ValueError:\n        artifact = str(path)\n\n    failures = 0\n    for lineno, kind in find_template_guidance_residue(text):\n        failures += fail_line(\n            ctx,\n            \"artifact_template_guidance_residue\",\n            f\" file={artifact!r} line={lineno} kind={kind}\",\n            target=f\"{artifact}:{lineno}\",\n        )\n    return failures\n\n\ndef spec_files(ctx: HookContext) -> list[Path]:\n    return sorted(\n        path\n        for path in ctx.feature_dir.glob(\"specs/**/*.md\")\n        if path.is_file() and path.stat().st_size > 0\n    )\n\n\ndef _implementation_scope_contract_errors(ctx: HookContext) -> tuple[str, list[str]]:\n    \"\"\"Load the optional scope contract without breaking legacy Features.\"\"\"\n\n    manifest = scope_path(ctx.feature_dir)\n    if not manifest.is_file():\n        return \"full_stack\", []\n    return load_scope(ctx.feature_dir, required=True)\n\n\ndef _report_implementation_scope_errors(ctx: HookContext) -> int:\n    _, errors = _implementation_scope_contract_errors(ctx)\n    failures = 0\n    for error in errors:\n        failures += fail_line(\n            ctx,\n            \"invalid_implementation_scope\",\n            f\" detail={error}\",\n            target=error,\n        )\n    return failures\n\n\ndef validate_proposal_contract(ctx: HookContext) -> int:\n    proposal = ctx.file(\"proposal.md\")\n    if not is_nonempty(proposal):\n        return fail_line(ctx, \"missing_proposal\")\n\n    # Only the capability list is consumed as a structural contract downstream.\n    # Other proposal sections are authoring guidance, not completion gates.\n    failures = _report_implementation_scope_errors(ctx)\n    if not CAPABILITIES_SECTION.search(read_text(proposal)):\n        failures += fail_line(\n            ctx,\n            \"invalid_proposal_missing_section\",\n            \" section='Capabilities'\",\n            target=\"Capabilities\",\n        )\n    return failures\n\n\ndef proposal_capabilities(text: str) -> set[str]:\n    \"\"\"Kebab-case capability names listed under ``## Capabilities``, any group.\"\"\"\n    section = CAPABILITIES_SECTION.search(text)\n    if not section:\n        return set()\n    return {\n        match.group(\"name\")\n        for match in CAPABILITY_ITEM.finditer(section.group(\"body\"))\n    }\n\n\ndef spec_capability_dirs(ctx: HookContext) -> set[str]:\n    \"\"\"Capability directory names following the ``specs/<capability>/spec.md`` shape.\"\"\"\n    return {\n        path.parent.name\n        for path in ctx.feature_dir.glob(\"specs/*/spec.md\")\n        if path.is_file() and path.stat().st_size > 0\n    }\n\n\ndef validate_capability_spec_correspondence(ctx: HookContext) -> int:\n    \"\"\"Both directions of ``Capabilities`` <-> ``specs/<capability>/spec.md``.\n\n    Listing a capability without writing its spec, and shipping a spec the\n    proposal never claims, are both mechanical facts about files. Neither is\n    something the agent should be asked to self-certify in its reply.\n    \"\"\"\n    proposal = ctx.file(\"proposal.md\")\n    if not is_nonempty(proposal):\n        # `proposal_contract` owns this failure; do not report it twice.\n        return 0\n\n    text = read_text(proposal)\n    if not CAPABILITIES_SECTION.search(text):\n        # Missing section is `invalid_proposal_missing_section`, not a mismatch.\n        return 0\n\n    declared = proposal_capabilities(text)\n    present = spec_capability_dirs(ctx)\n\n    failures = 0\n    missing_specs = sorted(declared - present)\n    if missing_specs:\n        failures += fail_line(\n            ctx,\n            \"proposal_capability_missing_spec\",\n            f\" capabilities={','.join(missing_specs)}\",\n            target=\",\".join(missing_specs),\n        )\n    unlisted = sorted(present - declared)\n    if unlisted:\n        failures += fail_line(\n            ctx,\n            \"spec_missing_proposal_capability\",\n            f\" capabilities={','.join(unlisted)}\",\n            target=\",\".join(unlisted),\n        )\n    return failures\n\n\ndef validate_specs_contract(ctx: HookContext) -> int:\n    specs = spec_files(ctx)\n    if not specs:\n        return fail_line(ctx, \"missing_specs\")\n\n    failures = _report_implementation_scope_errors(ctx)\n    # Renumbering suggestions have to clear every ID the feature already owns,\n    # not just the ones in the file being repaired -- a file-local suggestion\n    # walks straight into `duplicate_spec_id_across_specs`.\n    taken: set[str] = set()\n    for spec in specs:\n        spec_text = read_text(spec)\n        taken.update(SPEC_REQUIREMENT_DEF_RE.findall(spec_text))\n        taken.update(SPEC_SCENARIO_DEF_RE.findall(spec_text))\n    for spec in specs:\n        text = read_text(spec)\n        rel = spec.relative_to(ctx.feature_dir)\n        _, duplicate_reasons = _spec_definition_index(text)\n        for reason in duplicate_reasons:\n            failures += fail_line(ctx, reason, f\" file={rel}\", target=str(rel))\n        width_errors = contract_id_width_errors(text, taken)\n        for width_error in width_errors:\n            if width_error.suggested:\n                taken.add(width_error.suggested)\n            failures += fail_line(\n                ctx,\n                \"spec_id_width_invalid\",\n                f\" file={rel} id={width_error.current} suggested={width_error.suggested or 'NONE'}\",\n                target=str(rel),\n                fields={\n                    \"id\": width_error.current,\n                    \"suggested\": width_error.suggested or \"三位 ID 空间已耗尽\",\n                },\n            )\n        has_requirement_candidate = SPEC_REQUIREMENT_NUMERIC_RE.search(text) is not None\n        has_scenario_candidate = SPEC_SCENARIO_NUMERIC_RE.search(text) is not None\n        if not has_requirement_candidate:\n            failures += fail_line(ctx, \"invalid_spec_missing_requirement\", f\" file={rel}\", target=str(rel))\n        if not has_scenario_candidate:\n            failures += fail_line(ctx, \"invalid_spec_missing_scenario\", f\" file={rel}\", target=str(rel))\n        malformed = malformed_contract_headings(text)\n        if malformed:\n            failures += fail_line(\n                ctx,\n                \"spec_contract_heading_malformed\",\n                f\" file={rel} headings={'; '.join(malformed)}\",\n                target=str(rel),\n                fields={\"headings\": \"; \".join(malformed)},\n            )\n        barren = requirements_without_scenario(text)\n        if barren:\n            failures += fail_line(\n                ctx,\n                \"spec_requirement_without_scenario\",\n                f\" file={rel} requirements={','.join(barren)}\",\n                target=str(rel),\n                fields={\"requirements\": \",\".join(barren)},\n            )\n        orphans = scenarios_without_requirement(text)\n        if orphans:\n            failures += fail_line(\n                ctx,\n                \"spec_scenario_without_requirement\",\n                f\" file={rel} scenarios={','.join(orphans)}\",\n                target=str(rel),\n                fields={\"scenarios\": \",\".join(orphans)},\n            )\n    failures += _duplicate_ids_across_specs(ctx, specs)\n    return failures\n\n\ndef _duplicate_ids_across_specs(ctx: HookContext, specs: list[Path]) -> int:\n    \"\"\"One REQ/SCN ID must name one thing across the whole feature.\n\n    ``collect_spec_definition_index`` merges every spec's IDs into one flat set\n    that five validators consume, ``_validate_scenario_coverage`` among them.\n    A number reused in a second capability collapses into a single entry there,\n    so covering one of them marks both covered -- the same vacuous-coverage\n    shape the ID convention mismatch produced.\n    \"\"\"\n    owners: dict[str, list[str]] = {}\n    for spec in specs:\n        text = read_text(spec)\n        rel = spec.relative_to(ctx.feature_dir).as_posix()\n        for pattern in (SPEC_REQUIREMENT_DEF_RE, SPEC_SCENARIO_DEF_RE):\n            for spec_id in set(pattern.findall(text)):\n                owners.setdefault(spec_id, []).append(rel)\n\n    reserved = set(owners)\n    failures = 0\n    for spec_id, files in sorted(owners.items()):\n        if len(files) > 1:\n            sorted_files = sorted(files)\n            prefix = spec_id.split(\"-\", 1)[0]\n            replacements: list[str] = []\n            for owner in sorted_files[1:]:\n                suggested = _next_free_spec_id(prefix, 0, reserved)\n                if suggested:\n                    reserved.add(suggested)\n                    replacements.append(f\"{owner}:{spec_id}->{suggested}\")\n                else:\n                    replacements.append(f\"{owner}:{spec_id}->三位 ID 空间已耗尽\")\n            failures += fail_line(\n                ctx,\n                \"duplicate_spec_id_across_specs\",\n                f\" id={spec_id} keep={sorted_files[0]} replacements={';'.join(replacements)}\",\n                target=spec_id,\n                fields={\n                    \"files\": \",\".join(sorted_files),\n                    \"keep\": sorted_files[0],\n                    \"replacements\": \"; \".join(replacements),\n                },\n            )\n    return failures\n\n\ndef malformed_contract_headings(text: str) -> list[str]:\n    \"\"\"Heading lines carrying a REQ-/SCN- token that the ID indexer will not see.\"\"\"\n    malformed: list[str] = []\n    for line in text.splitlines():\n        if not CONTRACT_HEADING_CANDIDATE.match(line):\n            continue\n        if SPEC_REQUIREMENT_DEF_RE.match(line) or SPEC_SCENARIO_DEF_RE.match(line):\n            continue\n        # 数字 ID 的标题形状正确但位数错误时，由 ``spec_id_width_invalid``\n        # 给唯一根因和替换值；这里不再重复报 malformed。\n        if SPEC_REQUIREMENT_NUMERIC_RE.match(line) or SPEC_SCENARIO_NUMERIC_RE.match(line):\n            continue\n        malformed.append(line.strip())\n    return malformed\n\n\nclass SpecIdWidth(NamedTuple):\n    current: str\n    suggested: str\n\n\ndef contract_id_width_errors(text: str, taken: Iterable[str] = ()) -> list[SpecIdWidth]:\n    \"\"\"Well-shaped numeric contract headings whose ID is not exactly three digits.\"\"\"\n\n    reserved = set(taken)\n    reserved.update(SPEC_REQUIREMENT_DEF_RE.findall(text))\n    reserved.update(SPEC_SCENARIO_DEF_RE.findall(text))\n    errors: list[SpecIdWidth] = []\n    for prefix, pattern in (\n        (\"REQ\", SPEC_REQUIREMENT_NUMERIC_RE),\n        (\"SCN\", SPEC_SCENARIO_NUMERIC_RE),\n    ):\n        highest = 0\n        for match in pattern.finditer(text):\n            digits = match.group(\"digits\")\n            current = match.group(1)\n            if len(digits) == 3:\n                highest = max(highest, int(digits))\n                continue\n            suggested = _next_free_spec_id(prefix, highest, reserved)\n            if suggested:\n                reserved.add(suggested)\n                highest = int(suggested.rpartition(\"-\")[2])\n            errors.append(SpecIdWidth(current, suggested))\n    return errors\n\n\ndef _next_free_spec_id(prefix: str, floor: int, reserved: set[str]) -> str:\n    \"\"\"Lowest ``<prefix>-NNN`` above ``floor`` that nothing else in the feature owns.\"\"\"\n    for number in range(floor + 1, 1000):\n        candidate = f\"{prefix}-{number:03d}\"\n        if candidate not in reserved:\n            return candidate\n    return \"\"\n\n\ndef scenarios_without_requirement(text: str) -> list[str]:\n    \"\"\"Scenario IDs that no Requirement owns.\n\n    ``requirements_without_scenario`` checks the other direction. A Scenario\n    placed before the file's first Requirement, or directly under an operation\n    section heading, belongs to nothing -- it is indexed as a defined scenario\n    and then demands coverage for a behaviour no Requirement states.\n    \"\"\"\n    orphans: list[str] = []\n    current_requirement: str | None = None\n    for line in text.splitlines():\n        if SECTION_HEADING.match(line):\n            # A new `## ` section closes the Requirement that came before it.\n            current_requirement = None\n            continue\n        requirement = SPEC_REQUIREMENT_DEF_RE.match(line)\n        if requirement:\n            current_requirement = requirement.group(1)\n            continue\n        scenario = SPEC_SCENARIO_DEF_RE.match(line)\n        if scenario and current_requirement is None:\n            orphans.append(scenario.group(1))\n    return orphans\n\n\ndef requirements_without_scenario(text: str) -> list[str]:\n    \"\"\"Requirement IDs whose own block carries no Scenario heading.\n\n    A file-level \"has at least one REQ and one SCN\" check passes when three\n    Requirements share a single Scenario, so slice per Requirement instead.\n    Uses the same two module-level patterns the ID indexer uses; introducing a\n    third spelling here is what let coverage go vacuous before.\n    \"\"\"\n    matches = list(SPEC_REQUIREMENT_DEF_RE.finditer(text))\n    barren: list[str] = []\n    for index, match in enumerate(matches):\n        end = matches[index + 1].start() if index + 1 < len(matches) else len(text)\n        block = text[match.end():end]\n        # A new `## ` section ends the Requirement even without a following `### `.\n        next_section = re.search(r\"^##\\s+\\S\", block, re.MULTILINE)\n        if next_section:\n            block = block[: next_section.start()]\n        if not SPEC_SCENARIO_DEF_RE.search(block):\n            barren.append(match.group(1))\n    return barren\n\n\ndef validate_design_contract(ctx: HookContext) -> int:\n    design = ctx.file(\"design.md\")\n    if not is_nonempty(design):\n        return fail_line(ctx, \"missing_design\")\n\n    text = read_text(design)\n    failures = validate_no_template_guidance(ctx, design, text)\n    required_sections = [\n        \"Context / 输入上下文\",\n        \"Code Evidence\",\n        \"Spec Traceability\",\n        \"API Decisions\",\n        \"Data Decisions\",\n        \"Technical Design\",\n        \"Risks / Open Questions\",\n    ]\n    for section in required_sections:\n        if section not in text:\n            failures += fail_line(ctx, \"invalid_design_missing_section\", f\" section={section!r}\", target=section)\n\n    no_http_api = design_marker_value(text, \"x-auto-no-http-api\")\n    no_sql = design_marker_value(text, \"x-auto-no-sql\")\n    if no_http_api is None:\n        failures += fail_line(ctx, \"missing_design_api_marker\")\n    if no_sql is None:\n        failures += fail_line(ctx, \"missing_design_data_marker\")\n    design_ids, _ = collect_design_definition_index(ctx)\n    if no_http_api is True and design_ids[\"API\"]:\n        failures += fail_line(ctx, \"design_api_marker_conflicts_with_definitions\")\n    if no_sql is True and design_ids[\"DATA\"]:\n        failures += fail_line(ctx, \"design_data_marker_conflicts_with_definitions\")\n    pending = PENDING_CELL.findall(text)\n    if pending:\n        failures += fail_line(\n            ctx,\n            \"design_has_pending_cells\",\n            f\" count={len(pending)}\",\n            target=f\"{len(pending)} 处\",\n        )\n    failures += _unresolved_decision_refs(ctx, text)\n    return failures\n\n\ndef validate_design_contract_lock(ctx: HookContext) -> int:\n    \"\"\"Require the Design-owned snapshot to match the validated design artifact.\"\"\"\n\n    failures = 0\n    for issue in validate_locked_design_contract(ctx.feature_dir, ctx.slug):\n        failures += _emit_artifact_issue(ctx, issue, \".design-contract.lock.json\")\n    return failures\n\n\ndef _unresolved_decision_refs(ctx: HookContext, design_text: str) -> int:\n    \"\"\"Every ``DEC-NNN`` design cites must exist in the proposal's Decision Log.\n\n    The lookup is scoped to the section, not the whole file: a ``### DEC-001:``\n    heading dropped anywhere else in the proposal would otherwise resolve the\n    reference, which makes the check report something weaker than it claims.\n\n    Reference resolution only. Whether a decision is well argued, and whether\n    every Requirement needs one, are judgements a script cannot make -- and the\n    2026-07-29 trace showed that demanding a self-issued status word here just\n    teaches the model to forge one. Existence is a fact about files, so that is\n    all this checks; ``无`` stays a legal cell value.\n    \"\"\"\n    cited = set(SPEC_DECISION_ID.findall(design_text))\n    if not cited:\n        return 0\n\n    proposal = ctx.file(\"proposal.md\")\n    if not is_nonempty(proposal):\n        # `proposal_contract` owns a missing proposal; do not report it twice.\n        return 0\n\n    section = DECISION_LOG_SECTION.search(read_text(proposal))\n    defined = set(SPEC_DECISION_HEADING.findall(section.group(\"body\"))) if section else set()\n    missing = sorted(cited - defined)\n    if not missing:\n        return 0\n    return fail_line(\n        ctx,\n        \"design_decision_ref_unresolved\",\n        f\" ids={','.join(missing)}\",\n        target=\",\".join(missing),\n    )\n\n\ndef _spec_definition_index(text: str) -> tuple[dict[str, set[str]], list[str]]:\n    req_ids = SPEC_REQUIREMENT_DEF_RE.findall(text)\n    scn_ids = SPEC_SCENARIO_DEF_RE.findall(text)\n    failures: list[str] = []\n    if len(req_ids) != len(set(req_ids)):\n        failures.append(\"duplicate_requirement_id\")\n    if len(scn_ids) != len(set(scn_ids)):\n        failures.append(\"duplicate_scenario_id\")\n    return {\"REQ\": set(req_ids), \"SCN\": set(scn_ids)}, failures\n\n\ndef collect_spec_definition_index(ctx: HookContext) -> tuple[dict[str, set[str]], int]:\n    failures = 0\n    index = {\"REQ\": set(), \"SCN\": set()}\n    for spec in spec_files(ctx):\n        definitions, duplicate_reasons = _spec_definition_index(read_text(spec))\n        rel = spec.relative_to(ctx.feature_dir)\n        for reason in duplicate_reasons:\n            failures += fail_line(ctx, reason, f\" file={rel}\", target=str(rel))\n        index[\"REQ\"].update(definitions[\"REQ\"])\n        index[\"SCN\"].update(definitions[\"SCN\"])\n    return index, failures\n\n\ndef _design_definition_index(text: str) -> tuple[dict[str, set[str]], list[str]]:\n    api_ids = DESIGN_API_DEF_RE.findall(text)\n    data_ids = DESIGN_DATA_DEF_RE.findall(text)\n    decision_ids = DESIGN_DECISION_DEF_RE.findall(text)\n    failures: list[str] = []\n    if len(api_ids) != len(set(api_ids)):\n        failures.append(\"duplicate_design_api_id\")\n    if len(data_ids) != len(set(data_ids)):\n        failures.append(\"duplicate_design_data_id\")\n    if len(decision_ids) != len(set(decision_ids)):\n        failures.append(\"duplicate_design_decision_id\")\n    return {\"API\": set(api_ids), \"DATA\": set(data_ids), \"D\": set(decision_ids)}, failures\n\n\ndef collect_design_definition_index(ctx: HookContext) -> tuple[dict[str, set[str]], int]:\n    design = ctx.file(\"design.md\")\n    if not is_nonempty(design):\n        return {\"API\": set(), \"DATA\": set(), \"D\": set()}, 0\n    definitions, duplicate_reasons = _design_definition_index(read_text(design))\n    failures = 0\n    for reason in duplicate_reasons:\n        failures += fail_line(ctx, reason, target=\"design.md\")\n    return definitions, failures\n\n\ndef load_json_artifact(ctx: HookContext, name: str, *, required: bool = True) -> tuple[dict | None, int]:\n    path = ctx.file(name)\n    if not is_nonempty(path):\n        if not required:\n            info(ctx, \"json_artifact_missing_degrade\", f\" file={name}\")\n            return None, 0\n        return None, fail_line(ctx, \"missing_json_artifact\", f\" file={name}\")\n    try:\n        data = json.loads(path.read_text(encoding=\"utf-8\"))\n    except json.JSONDecodeError as exc:\n        return None, fail_line(ctx, \"invalid_json_artifact\", f\" file={name} detail={exc}\")\n    if not isinstance(data, dict):\n        return None, fail_line(ctx, \"invalid_json_artifact_root\", f\" file={name}\")\n    return data, 0\n\n\ndef _string_list_value(value: object) -> list[str] | None:\n    if not isinstance(value, list):\n        return None\n    result: list[str] = []\n    for item in value:\n        if not isinstance(item, str):\n            return None\n        stripped = item.strip()\n        if stripped:\n            result.append(stripped)\n    return result\n\n\ndef _scenario_refs_from_spec_refs(spec_refs: list[str]) -> set[str]:\n    return set(SCN_ID.findall(\" \".join(spec_refs)))\n\n\ndef validate_ui_context_json(ctx: HookContext) -> int:\n    data, failures = load_json_artifact(\n        ctx,\n        \"UI_CONTEXT.json\",\n        required=ctx.requires_artifact(\"UI_CONTEXT.json\"),\n    )\n    if data is None:\n        return failures\n    spec_ids, spec_failures = collect_spec_definition_index(ctx)\n    failures += spec_failures\n    for error in validate_ui_context_data(\n        data,\n        feature_id=ctx.slug,\n        # PRD creates the confirmed UI scope before spec IDs exist; specs/plan\n        # stages still require the context to be locked and reference-resolved.\n        require_locked=ctx.requires_artifact(\"UI_CONTEXT.json\")\n        and ctx.skill != \"autobiz-requirement-discuss\",\n        defined_requirements=spec_ids[\"REQ\"],\n        defined_scenarios=spec_ids[\"SCN\"],\n    ):\n        failures += fail_line(ctx, \"invalid_ui_context_json\", f\" detail={error}\")\n    return failures\n\n\ndef _load_ui_context_for_projection(ctx: HookContext) -> tuple[dict | None, int]:\n    try:\n        data = load_ui_context(ctx.feature_dir)\n    except UIContextError as exc:\n        return None, fail_line(ctx, \"invalid_ui_context_json\", f\" detail={exc}\")\n    if data is None:\n        if ctx.requires_artifact(\"UI_CONTEXT.json\"):\n            return None, fail_line(ctx, \"missing_json_artifact\", \" file=UI_CONTEXT.json\")\n        info(ctx, \"ui_context_not_in_contract_degrade\")\n        return None, 0\n    return data, 0\n\n\ndef _visual_source_expected_frontend_route(source: dict) -> str | None:\n    route = source.get(\"route\")\n    if isinstance(route, str) and route in {\n        ROUTE_SPEC_DRIVEN,\n        ROUTE_ABSOLUTE,\n        ROUTE_STANDARD,\n        ROUTE_MISSING,\n    }:\n        return route\n    source_type = source.get(\"type\")\n    if source_type == \"high_fidelity_html\":\n        return ROUTE_ABSOLUTE\n    if source_type == \"standard_html\":\n        return ROUTE_STANDARD\n    return None\n\n\ndef validate_plan_ui_projection(ctx: HookContext) -> int:\n    ui_data, failures = _load_ui_context_for_projection(ctx)\n    if ui_data is None:\n        return failures\n    indexes = ui_context_indexes(ui_data)\n    visual_sources_by_id = {\n        item[\"sourceId\"]: item\n        for item in ui_data.get(\"visualSources\", [])\n        if isinstance(item, dict) and isinstance(item.get(\"sourceId\"), str)\n    }\n    capabilities = [\n        item\n        for item in ui_data.get(\"capabilities\", [])\n        if isinstance(item, dict) and item.get(\"uiRequired\") is not False\n    ]\n\n    plan_data, errors = load_and_validate_plan(plan_json_path(ctx.feature_dir))\n    if errors or plan_data is None:\n        return failures\n\n    raw_tasks = plan_data.get(\"tasks\")\n    if not isinstance(raw_tasks, list):\n        return failures\n\n    feature_ui_required = ui_data.get(\"uiRequired\") is True\n    ui_task_count = 0\n    for index, task in enumerate(raw_tasks):\n        if not isinstance(task, dict):\n            continue\n        task_id = task.get(\"id\") if isinstance(task.get(\"id\"), str) else f\"tasks[{index}]\"\n        task_ui_required = task.get(\"uiRequired\") is True\n        ui_refs = task.get(\"uiRefs\")\n\n        if not feature_ui_required:\n            if task_ui_required:\n                failures += fail_line(ctx, \"plan_ui_task_when_feature_not_ui\", f\" task={task_id}\")\n            if isinstance(ui_refs, dict) and ui_refs:\n                failures += fail_line(ctx, \"plan_ui_refs_when_feature_not_ui\", f\" task={task_id}\")\n            continue\n\n        if not task_ui_required:\n            if isinstance(ui_refs, dict) and ui_refs:\n                failures += fail_line(ctx, \"plan_ui_refs_for_non_ui_task\", f\" task={task_id}\")\n            continue\n\n        if task_ui_required:\n            ui_task_count += 1\n            if not isinstance(ui_refs, dict):\n                failures += fail_line(ctx, \"plan_ui_task_missing_uiRefs\", f\" task={task_id}\")\n                continue\n            for field, known in (\n                (\"pageRefs\", indexes[\"page\"]),\n                (\"interactionRefs\", indexes[\"interaction\"]),\n                (\"visualSourceRefs\", indexes[\"visualSource\"]),\n            ):\n                refs = _string_list_value(ui_refs.get(field))\n                if refs is None:\n                    failures += fail_line(ctx, \"invalid_plan_ui_refs\", f\" task={task_id} field={field}\")\n                    continue\n                if field == \"pageRefs\" and not refs:\n                    failures += fail_line(ctx, \"missing_plan_ui_refs\", f\" task={task_id} field={field}\")\n                for ref in refs:\n                    if ref not in known:\n                        failures += fail_line(ctx, \"unknown_plan_ui_ref\", f\" task={task_id} field={field} ref={ref}\")\n            frontend_route = ui_refs.get(\"frontendRoute\")\n            if not isinstance(frontend_route, str) or frontend_route not in {\n                ROUTE_NONE,\n                ROUTE_SPEC_DRIVEN,\n                ROUTE_ABSOLUTE,\n                ROUTE_STANDARD,\n                ROUTE_MISSING,\n            }:\n                failures += fail_line(ctx, \"invalid_plan_ui_frontend_route\", f\" task={task_id}\")\n                continue\n            visual_refs = _string_list_value(ui_refs.get(\"visualSourceRefs\")) or []\n            task_spec_refs = set(_string_list_value(task.get(\"specRefs\")) or [])\n            matching_capabilities = [\n                capability\n                for capability in capabilities\n                if task_spec_refs.intersection(_string_list_value(capability.get(\"specRefs\")) or [])\n            ]\n            if matching_capabilities and any(\n                \"visualSourceRefs\" in capability for capability in matching_capabilities\n            ):\n                expected_visual_refs = {\n                    ref\n                    for capability in matching_capabilities\n                    for ref in (_string_list_value(capability.get(\"visualSourceRefs\")) or [])\n                }\n                if set(visual_refs) != expected_visual_refs:\n                    failures += fail_line(\n                        ctx,\n                        \"plan_ui_visual_source_projection_mismatch\",\n                        (\n                            f\" task={task_id} expected={','.join(sorted(expected_visual_refs)) or 'none'}\"\n                            f\" actual={','.join(sorted(visual_refs)) or 'none'}\"\n                        ),\n                    )\n                if not expected_visual_refs and frontend_route != ROUTE_SPEC_DRIVEN:\n                    failures += fail_line(\n                        ctx,\n                        \"plan_ui_route_without_visual_source\",\n                        f\" task={task_id} expected={ROUTE_SPEC_DRIVEN} actual={frontend_route}\",\n                    )\n            for visual_ref in visual_refs:\n                visual_source = visual_sources_by_id.get(visual_ref)\n                if visual_source is None:\n                    continue\n                expected_route = _visual_source_expected_frontend_route(visual_source)\n                if expected_route is not None and frontend_route != expected_route:\n                    failures += fail_line(\n                        ctx,\n                        \"plan_ui_frontend_route_mismatch\",\n                        f\" task={task_id} visualSource={visual_ref} expected={expected_route} actual={frontend_route}\",\n                    )\n\n    implementation_scope, _ = load_scope(ctx.feature_dir)\n    selections, _ = resolve_plan_scope(ctx.feature_dir)\n    scenario_selection = selections[\"scenario\"]\n    in_scope_ui = feature_ui_required and implementation_scope != \"backend_only\"\n    if scenario_selection.deferred or scenario_selection.unpartitioned:\n        in_scope_ui = in_scope_ui and any(\n            scenario_selection.included.intersection(_string_list_value(capability.get(\"specRefs\")) or [])\n            for capability in capabilities\n        )\n    if in_scope_ui and ui_task_count == 0:\n        failures += fail_line(ctx, \"plan_ui_required_without_ui_task\")\n    return failures\n\n\ndef _artifact_issue_target(issue: dict, fallback: str) -> str:\n    task_ids = issue.get(\"taskIds\")\n    task_id = \"\"\n    if isinstance(task_ids, list):\n        task_id = \",\".join(str(item) for item in task_ids if item)\n\n    field = issue.get(\"field\")\n    location = \".\".join(\n        item for item in (task_id, str(field) if field else \"\") if item\n    )\n    current_value = issue.get(\"currentValue\")\n    if current_value not in (None, \"\"):\n        return f\"{location} {current_value}\".strip()\n    return location or fallback\n\n\ndef _emit_artifact_issue(ctx: HookContext, issue: dict, fallback: str) -> int:\n    reason = str(issue.get(\"reason\") or \"invalid_artifact_ref\")\n    detail = str(issue.get(\"detail\") or \"\")\n    return fail_line(\n        ctx,\n        reason,\n        f\" {detail}\" if detail else \"\",\n        target=_artifact_issue_target(issue, fallback),\n        fields={\"detail\": detail},\n    )\n\n\ndef _validate_plan_json_traceability(ctx: HookContext, data: dict) -> int:\n    failures = 0\n    spec_ids, spec_failures = collect_spec_definition_index(ctx)\n    # dev.design already validated and locked design.md.  Plan consumes the\n    # snapshot instead of reopening the upstream artifact.\n    design_contract, design_issues = load_confirmed_design_contract(ctx.feature_dir, ctx.slug)\n    failures += spec_failures\n    for issue in design_issues:\n        failures += _emit_artifact_issue(ctx, issue, \"design.md\")\n\n    raw_tasks = data.get(\"tasks\")\n    if not isinstance(raw_tasks, list):\n        return failures\n\n    for index, task in enumerate(raw_tasks):\n        context = f\"tasks[{index}]\"\n        if not isinstance(task, dict):\n            continue\n        task_id = task.get(\"id\") if isinstance(task.get(\"id\"), str) else context\n\n        spec_refs = _string_list_value(task.get(\"specRefs\")) or []\n        req_refs = set(REQ_ID.findall(\" \".join(spec_refs)))\n        scn_refs = _scenario_refs_from_spec_refs(spec_refs)\n        if not req_refs:\n            failures += fail_line(ctx, \"missing_plan_json_requirement_ref\", f\" task={task_id}\", target=task_id)\n        if not scn_refs:\n            failures += fail_line(ctx, \"missing_plan_json_scenario_ref\", f\" task={task_id}\", target=task_id)\n        for req_id in sorted(req_refs):\n            if req_id not in spec_ids[\"REQ\"]:\n                failures += fail_line(\n                    ctx,\n                    \"unknown_plan_json_requirement_ref\",\n                    f\" task={task_id} id={req_id}\",\n                    target=f\"{task_id}.specRefs {req_id}\",\n                )\n        for scn_id in sorted(scn_refs):\n            if scn_id not in spec_ids[\"SCN\"]:\n                failures += fail_line(\n                    ctx,\n                    \"unknown_plan_json_scenario_ref\",\n                    f\" task={task_id} id={scn_id}\",\n                    target=f\"{task_id}.specRefs {scn_id}\",\n                )\n\n        for issue in validate_task_artifact_refs(\n            ctx.feature_dir,\n            task,\n            design_contract=design_contract,\n            check_design_artifact=False,\n        ):\n            failures += _emit_artifact_issue(ctx, issue, task_id)\n    selections, partition_errors = resolve_plan_scope(ctx.feature_dir)\n    for issue in partition_errors:\n        failures += _emit_artifact_issue(ctx, issue, \"IMPLEMENTATION_SCOPE.json\")\n    report = scope_report(selections)\n    if report:\n        info(ctx, \"plan_scope_report \" + json.dumps(report, ensure_ascii=False))\n    for issue in validate_plan_design_coverage(design_contract, raw_tasks, included_ids=selections[\"design\"].included):\n        reason = str(issue.get(\"reason\") or \"\")\n        fallback = {\n            \"missing_design_api_id\": \"API Decisions\",\n            \"missing_design_data_id\": \"Data Decisions\",\n        }.get(reason, \"plan.json\")\n        failures += _emit_artifact_issue(ctx, issue, fallback)\n    return failures\n\n\ndef _plan_task_string_list(task: dict, field: str) -> list[str]:\n    return _string_list_value(task.get(field)) or []\n\n\ndef _spec_scenario_refs_by_path(ctx: HookContext) -> dict[str, set[str]]:\n    refs_by_id: dict[str, set[str]] = {}\n    for spec in spec_files(ctx):\n        rel = spec.relative_to(ctx.feature_dir).as_posix()\n        for scn_id in SPEC_SCENARIO_DEF_RE.findall(read_text(spec)):\n            refs_by_id.setdefault(scn_id, set()).add(f\"{rel}#{scn_id}\")\n    return refs_by_id\n\n\ndef _covered_spec_scenario_refs(spec_refs: list[str], refs_by_id: dict[str, set[str]]) -> set[str]:\n    covered: set[str] = set()\n    for raw_ref in spec_refs:\n        if not isinstance(raw_ref, str):\n            continue\n        path_part, _, anchor = raw_ref.partition(\"#\")\n        scenario_ids = SCN_ID.findall(anchor or raw_ref)\n        if not scenario_ids:\n            continue\n        normalized_path = path_part.strip().replace(\"\\\\\", \"/\")\n        for scn_id in scenario_ids:\n            if normalized_path:\n                covered.add(f\"{normalized_path}#{scn_id}\")\n            elif len(refs_by_id.get(scn_id, set())) == 1:\n                covered.update(refs_by_id[scn_id])\n    return covered\n\n\ndef validate_plan_task_granularity(ctx: HookContext) -> int:\n    plan_json = ctx.file(\"plan.json\")\n    if not ctx.requires_artifact(\"plan.json\") and not is_nonempty(plan_json):\n        info(ctx, \"plan_task_granularity_not_in_contract_degrade\")\n        return 0\n\n    data, errors = load_and_validate_plan(plan_json)\n    failures = 0\n    if errors:\n        for error in errors:\n            failures += fail_line(ctx, \"invalid_plan_json\", f\" detail={error}\", target=str(error))\n        return failures\n    if data is None:\n        return fail_line(ctx, \"missing_plan_json\", target=\"plan.json\")\n\n    raw_tasks = data.get(\"tasks\")\n    if not isinstance(raw_tasks, list):\n        return failures\n    for index, task in enumerate(raw_tasks):\n        if not isinstance(task, dict):\n            continue\n        task_id = task.get(\"id\") if isinstance(task.get(\"id\"), str) else f\"tasks[{index}]\"\n        task_errors = validate_plan_task_granularity_item(task, task_id=task_id)\n        for error in task_errors:\n            failures += fail_line(\n                ctx,\n                error[\"reason\"],\n                \" \" + error.get(\"detail\", \"\"),\n                target=task_id,\n                fields={\"detail\": error.get(\"detail\", \"\")},\n                diagnostics=error,\n            )\n    return failures\n\n\ndef validate_plan_scenario_coverage(ctx: HookContext) -> int:\n    plan_json = ctx.file(\"plan.json\")\n    if not ctx.requires_artifact(\"plan.json\") and not is_nonempty(plan_json):\n        info(ctx, \"plan_scenario_coverage_not_in_contract_degrade\")\n        return 0\n\n    refs_by_id = _spec_scenario_refs_by_path(ctx)\n    selections, partition_errors = resolve_plan_scope(ctx.feature_dir)\n    expected_refs = selections[\"scenario\"].included\n    if partition_errors:\n        return sum(_emit_artifact_issue(ctx, issue, \"IMPLEMENTATION_SCOPE.json\") for issue in partition_errors)\n    if not expected_refs:\n        info(ctx, \"plan_scenario_coverage_no_specs_degrade\")\n        return 0\n\n    data, errors = load_and_validate_plan(plan_json)\n    failures = 0\n    if errors:\n        for error in errors:\n            failures += fail_line(ctx, \"invalid_plan_json\", f\" detail={error}\", target=str(error))\n        return failures\n    if data is None:\n        return fail_line(ctx, \"missing_plan_json\", target=\"plan.json\")\n\n    covered_refs: set[str] = set()\n    raw_tasks = data.get(\"tasks\")\n    if isinstance(raw_tasks, list):\n        for task in raw_tasks:\n            if not isinstance(task, dict):\n                continue\n            covered_refs.update(_covered_spec_scenario_refs(_plan_task_string_list(task, \"specRefs\"), refs_by_id))\n\n    missing_refs = expected_refs - covered_refs\n    if missing_refs:\n        failures += fail_line(\n            ctx,\n            \"missing_plan_scenario_coverage\",\n            f\" ids={','.join(sorted(missing_refs))}\",\n            target=\",\".join(sorted(missing_refs)),\n        )\n    return failures\n\n\ndef validate_plan_ref_resolution(ctx: HookContext) -> int:\n    plan_json = ctx.file(\"plan.json\")\n    if not ctx.requires_artifact(\"plan.json\") and not is_nonempty(plan_json):\n        info(ctx, \"plan_ref_resolution_not_in_contract_degrade\")\n        return 0\n\n    data, errors = load_and_validate_plan(plan_json)\n    failures = 0\n    if errors:\n        for error in errors:\n            failures += fail_line(ctx, \"invalid_plan_json\", f\" detail={error}\", target=str(error))\n        return failures\n    if data is None:\n        return fail_line(ctx, \"missing_plan_json\", target=\"plan.json\")\n\n    tasks = data.get(\"tasks\")\n    if not isinstance(tasks, list):\n        return failures\n    for index, task in enumerate(tasks):\n        if not isinstance(task, dict):\n            continue\n        task_id = task.get(\"id\") if isinstance(task.get(\"id\"), str) else f\"tasks[{index}]\"\n        _, _, ref_errors = resolve_task_refs(ctx.feature_dir, task)\n        for error in ref_errors:\n            detail = error.get(\"detail\", \"\")\n            suffix = f\" task={task_id} detail={detail}\" if detail else f\" task={task_id}\"\n            failures += fail_line(\n                ctx,\n                error.get(\"reason\", \"invalid_artifact_ref\"),\n                suffix,\n                target=task_id,\n                fields={\"detail\": detail},\n            )\n    return failures\n\n\ndef validate_plan_json_initial_tasks(ctx: HookContext) -> int:\n    if not ctx.requires_artifact(\"plan.json\") and not is_nonempty(ctx.file(\"plan.json\")):\n        if is_nonempty(ctx.file(\"PLAN.md\")):\n            return fail_line(\n                ctx,\n                \"missing_plan_json\",\n                \" detail=PLAN.md_present_but_not_machine_source\",\n                target=\"plan.json（当前只有 PLAN.md，它是投影视图不是事实源）\",\n            )\n        info(ctx, \"plan_json_not_in_contract_degrade\")\n        return 0\n    data, errors = load_and_validate_plan(ctx.file(\"plan.json\"), require_initial_status=True)\n    failures = 0\n    for error in errors:\n        failures += fail_line(ctx, \"invalid_plan_json\", f\" detail={error}\", target=str(error))\n    if data is not None and not errors and data.get(\"taskSetStatus\") != \"finalized\":\n        failures += fail_line(ctx, \"plan_task_set_not_finalized\", target=\"plan.json.taskSetStatus\")\n    return failures\n\n\ndef validate_parallel_batch_pipeline_contract(ctx: HookContext) -> int:\n    \"\"\"Require the per-Batch UTest plus E2E-only pipeline contract.\"\"\"\n    plan_json = ctx.file(\"plan.json\")\n    if not ctx.requires_artifact(\"plan.json\") and not is_nonempty(plan_json):\n        info(ctx, \"parallel_batch_pipeline_not_in_contract_degrade\")\n        return 0\n    try:\n        bundle = load_plan_bundle(ctx.feature_dir)\n    except Exception as exc:  # plan_json_contract reports the structural cause too.\n        return fail_line(ctx, \"invalid_parallel_batch_pipeline\", f\" detail={exc}\")\n\n    failures = 0\n    for error in validation_ownership_errors(bundle.root, bundle.batches):\n        failures += fail_line(\n            ctx,\n            \"invalid_parallel_batch_pipeline\",\n            f\" detail={error}\",\n            target=error,\n        )\n    return failures\n\n\ndef validate_plan_json_contract(ctx: HookContext) -> int:\n    plan_json = ctx.file(\"plan.json\")\n    if not ctx.requires_artifact(\"plan.json\") and not is_nonempty(plan_json):\n        if is_nonempty(ctx.file(\"PLAN.md\")):\n            return fail_line(\n                ctx,\n                \"missing_plan_json\",\n                \" detail=PLAN.md_present_but_not_machine_source\",\n                target=\"plan.json（当前只有 PLAN.md，它是投影视图不是事实源）\",\n            )\n        info(ctx, \"plan_json_not_in_contract_degrade\")\n        return 0\n\n    data, errors = load_and_validate_plan(plan_json)\n    failures = 0\n    if errors:\n        for error in errors:\n            failures += fail_line(ctx, \"invalid_plan_json\", f\" detail={error}\", target=str(error))\n        return failures\n    if data is None:\n        return fail_line(ctx, \"missing_plan_json\", target=\"plan.json\")\n    implementation_scope, scope_errors = _implementation_scope_contract_errors(ctx)\n    for error in scope_errors:\n        failures += fail_line(ctx, \"invalid_implementation_scope\", f\" detail={error}\", target=error)\n    if scope_path(ctx.feature_dir).is_file() and not scope_errors:\n        plan_scope = data.get(\"implementationScope\")\n        if plan_scope != implementation_scope:\n            failures += fail_line(\n                ctx,\n                \"plan_implementation_scope_mismatch\",\n                f\" plan={plan_scope!r} feature={implementation_scope!r}\",\n                target=f\"plan={plan_scope!r} feature={implementation_scope!r}\",\n            )\n    failures += _validate_plan_json_traceability(ctx, data)\n    failures += validate_plan_ui_projection(ctx)\n    return failures\n",
  "check.py": "\"\"\"Validate pinned artifact bytes in private scratch space, never the project workspace.\n\nJSON stdin contains only the action's captured bundle and preceding Host artifact\nbundles. Stage selection comes from the locked public action's command.\n\"\"\"\nimport hashlib\nimport json\nimport re\nimport sys\nimport tempfile\nfrom pathlib import Path\nfrom native_context import HookContext, fail_line\nfrom prd_rules import iter_headings, pending_marker_lines, REQUIRED_PRD_SECTIONS, FORMAL_SECTION_MAX_LEVEL\nfrom hooks.source_references import split_source_reference_section, extract_source_references\nfrom hooks.source_context import validate_source_context\nfrom hooks.implementation_scope import load_scope\nfrom artifact_rules import (validate_proposal_contract, validate_specs_contract,\n    validate_capability_spec_correspondence, validate_design_contract,\n    validate_design_contract_lock, validate_ui_context_json, validate_plan_json_initial_tasks,\n    validate_plan_json_contract, validate_plan_task_granularity, validate_plan_scenario_coverage,\n    validate_plan_ref_resolution, validate_parallel_batch_pipeline_contract)\n\nOWNED = {\n    \"prd\": {\"PRD.md\", \"UI_CONTEXT.json\", \"IMPLEMENTATION_SCOPE.json\", \"source-context.json\"},\n    \"specs\": {\"proposal.md\", \"UI_CONTEXT.json\"},\n    \"design\": {\"design.md\", \".design-contract.lock.json\"},\n    \"plan\": {\"plan.json\"},\n}\nREQUIRED = {\n    \"prd\": {\"PRD.md\", \"UI_CONTEXT.json\", \"IMPLEMENTATION_SCOPE.json\"},\n    \"specs\": {\"proposal.md\", \"UI_CONTEXT.json\"},\n    \"design\": {\"design.md\", \".design-contract.lock.json\"},\n    \"plan\": {\"plan.json\"},\n}\n\n\ndef safe_path(name):\n    if (not isinstance(name, str) or len(name) > 240 or \"\\\\\" in name or \":\" in name\n        or any(part in {\"\", \".\", \"..\"} or re.search(r'[<>\"|?*\\x00-\\x1f]|[. ]$', part)\n               or re.match(r'^(con|prn|aux|nul|com[0-9]|lpt[0-9])(?:\\.|$)', part, re.I)\n               for part in name.split(\"/\"))):\n        raise ValueError(\"ARTIFACT_BUNDLE_PATH_INVALID\")\n    return name\n\n\ndef normalized(value):\n    if (not isinstance(value, dict) or not re.fullmatch(r\"[a-zA-Z0-9][\\w.-]{0,63}\", str(value.get(\"feature\", \"\")))\n        or not isinstance(value.get(\"revision\"), int) or isinstance(value.get(\"revision\"), bool)\n        or value[\"revision\"] < 2 or not isinstance(value.get(\"requirements\"), list)\n        or not value[\"requirements\"] or any(not isinstance(row, str) or not row.strip() for row in value[\"requirements\"])):\n        raise ValueError(\"NORMALIZED_REQUIREMENTS_INVALID\")\n    return value\n\n\ndef merge_bundle(files, bundle, stage, feature):\n    if (not isinstance(bundle, dict) or bundle.get(\"feature\") != feature or bundle.get(\"stage\") != stage\n        or not isinstance(bundle.get(\"files\"), dict) or not REQUIRED[stage].issubset(bundle[\"files\"])):\n        raise ValueError(\"ARTIFACT_BUNDLE_INVALID\")\n    for name, content in bundle[\"files\"].items():\n        safe_path(name)\n        if not (name in OWNED[stage] or stage == \"specs\" and re.fullmatch(r\"specs/[a-z0-9]+(?:-[a-z0-9]+)*/spec\\.md\", name)\n                or stage == \"plan\" and re.fullmatch(r\"plans/B\\d{3}/plan\\.json\", name)\n                or stage == \"prd\" and re.fullmatch(r\"sources/SRC-\\d{3}/[a-zA-Z0-9_.-]+\", name)):\n            raise ValueError(\"ARTIFACT_BUNDLE_OWNERSHIP\")\n        if not isinstance(content, str) or not content.strip() or len(content.encode()) > 20000:\n            raise ValueError(\"ARTIFACT_BUNDLE_CONTENT_INVALID\")\n        if name.lower() in {key.lower() for key in files} and name not in files:\n            raise ValueError(\"ARTIFACT_BUNDLE_PATH_COLLISION\")\n        files[name] = content\n\n\ndef check_prd(ctx, requirements):\n    content = ctx.file(\"PRD.md\").read_text(encoding=\"utf-8\")\n    if any(item not in content for item in requirements) or \"来源：NORMALIZED_REQUIREMENTS.json\" not in content:\n        fail_line(ctx, \"AUTOBIZ_PRD_REQUIREMENTS_NOT_COVERED\")\n    headings = [row.text for row in iter_headings(content) if row.level <= FORMAL_SECTION_MAX_LEVEL]\n    markers = headings + re.findall(r\"\\*\\*(.+?)\\*\\*\", content)\n    for section in REQUIRED_PRD_SECTIONS:\n        if not any(section in marker for marker in markers):\n            fail_line(ctx, \"PRD_REQUIRED_SECTION\", section)\n    if pending_marker_lines(content):\n        fail_line(ctx, \"PRD_PENDING_DECISION\")\n    _, scope_errors = load_scope(ctx.feature_dir, required=True)\n    for error in scope_errors:\n        fail_line(ctx, \"IMPLEMENTATION_SCOPE_INVALID\", error)\n    if \"当前实现范围\" not in content:\n        fail_line(ctx, \"PRD_SCOPE_SECTION_MISSING\")\n    errors, warnings = split_source_reference_section(content)\n    for error in errors:\n        fail_line(ctx, \"PRD_SOURCE_REFERENCE_INVALID\", error)\n    ctx.warnings.extend(warnings)\n    refs = {row.source_id for row in extract_source_references(content)}\n    if refs:\n        errors, warnings = validate_source_context(ctx.feature_dir, refs)\n        for error in errors:\n            fail_line(ctx, \"PRD_SOURCE_CONTEXT_INVALID\", error)\n        ctx.warnings.extend(warnings)\n    validate_ui_context_json(ctx)\n\n\ndef run(request):\n    stage = request.get(\"stage\")\n    if stage == \"repair-evidence\":\n        from repair import check\n        return check(request)\n    if stage in {\"cicd\", \"archive\"}:\n        from ops import check\n        return check(request)\n    if stage == \"performance\":\n        from performance import check\n        return check(request.get(\"current\", {}))\n    if stage == \"command-policy\":\n        from hooks.compile_command_policy import _production_compile_argv\n        from hooks.utest_command_policy import command_executes_tests\n        command = request.get(\"current\", {})\n        argv = command.get(\"argv\")\n        if not isinstance(argv, list) or not argv or len(argv) > 64 or any(not isinstance(arg, str) or not arg or len(arg) > 1024 for arg in argv):\n            raise ValueError(\"CODE_COMMAND_INVALID\")\n        passed = (_production_compile_argv(argv) if command.get(\"phase\") == \"compile\"\n                  else command_executes_tests(command) if command.get(\"phase\") in {\"test\", \"e2e\"} else False)\n        from hooks.plan_write_ownership import is_test_asset_path\n        paths = command.get(\"changedPaths\", [])\n        if not isinstance(paths, list) or any(not isinstance(path, str) for path in paths):\n            raise ValueError(\"CODE_CHANGED_PATHS_INVALID\")\n        ownership = all(not is_test_asset_path(path) for path in paths) if command.get(\"phase\") == \"compile\" else all(is_test_asset_path(path) for path in paths)\n        protected = any(path.startswith((\".devclaw/\", \".cmbcoworkagent/\", \".git/\")) or path in {\n            \"NORMALIZED_REQUIREMENTS.json\", \"PRD.bundle.json\", \"SPECS.bundle.json\", \"DESIGN.bundle.json\",\n            \"PLAN.bundle.json\", \"CODE_RESULT.json\", \"CICD.bundle.json\", \"ARCHIVE.bundle.json\"} for path in paths)\n        return {\"passed\": passed and ownership and not protected,\n            \"testFiles\": [path for path in command.get(\"trackedPaths\", []) if is_test_asset_path(path)],\n            \"errors\": ([] if passed else [{\"code\": \"CODE_COMMAND_POLICY_DENIED\"}])\n                + ([] if ownership else [{\"code\": \"CODE_PRODUCTION_TEST_WRITE_BOUNDARY\"}])\n                + ([{\"code\": \"CODE_HOST_ARTIFACT_WRITE_DENIED\"}] if protected else []), \"warnings\": []}\n    if stage not in {\"convert\", \"prd\", \"specs\", \"design\", \"plan\"}:\n        raise ValueError(\"STAGE_UNSUPPORTED\")\n    upstream = normalized(request[\"current\"] if stage == \"convert\" else request[\"normalized\"])\n    if stage == \"convert\":\n        return {\"passed\": True, \"errors\": [], \"warnings\": []}\n    feature = upstream[\"feature\"]\n    files = {\"NORMALIZED_REQUIREMENTS.json\": json.dumps(upstream, ensure_ascii=False)}\n    order = [\"prd\", \"specs\", \"design\", \"plan\"]\n    for entry in order[:order.index(stage) + 1]:\n        merge_bundle(files, request[\"current\"] if entry == stage else request[entry], entry, feature)\n    if len(files) > 40 or sum(len(text.encode()) for text in files.values()) > 100000:\n        raise ValueError(\"ARTIFACT_BUNDLE_LIMIT\")\n    with tempfile.TemporaryDirectory(prefix=\"autobiz-native-check-\") as directory:\n        root = Path(directory) / feature\n        root.mkdir()\n        for name, content in files.items():\n            path = root / name\n            path.parent.mkdir(parents=True, exist_ok=True)\n            path.write_text(content, encoding=\"utf-8\", newline=\"\\n\")\n        ctx = HookContext(root, feature, stage)\n        check_prd(ctx, upstream[\"requirements\"])\n        if stage in {\"specs\", \"design\", \"plan\"}:\n            validate_proposal_contract(ctx)\n            validate_specs_contract(ctx)\n            validate_capability_spec_correspondence(ctx)\n        if stage in {\"design\", \"plan\"}:\n            validate_design_contract(ctx)\n            validate_design_contract_lock(ctx)\n        if stage == \"plan\":\n            validate_plan_json_initial_tasks(ctx)\n            validate_plan_json_contract(ctx)\n            validate_plan_task_granularity(ctx)\n            validate_plan_scenario_coverage(ctx)\n            validate_plan_ref_resolution(ctx)\n            validate_parallel_batch_pipeline_contract(ctx)\n        return {\"passed\": not ctx.errors, \"errors\": ctx.errors, \"warnings\": ctx.warnings,\n                \"inputSha256\": hashlib.sha256(json.dumps(request[\"current\"], ensure_ascii=False, sort_keys=True, separators=(\",\", \":\")).encode()).hexdigest()}\n\n\nif __name__ == \"__main__\":\n    try:\n        raw = sys.stdin.read(120001)\n        if len(raw.encode()) > 120000:\n            raise ValueError(\"ARTIFACT_BUNDLE_LIMIT\")\n        result = run(json.loads(raw))\n    except Exception as error:\n        result = {\"passed\": False, \"errors\": [{\"code\": type(error).__name__, \"detail\": str(error)}], \"warnings\": []}\n    print(json.dumps(result, ensure_ascii=False))\n    sys.exit(0 if result[\"passed\"] else 1)\n",
  "hooks/artifact_ref_validator.py": "\"\"\"Read-only rules extracted from hooks/artifact_ref_validator.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nimport hashlib\nimport re\nfrom pathlib import Path\nfrom typing import Any\nfrom hooks.spec_contract import spec_heading\n\nANCHOR_RE = re.compile(r\"^(REQ|SCN|API|DATA|D)-\\d{3}$\")\n\n\nDESIGN_API_DEF_RE = re.compile(r\"^\\|\\s*(API-\\d{3})\\s*\\|\", re.MULTILINE)\n\n\nDESIGN_DATA_DEF_RE = re.compile(r\"^\\|\\s*(DATA-\\d{3})\\s*\\|\", re.MULTILINE)\n\n\nDESIGN_DECISION_DEF_RE = re.compile(r\"^\\|\\s*(D-\\d{3})\\s*\\|\", re.MULTILINE)\n\n\nPENDING_CELL_RE = re.compile(r\"\\|\\s*(待确认|读码差异)\\s*\\|\")\n\n\ndef design_marker_value(text: str, marker: str) -> bool | None:\n    \"\"\"Read a boolean Design marker without accepting template placeholders.\n\n    The marker is a line-level contract. Stripping Markdown bold markers first\n    makes both ``- **marker:** false`` and plain ``- marker: false`` valid,\n    while a template value such as ``[true/false]`` cannot backtrack into a\n    false positive.\n    \"\"\"\n    marker_re = re.compile(rf\"^{re.escape(marker)}\\s*:\\s*(true|false)$\", re.IGNORECASE)\n    for raw_line in text.splitlines():\n        line = raw_line.strip()\n        if len(line) >= 2 and line[0] in \"-*+\" and line[1].isspace():\n            line = line[2:].strip()\n        line = line.replace(\"**\", \"\")\n        match = marker_re.fullmatch(line)\n        if match:\n            return match.group(1).lower() == \"true\"\n    return None\n\n\ndef _contract_error(reason: str, detail: str = \"\", suggestion: str = \"\") -> dict[str, Any]:\n    issue: dict[str, Any] = {\n        \"reason\": reason,\n        \"repairTarget\": \"design_revision\",\n        \"repairable\": False,\n    }\n    if detail:\n        issue[\"detail\"] = detail\n    if suggestion:\n        issue[\"repairSuggestion\"] = suggestion\n    return issue\n\n\ndef load_design_contract(base: Path) -> tuple[dict[str, Any], list[dict[str, Any]]]:\n    \"\"\"Load the confirmed design as the sole source of Plan reference IDs.\"\"\"\n\n    path = base / \"design.md\"\n    empty = {\n        \"sha256\": \"\",\n        \"ids\": {\"API\": set(), \"DATA\": set(), \"D\": set()},\n        \"noHttpApi\": False,\n        \"noSql\": False,\n    }\n    if not path.is_file() or path.stat().st_size <= 0:\n        return empty, [_contract_error(\n            \"missing_design\",\n            suggestion=\"需要先创建 design.md 文件，包含 API Decisions 和 Data Decisions 表格\"\n        )]\n    try:\n        raw = path.read_bytes()\n        text = raw.decode(\"utf-8\")\n    except (OSError, UnicodeDecodeError) as exc:\n        return empty, [_contract_error(\n            \"invalid_design_contract\",\n            detail=f\"error={exc}\",\n            suggestion=\"检查 design.md 文件编码是否为 UTF-8，文件是否损坏\"\n        )]\n\n    api_ids = DESIGN_API_DEF_RE.findall(text)\n    data_ids = DESIGN_DATA_DEF_RE.findall(text)\n    decision_ids = DESIGN_DECISION_DEF_RE.findall(text)\n    errors: list[dict[str, Any]] = []\n    for ids, reason in (\n        (api_ids, \"duplicate_design_api_id\"),\n        (data_ids, \"duplicate_design_data_id\"),\n        (decision_ids, \"duplicate_design_decision_id\"),\n    ):\n        if len(ids) != len(set(ids)):\n            duplicates = [id_ for id_ in set(ids) if ids.count(id_) > 1]\n            errors.append(_contract_error(\n                reason,\n                detail=f\"duplicates={','.join(duplicates)}\",\n                suggestion=f\"在 design.md 中删除重复的 ID 定义：{', '.join(duplicates)}\"\n            ))\n\n    no_http_api = design_marker_value(text, \"x-auto-no-http-api\")\n    no_sql = design_marker_value(text, \"x-auto-no-sql\")\n    if no_http_api is None:\n        errors.append(_contract_error(\n            \"missing_design_api_marker\",\n            suggestion=\"在 design.md 中添加 API 标记行：`- x-auto-no-http-api: false` 或 `true`\"\n        ))\n    if no_sql is None:\n        errors.append(_contract_error(\n            \"missing_design_data_marker\",\n            suggestion=\"在 design.md 中添加数据标记行：`- x-auto-no-sql: false` 或 `true`\"\n        ))\n    if no_http_api is True and api_ids:\n        errors.append(_contract_error(\n            \"design_api_marker_conflicts_with_definitions\",\n            \"x-auto-no-http-api=true cannot coexist with API Decisions rows\",\n            suggestion=f\"将 x-auto-no-http-api 改为 false，或删除 API Decisions 表格中的 {len(api_ids)} 行定义\"\n        ))\n    if no_sql is True and data_ids:\n        errors.append(_contract_error(\n            \"design_data_marker_conflicts_with_definitions\",\n            \"x-auto-no-sql=true cannot coexist with Data Decisions rows\",\n            suggestion=f\"将 x-auto-no-sql 改为 false，或删除 Data Decisions 表格中的 {len(data_ids)} 行定义\"\n        ))\n    pending_matches = PENDING_CELL_RE.findall(text)\n    pending_count = len(pending_matches)\n    if pending_count:\n        # 提取待确认项所在的行号和上下文\n        lines = text.splitlines()\n        pending_locations = []\n        for i, line in enumerate(lines, 1):\n            if PENDING_CELL_RE.search(line):\n                pending_locations.append(f\"第 {i} 行\")\n                if len(pending_locations) >= 5:  # 最多展示前5个位置\n                    pending_locations.append(f\"...还有 {pending_count - 5} 处\")\n                    break\n\n        location_info = \"，位置：\" + \"、\".join(pending_locations) if pending_locations else \"\"\n        errors.append(_contract_error(\n            \"design_has_pending_cells\",\n            f\"count={pending_count}\",\n            suggestion=f\"design.md 中有 {pending_count} 个单元格包含「待确认」或「读码差异」{location_info}。请逐条与用户确认后，将单元格内容改为具体值并标记为「已确认」\"\n        ))\n\n    return {\n        \"sha256\": hashlib.sha256(raw).hexdigest(),\n        \"ids\": {\n            \"API\": set(api_ids),\n            \"DATA\": set(data_ids),\n            \"D\": set(decision_ids),\n        },\n        \"noHttpApi\": no_http_api is True,\n        \"noSql\": no_sql is True,\n    }, errors\n\n\ndef design_contract_snapshot(contract: dict[str, Any]) -> dict[str, Any]:\n    ids = contract.get(\"ids\") if isinstance(contract.get(\"ids\"), dict) else {}\n    return {\n        \"sha256\": contract.get(\"sha256\"),\n        \"apiIds\": sorted(ids.get(\"API\", set())),\n        \"dataIds\": sorted(ids.get(\"DATA\", set())),\n        \"decisionIds\": sorted(ids.get(\"D\", set())),\n        \"noHttpApi\": contract.get(\"noHttpApi\") is True,\n        \"noSql\": contract.get(\"noSql\") is True,\n    }\n\n\ndef _unknown_design_id_issue(\n    task_id: str,\n    field: str,\n    index: int,\n    value: str,\n    kind: str,\n    repair_target: str,\n) -> dict[str, Any]:\n    kind_label = {\"API\": \"接口\", \"DATA\": \"数据\", \"D\": \"决策\"}.get(kind, kind)\n    return {\n        \"reason\": f\"unknown_plan_json_{kind.lower()}_ref\",\n        \"detail\": f\"task={task_id};id={value};design_is_source_of_truth;repair_plan_not_design\",\n        \"taskIds\": [task_id],\n        \"field\": f\"{field}[{index}]\",\n        \"currentValue\": value,\n        \"repairTarget\": repair_target,\n        \"designMutationAllowed\": False,\n        \"repairSuggestion\": f\"任务 {task_id} 引用了 design.md 中不存在的{kind_label} ID：{value}。请在 Plan v2 输入的 refs 中删除该引用，或先在 design.md 的对应表格中添加该 ID 定义\"\n    }\n\n\ndef _reference_validation_contract(\n    contract: dict[str, Any] | None,\n) -> dict[str, Any] | None:\n    \"\"\"Return a contract that is safe for typed-reference validation.\n\n    Callers report an invalid or missing Design lock separately.  Reference\n    validation must nevertheless remain total: a partial lock used to raise a\n    KeyError and hid every actionable bad reference behind the first failure.\n    Treat an unusable snapshot as an empty, non-marker contract, so each\n    supplied typed ID is reported as unresolved while the lock diagnostic is\n    preserved by the caller.\n    \"\"\"\n\n    if contract is None:\n        return None\n    ids = contract.get(\"ids\") if isinstance(contract, dict) else None\n    if isinstance(ids, dict) and all(\n        isinstance(ids.get(kind), (set, list, tuple))\n        for kind in (\"API\", \"DATA\", \"D\")\n    ):\n        return contract\n    return {\n        \"ids\": {\"API\": set(), \"DATA\": set(), \"D\": set()},\n        \"noHttpApi\": False,\n        \"noSql\": False,\n    }\n\n\ndef validate_task_design_contract(\n    contract: dict[str, Any],\n    task: dict[str, Any],\n) -> list[dict[str, Any]]:\n    \"\"\"Validate task-owned typed references against the confirmed Design.\"\"\"\n\n    contract = _reference_validation_contract(contract) or {\n        \"ids\": {\"API\": set(), \"DATA\": set(), \"D\": set()},\n        \"noHttpApi\": False,\n        \"noSql\": False,\n    }\n    task_id = str(task.get(\"id\", \"task\"))\n    errors: list[dict[str, Any]] = []\n    field_contracts = (\n        (\"apiIds\", \"API\", \"api\", \"task_group\"),\n        (\"dataIds\", \"DATA\", \"data\", \"task_detail\"),\n        (\"decisionIds\", \"D\", \"decision\", \"task_detail\"),\n    )\n    for field, id_kind, reason_kind, repair_target in field_contracts:\n        values = task.get(field) if isinstance(task.get(field), list) else []\n        for index, value in enumerate(values):\n            if not isinstance(value, str):\n                continue\n            if id_kind == \"API\" and contract.get(\"noHttpApi\") is True:\n                errors.append({\n                    \"reason\": \"plan_api_ref_forbidden_by_design_marker\",\n                    \"detail\": f\"task={task_id};id={value};x-auto-no-http-api=true\",\n                    \"taskIds\": [task_id],\n                    \"field\": f\"{field}[{index}]\",\n                    \"currentValue\": value,\n                    \"repairTarget\": repair_target,\n                    \"designMutationAllowed\": False,\n                })\n            elif id_kind == \"DATA\" and contract.get(\"noSql\") is True:\n                errors.append({\n                    \"reason\": \"plan_data_ref_forbidden_by_design_marker\",\n                    \"detail\": f\"task={task_id};id={value};x-auto-no-sql=true\",\n                    \"taskIds\": [task_id],\n                    \"field\": f\"{field}[{index}]\",\n                    \"currentValue\": value,\n                    \"repairTarget\": repair_target,\n                    \"designMutationAllowed\": False,\n                })\n            elif value not in contract[\"ids\"][id_kind]:\n                errors.append(_unknown_design_id_issue(\n                    task_id, field, index, value, reason_kind, repair_target\n                ))\n    return errors\n\n\ndef _design_ids_from_refs(task: dict[str, Any]) -> dict[str, set[str]]:\n    result = {\"API\": set(), \"DATA\": set(), \"D\": set()}\n    for ref in task.get(\"designRefs\", []):\n        if not isinstance(ref, str):\n            continue\n        _, marker, anchor = ref.partition(\"#\")\n        if not marker:\n            continue\n        if anchor.startswith(\"API-\"):\n            result[\"API\"].add(anchor)\n        elif anchor.startswith(\"DATA-\"):\n            result[\"DATA\"].add(anchor)\n        elif anchor.startswith(\"D-\"):\n            result[\"D\"].add(anchor)\n    return result\n\n\ndef validate_plan_design_coverage(\n    contract: dict[str, Any],\n    tasks: list[dict[str, Any]],\n    *,\n    included_ids: set[str] | None = None,\n) -> list[dict[str, Any]]:\n    \"\"\"Require every in-scope Design ID to be covered without inventing new IDs.\n\n    ``included_ids`` is the slice this round delivers; IDs a later round owns are\n    not missing coverage, so the Design keeps them instead of being edited down.\n    \"\"\"\n\n    contract = _reference_validation_contract(contract) or {\n        \"ids\": {\"API\": set(), \"DATA\": set(), \"D\": set()},\n        \"noHttpApi\": False,\n        \"noSql\": False,\n    }\n    covered = {\"API\": set(), \"DATA\": set(), \"D\": set()}\n    for task in tasks:\n        covered[\"API\"].update(\n            item for item in task.get(\"apiIds\", []) if isinstance(item, str)\n        )\n        covered[\"DATA\"].update(\n            item for item in task.get(\"dataIds\", []) if isinstance(item, str)\n        )\n        covered[\"D\"].update(\n            item for item in task.get(\"decisionIds\", []) if isinstance(item, str)\n        )\n        refs = _design_ids_from_refs(task)\n        for kind in covered:\n            # A designRef is only coverage evidence after it resolves to an\n            # ID that the current Design actually defines. Invalid anchors\n            # must never make a Design row appear covered.\n            covered[kind].update(refs[kind] & contract[\"ids\"][kind])\n\n    errors: list[dict[str, Any]] = []\n    coverage_rules = (\n        (\"API\", \"api\", contract.get(\"noHttpApi\") is True, \"task_group\"),\n        (\"DATA\", \"data\", contract.get(\"noSql\") is True, \"task_detail\"),\n        (\"D\", \"decision\", False, \"task_detail\"),\n    )\n    for id_kind, reason_kind, disabled, repair_target in coverage_rules:\n        known = contract[\"ids\"][id_kind]\n        if disabled and not known:\n            continue\n        if id_kind in {\"API\", \"DATA\"} and not known:\n            errors.append({\n                \"reason\": f\"missing_design_{reason_kind}_id\",\n                \"repairTarget\": \"design_revision\",\n                \"repairable\": False,\n            })\n            continue\n        required = known if included_ids is None else known & included_ids\n        for value in sorted(required - covered[id_kind]):\n            errors.append({\n                \"reason\": f\"missing_plan_json_{reason_kind}_coverage\",\n                \"detail\": f\"id={value};design_is_source_of_truth;attach_existing_id_to_relevant_task\",\n                \"field\": \"apiIds\" if id_kind == \"API\" else \"dataIds\" if id_kind == \"DATA\" else \"decisionIds\",\n                \"currentValue\": value,\n                \"repairTarget\": repair_target,\n                \"designMutationAllowed\": False,\n            })\n    return errors\n\n\nclass ArtifactRefError(Exception):\n    \"\"\"Raised when an artifact reference is invalid.\"\"\"\n\n    def __init__(self, reason: str, detail: str):\n        self.reason = reason\n        self.detail = detail\n        super().__init__(f\"{reason}: {detail}\")\n\n\ndef _split_ref(ref: str) -> tuple[str, str]:\n    \"\"\"Split reference into path and anchor, raising if format is invalid.\"\"\"\n    path_part, marker, anchor = ref.partition(\"#\")\n    if not marker:\n        raise ArtifactRefError(\n            \"invalid_artifact_ref_format\",\n            f\"引用缺少 # 符号: {ref}\",\n        )\n    anchor = anchor.strip()\n    if not anchor:\n        raise ArtifactRefError(\n            \"invalid_artifact_ref_format\",\n            f\"引用缺少 anchor: {ref}\",\n        )\n    if not ANCHOR_RE.fullmatch(anchor):\n        raise ArtifactRefError(\n            \"invalid_artifact_ref_format\",\n            f\"引用 anchor 格式非法: {ref} (期望格式: REQ-001, SCN-002, API-003, DATA-004, D-005)\",\n        )\n    return path_part.strip(), anchor\n\n\ndef _inside_base(candidate: Path, base: Path) -> bool:\n    try:\n        candidate.relative_to(base)\n        return True\n    except ValueError:\n        return False\n\n\ndef _safe_ref_path(base: Path, raw_path: str, ref: str) -> Path:\n    \"\"\"Resolve reference path safely within base directory.\"\"\"\n    if not raw_path:\n        raise ArtifactRefError(\n            \"invalid_artifact_ref_format\",\n            f\"引用缺少相对路径: {ref}\",\n        )\n    path = Path(raw_path)\n    if path.is_absolute():\n        raise ArtifactRefError(\n            \"invalid_artifact_ref_format\",\n            f\"引用必须是产物目录相对路径，不允许绝对路径: {ref}\",\n        )\n    candidate = (base / path).resolve(strict=False)\n    resolved_base = base.resolve(strict=False)\n    if not _inside_base(candidate, resolved_base):\n        raise ArtifactRefError(\n            \"invalid_artifact_ref_format\",\n            f\"引用路径越界: {ref}\",\n        )\n    return candidate\n\n\ndef _find_unique_anchor_file(base: Path, anchor: str, *, design: bool) -> Path:\n    \"\"\"Find the unique file containing the anchor.\"\"\"\n    if design:\n        return base / \"design.md\"\n\n    candidates = sorted((base / \"specs\").glob(\"**/*.md\"))\n    matches: list[Path] = []\n\n    for candidate in candidates:\n        try:\n            text = candidate.read_text(encoding=\"utf-8\")\n        except OSError:\n            continue\n\n        if _extract_spec_snippet(text, anchor) is not None:\n            matches.append(candidate)\n\n    if len(matches) == 1:\n        return matches[0]\n    if not matches:\n        raise ArtifactRefError(\n            \"missing_ref_anchor\",\n            f\"短引用未找到 anchor: #{anchor}\",\n        )\n    raise ArtifactRefError(\n        \"ambiguous_ref_anchor\",\n        f\"短引用 anchor 不唯一: #{anchor} (在 {len(matches)} 个文件中找到)\",\n    )\n\n\ndef _extract_spec_snippet(text: str, anchor: str) -> str | None:\n    \"\"\"Extract spec snippet for REQ/SCN anchors.\"\"\"\n    if not anchor.startswith((\"REQ-\", \"SCN-\")):\n        return None\n    match = spec_heading(text, anchor)\n    return text[match.start():match.end()] if match else None\n\n\ndef _extract_design_snippet(text: str, anchor: str) -> str | None:\n    \"\"\"Extract design snippet for API/DATA/D anchors from table rows.\"\"\"\n    lines = text.splitlines()\n    row_re = re.compile(rf\"^\\|\\s*{re.escape(anchor)}\\s*\\|\")\n\n    for line in lines:\n        if row_re.match(line):\n            return line\n\n    return None\n\n\ndef validate_artifact_ref(\n    base: Path,\n    ref: str,\n    *,\n    design: bool,\n    cache: dict[str, bool] | None = None,\n) -> None:\n    \"\"\"Validate a single artifact reference.\n\n    Args:\n        base: Feature directory base path\n        ref: Reference string (e.g., \"design.md#API-001\" or \"#REQ-001\")\n        design: True for designRefs, False for specRefs\n        cache: Optional cache dict (NOT USED - reserved for future safe implementation)\n\n    Raises:\n        ArtifactRefError: If reference is invalid, file missing, or anchor not found\n\n    Note: Cache parameter is accepted but not used. Format and type checks must always\n    run; file existence and anchor presence can change between validations. A safe cache\n    would need: refType + resolvedPath + fileSha256 + anchor as the key.\n    \"\"\"\n    # Parse format (always validate - cannot be cached safely)\n    raw_path, anchor = _split_ref(ref)\n\n    # Check anchor type matches ref type (always validate - cannot be cached safely)\n    if design and not (anchor.startswith(\"API-\") or anchor.startswith(\"DATA-\") or anchor.startswith(\"D-\")):\n        raise ArtifactRefError(\n            \"invalid_artifact_ref_type\",\n            f\"designRefs 只允许 API/DATA/D anchor: {ref}\",\n        )\n    if not design and not (anchor.startswith(\"REQ-\") or anchor.startswith(\"SCN-\")):\n        raise ArtifactRefError(\n            \"invalid_artifact_ref_type\",\n            f\"specRefs 只允许 REQ/SCN anchor: {ref}\",\n        )\n\n    # Resolve path (always resolve - path resolution can change)\n    if raw_path:\n        path = _safe_ref_path(base, raw_path, ref)\n    else:\n        path = _find_unique_anchor_file(base, anchor, design=design)\n\n    # Check file exists (always check - file can be deleted)\n    if not path.is_file():\n        raise ArtifactRefError(\n            \"missing_ref_file\",\n            f\"引用文件不存在: {ref} (解析为 {path})\",\n        )\n\n    # Check anchor exists in file (always check - file content can change)\n    try:\n        text = path.read_text(encoding=\"utf-8\")\n    except OSError as exc:\n        raise ArtifactRefError(\n            \"missing_ref_file\",\n            f\"无法读取引用文件: {ref} ({exc})\",\n        )\n\n    extracted = _extract_design_snippet(text, anchor) if design else _extract_spec_snippet(text, anchor)\n    if extracted is None:\n        raise ArtifactRefError(\n            \"missing_ref_anchor\",\n            f\"引用 anchor 不存在: {ref} (文件 {path.name} 中未找到 {anchor})\",\n        )\n\n\ndef validate_task_artifact_refs(\n    base: Path,\n    task: dict[str, Any],\n    cache: dict[str, bool] | None = None,\n    design_contract: dict[str, Any] | None = None,\n    *,\n    check_design_artifact: bool = True,\n) -> list[dict[str, Any]]:\n    \"\"\"Validate all artifact references in a task.\n\n    Args:\n        cache: Accepted but not used (reserved for future safe implementation)\n\n    Returns:\n        List of error dicts with 'reason' and 'detail' keys\n    \"\"\"\n    errors: list[dict[str, Any]] = []\n    task_id = str(task.get(\"id\", \"task\"))\n\n    contract = _reference_validation_contract(design_contract)\n\n    # Validate designRefs.  Design owns validation of design.md itself.  Plan\n    # consumes the locked contract snapshot and therefore can validate the\n    # logical ref shape/ID without reopening the Design artifact.\n    for index, ref in enumerate(task.get(\"designRefs\", [])):\n        if not isinstance(ref, str):\n            continue\n        try:\n            raw_path, anchor = _split_ref(ref)\n            if not (anchor.startswith(\"API-\") or anchor.startswith(\"DATA-\") or anchor.startswith(\"D-\")):\n                raise ArtifactRefError(\"invalid_artifact_ref_type\", f\"designRefs 只允许 API/DATA/D anchor: {ref}\")\n            if not check_design_artifact and raw_path not in {\"\", \"design.md\"}:\n                raise ArtifactRefError(\"invalid_artifact_ref_format\", f\"designRefs 必须引用 design.md: {ref}\")\n            if check_design_artifact:\n                validate_artifact_ref(base, ref, design=True, cache=None)\n        except ArtifactRefError as exc:\n            errors.append({\n                \"reason\": exc.reason,\n                \"detail\": f\"task={task_id};ref={ref};{exc.detail}\",\n                \"taskIds\": [task_id],\n                \"field\": f\"designRefs[{index}]\",\n                \"currentValue\": ref,\n                \"repairTarget\": \"task_detail\",\n            })\n            continue\n        kind = \"API\" if anchor.startswith(\"API-\") else \"DATA\" if anchor.startswith(\"DATA-\") else \"D\"\n        if contract is not None:\n            if kind == \"API\" and contract.get(\"noHttpApi\") is True:\n                errors.append({\n                    \"reason\": \"plan_api_ref_forbidden_by_design_marker\",\n                    \"detail\": f\"task={task_id};ref={ref};x-auto-no-http-api=true\",\n                    \"taskIds\": [task_id],\n                    \"field\": f\"designRefs[{index}]\",\n                    \"currentValue\": ref,\n                    \"repairTarget\": \"task_detail\",\n                    \"designMutationAllowed\": False,\n                })\n            elif kind == \"DATA\" and contract.get(\"noSql\") is True:\n                errors.append({\n                    \"reason\": \"plan_data_ref_forbidden_by_design_marker\",\n                    \"detail\": f\"task={task_id};ref={ref};x-auto-no-sql=true\",\n                    \"taskIds\": [task_id],\n                    \"field\": f\"designRefs[{index}]\",\n                    \"currentValue\": ref,\n                    \"repairTarget\": \"task_detail\",\n                    \"designMutationAllowed\": False,\n                })\n            elif anchor not in contract[\"ids\"][kind]:\n                errors.append(_unknown_design_id_issue(\n                    task_id,\n                    \"designRefs\",\n                    index,\n                    anchor,\n                    kind.lower(),\n                    \"task_detail\",\n                ))\n\n    # Validate specRefs (beyond basic structure - only format and file existence)\n    for index, ref in enumerate(task.get(\"specRefs\", [])):\n        if not isinstance(ref, str):\n            continue\n        try:\n            validate_artifact_ref(base, ref, design=False, cache=None)\n        except ArtifactRefError as exc:\n            errors.append({\n                \"reason\": exc.reason,\n                \"detail\": f\"task={task_id};ref={ref};{exc.detail}\",\n                \"taskIds\": [task_id],\n                \"field\": f\"specRefs[{index}]\",\n                \"currentValue\": ref,\n                \"repairTarget\": \"task_group\",\n            })\n\n    # sourceRefs is writer-owned and records source IDs projected from Specs.\n    # Source availability is deliberately non-blocking: an external document\n    # may legitimately be absent or never have been supplied.\n    source_refs = task.get(\"sourceRefs\", [])\n    if not isinstance(source_refs, list):\n        errors.append({\n            \"reason\": \"plan_source_refs_invalid\",\n            \"detail\": f\"task={task_id};sourceRefs_must_be_array\",\n            \"taskIds\": [task_id],\n            \"field\": \"sourceRefs\",\n            \"repairTarget\": \"task_group\",\n        })\n    if contract is not None:\n        errors.extend(validate_task_design_contract(contract, task))\n\n    return errors\n",
  "hooks/code_task_context.py": "\"\"\"Read-only rules extracted from hooks/code_task_context.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nimport re\nfrom pathlib import Path\nfrom typing import Any\nfrom hooks.spec_contract import spec_heading\nfrom hooks.source_context import load_source_context, source_index\nclass WriterError(ValueError): pass\n\nANCHOR_RE = re.compile(r\"^(REQ|SCN|API|DATA|D)-\\d{3}$\")\n\n\ndef _split_ref(ref: str) -> tuple[str, str]:\n    path_part, marker, anchor = ref.partition(\"#\")\n    if not marker or not anchor.strip():\n        raise WriterError(f\"引用缺少 anchor: {ref}\")\n    anchor = anchor.strip()\n    if not ANCHOR_RE.fullmatch(anchor):\n        raise WriterError(f\"引用 anchor 格式非法: {ref}\")\n    return path_part.strip(), anchor\n\n\ndef _inside_base(candidate: Path, base: Path) -> bool:\n    try:\n        candidate.relative_to(base)\n        return True\n    except ValueError:\n        return False\n\n\ndef _safe_ref_path(base: Path, raw_path: str, ref: str) -> Path:\n    if not raw_path:\n        raise WriterError(f\"引用缺少相对路径: {ref}\")\n    path = Path(raw_path)\n    if path.is_absolute():\n        raise WriterError(f\"引用必须是产物目录相对路径，不允许绝对路径: {ref}\")\n    candidate = (base / path).resolve(strict=False)\n    resolved_base = base.resolve(strict=False)\n    if not _inside_base(candidate, resolved_base):\n        raise WriterError(f\"引用路径越界: {ref}\")\n    return candidate\n\n\ndef _line_number(text: str, offset: int) -> int:\n    return text.count(\"\\n\", 0, offset) + 1\n\n\ndef _find_unique_anchor_file(base: Path, anchor: str, *, design: bool) -> Path:\n    if design:\n        return base / \"design.md\"\n    candidates = sorted((base / \"specs\").glob(\"**/*.md\"))\n    matches: list[Path] = []\n    for candidate in candidates:\n        try:\n            text = candidate.read_text(encoding=\"utf-8\")\n        except OSError:\n            continue\n        if _extract_spec_snippet(text, anchor) is not None:\n            matches.append(candidate)\n    if len(matches) == 1:\n        return matches[0]\n    if not matches:\n        raise WriterError(f\"短引用未找到 anchor: #{anchor}\")\n    raise WriterError(f\"短引用 anchor 不唯一: #{anchor}\")\n\n\ndef _resolve_path(base: Path, ref: str, anchor: str, *, design: bool) -> Path:\n    raw_path, _ = _split_ref(ref)\n    if not raw_path:\n        return _find_unique_anchor_file(base, anchor, design=design).resolve(strict=False)\n    return _safe_ref_path(base, raw_path, ref)\n\n\ndef _extract_spec_snippet(text: str, anchor: str) -> tuple[str, int] | None:\n    if not anchor.startswith((\"REQ-\", \"SCN-\")):\n        return None\n    match = spec_heading(text, anchor)\n    if not match:\n        return None\n    # Stop at the next peer or enclosing section, including mixed ID styles.\n    end_re = re.compile(r\"^#{1,4}\\s+\\S\", re.MULTILINE)\n    end_match = end_re.search(text, match.end())\n    end = end_match.start() if end_match else len(text)\n    snippet = text[match.start() : end].strip()\n    return snippet, _line_number(text, match.start())\n\n\ndef _extract_design_snippet(text: str, anchor: str) -> tuple[str, int] | None:\n    lines = text.splitlines()\n    row_re = re.compile(rf\"^\\|\\s*{re.escape(anchor)}\\s*\\|\")\n    for index, line in enumerate(lines):\n        if not row_re.match(line):\n            continue\n        heading = index\n        while heading > 0 and not re.match(r\"^#{2,}\\s+\", lines[heading]):\n            heading -= 1\n        start = min(max(heading, 0), max(index - 2, 0))\n        end = min(len(lines), index + 1)\n        return \"\\n\".join(lines[start:end]).strip(), index + 1\n    return None\n\n\ndef _relative_to_base(path: Path, base: Path) -> str:\n    try:\n        return path.resolve(strict=False).relative_to(base.resolve(strict=False)).as_posix()\n    except ValueError:\n        return str(path)\n\n\ndef _resolve_refs(base: Path, refs: list[str], *, design: bool) -> tuple[list[dict[str, Any]], list[dict[str, str]]]:\n    resolved: list[dict[str, Any]] = []\n    errors: list[dict[str, str]] = []\n    seen: set[str] = set()\n    for ref in refs:\n        if ref in seen:\n            continue\n        seen.add(ref)\n        try:\n            raw_path, anchor = _split_ref(ref)\n            if design and not (anchor.startswith(\"API-\") or anchor.startswith(\"DATA-\") or anchor.startswith(\"D-\")):\n                raise WriterError(f\"designRefs 只允许 API/DATA/D anchor: {ref}\")\n            if not design and not (anchor.startswith(\"REQ-\") or anchor.startswith(\"SCN-\")):\n                raise WriterError(f\"specRefs 只允许 REQ/SCN anchor: {ref}\")\n            path = _resolve_path(base, ref, anchor, design=design)\n        except WriterError as exc:\n            errors.append({\"reason\": \"invalid_artifact_ref\", \"detail\": f\"{ref}: {exc}\"})\n            resolved.append({\"ref\": ref, \"found\": False, \"error\": \"invalid_artifact_ref\"})\n            continue\n\n        item: dict[str, Any] = {\n            \"ref\": ref,\n            \"path\": _relative_to_base(path, base),\n            \"absolutePath\": str(path),\n            \"anchor\": anchor,\n            \"found\": False,\n        }\n        if not path.is_file():\n            errors.append({\"reason\": \"missing_ref_file\", \"detail\": ref})\n            item[\"error\"] = \"missing_ref_file\"\n            resolved.append(item)\n            continue\n\n        text = path.read_text(encoding=\"utf-8\")\n        extracted = _extract_design_snippet(text, anchor) if design else _extract_spec_snippet(text, anchor)\n        if extracted is None:\n            errors.append({\"reason\": \"missing_ref_anchor\", \"detail\": ref})\n            item[\"error\"] = \"missing_ref_anchor\"\n            resolved.append(item)\n            continue\n        snippet, line = extracted\n        item.update({\"found\": True, \"line\": line, \"text\": snippet, \"sourcePathWasExplicit\": bool(raw_path)})\n        resolved.append(item)\n    return resolved, errors\n\n\ndef resolve_task_refs(base: Path, task: dict[str, Any]) -> tuple[list[dict[str, Any]], list[dict[str, Any]], list[dict[str, str]]]:\n    spec_refs = [ref for ref in task.get(\"specRefs\", []) if isinstance(ref, str)]\n    design_refs = [ref for ref in task.get(\"designRefs\", []) if isinstance(ref, str)]\n    for field in (\"apiIds\", \"dataIds\", \"decisionIds\"):\n        design_refs.extend(f\"design.md#{value}\" for value in task.get(field, []) if isinstance(value, str))\n    resolved_specs, spec_errors = _resolve_refs(base, spec_refs, design=False)\n    resolved_design, design_errors = _resolve_refs(base, design_refs, design=True)\n    return resolved_specs, resolved_design, spec_errors + design_errors\n",
  "hooks/command_executable.py": "\"\"\"Read-only rules extracted from hooks/code_shell_analysis.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nimport re\nimport posixpath\n\ndef executable(token: str) -> str:\n    return token.replace(\"\\\\\", \"/\").rsplit(\"/\", 1)[-1].lower().removesuffix(\".cmd\").removesuffix(\".bat\")\n",
  "hooks/compile_command_policy.py": "\"\"\"Read-only rules extracted from hooks/code_execution_guard.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nimport re\nfrom pathlib import Path\nfrom hooks.command_executable import executable\n\ndef _executable(token: str) -> str:\n    return executable(token)\n\n\ndef _maven_arguments(argv: list[str]) -> tuple[list[str], list[str], str | None]:\n    goals: list[str] = []\n    files: list[str] = []\n    values = {\"-f\", \"--file\", \"-pl\", \"--projects\", \"-P\", \"--activate-profiles\", \"-D\", \"--define\",\n              \"-s\", \"--settings\", \"-gs\", \"--global-settings\", \"-t\", \"--toolchains\", \"-gt\", \"--global-toolchains\",\n              \"-T\", \"--threads\", \"-rf\", \"--resume-from\", \"-l\", \"--log-file\"}\n    index = 1\n    while index < len(argv):\n        token = argv[index]\n        if \"$\" in token:\n            return goals, files, \"Maven 参数包含无法确定的运行时变量\"\n        if token in values:\n            if index + 1 >= len(argv) or argv[index + 1].startswith(\"-\"):\n                return goals, files, f\"Maven 选项 {token} 缺少参数值\"\n            if token in {\"-f\", \"--file\"}:\n                files.append(argv[index + 1])\n            index += 2\n            continue\n        if token.startswith(\"--file=\") or token.startswith(\"-f=\"):\n            files.append(token.split(\"=\", 1)[1])\n        elif token.startswith(\"-f\") and len(token) > 2:\n            files.append(token[2:])\n        elif not token.startswith(\"-\"):\n            goals.append(token)\n        index += 1\n    if any(not path or \"$\" in path for path in files):\n        return goals, files, \"Maven -f/--file 必须指定明确的构建文件\"\n    return goals, files, None\n\n\ndef _production_compile_argv(tokens: list[str]) -> bool:\n    if any(\"$\" in token for token in tokens):\n        return False\n    executable = _executable(tokens[0])\n    if executable in {\"mvn\", \"mvnw\"}:\n        goals, _, error = _maven_arguments(tokens)\n        return error is None and \"compile\" in goals and set(goals) <= {\"compile\", \"clean\"}\n    if executable in {\"gradle\", \"gradlew\"}:\n        tasks = {token.rsplit(\":\", 1)[-1] for token in tokens[1:] if not token.startswith(\"-\")}\n        return bool(tasks) and tasks <= {\n            \"classes\", \"compileJava\", \"compileKotlin\", \"compileGroovy\", \"compileScala\"\n        }\n    if executable == \"go\":\n        return len(tokens) >= 2 and tokens[1] == \"build\" and not any(\n            token in {\"test\", \"vet\", \"run\", \"install\"} for token in tokens[1:]\n        )\n    if executable == \"cargo\":\n        return len(tokens) >= 2 and tokens[1] == \"check\" and not any(\n            token in {\"test\", \"build\", \"clippy\", \"bench\"} for token in tokens[1:]\n        )\n    return False\n",
  "hooks/design_contract_lock.py": "\"\"\"Read-only rules extracted from hooks/design_contract_lock.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nimport json\nimport re\nfrom pathlib import Path\nfrom typing import Any\nfrom hooks.artifact_ref_validator import load_design_contract, design_contract_snapshot\ndef load_json(path):\n    return json.loads(path.read_text(encoding='utf-8'))\n\nDESIGN_CONTRACT_LOCK_FILE = \".design-contract.lock.json\"\n\n\n_SHA256_RE = re.compile(r\"^[0-9a-f]{64}$\")\n\n\n_ID_PATTERNS = {\n    \"apiIds\": re.compile(r\"^API-\\d{3}$\"),\n    \"dataIds\": re.compile(r\"^DATA-\\d{3}$\"),\n    \"decisionIds\": re.compile(r\"^D-\\d{3}$\"),\n}\n\n\ndef design_contract_lock_path(base: Path) -> Path:\n    return base / DESIGN_CONTRACT_LOCK_FILE\n\n\ndef _issue(reason: str, detail: str = \"\") -> dict[str, Any]:\n    result: dict[str, Any] = {\n        \"reason\": reason,\n        \"repairTarget\": \"design_revision\",\n        \"repairable\": False,\n        \"designMutationAllowed\": False,\n        \"repairSuggestion\": \"回到 /autodev-design 校验并重新锁定 design.md，然后再进入 Plan。\",\n    }\n    if detail:\n        result[\"detail\"] = detail\n    return result\n\n\ndef _normalize_snapshot(value: Any) -> tuple[dict[str, Any] | None, list[dict[str, Any]]]:\n    if not isinstance(value, dict):\n        return None, [_issue(\"design_contract_lock_invalid\", \"designContract_missing\")]\n    sha256 = value.get(\"sha256\")\n    if not isinstance(sha256, str) or not _SHA256_RE.fullmatch(sha256):\n        return None, [_issue(\"design_contract_lock_invalid\", \"designContract.sha256_invalid\")]\n\n    ids: dict[str, set[str]] = {\"API\": set(), \"DATA\": set(), \"D\": set()}\n    for field, kind in ((\"apiIds\", \"API\"), (\"dataIds\", \"DATA\"), (\"decisionIds\", \"D\")):\n        raw_ids = value.get(field)\n        if not isinstance(raw_ids, list) or any(\n            not isinstance(item, str) or not _ID_PATTERNS[field].fullmatch(item)\n            for item in raw_ids\n        ):\n            return None, [_issue(\"design_contract_lock_invalid\", f\"designContract.{field}_invalid\")]\n        if len(raw_ids) != len(set(raw_ids)):\n            return None, [_issue(\"design_contract_lock_invalid\", f\"designContract.{field}_duplicate\")]\n        ids[kind] = set(raw_ids)\n\n    no_http_api = value.get(\"noHttpApi\")\n    no_sql = value.get(\"noSql\")\n    if not isinstance(no_http_api, bool) or not isinstance(no_sql, bool):\n        return None, [_issue(\"design_contract_lock_invalid\", \"designContract.marker_invalid\")]\n    if no_http_api and ids[\"API\"]:\n        return None, [_issue(\"design_contract_lock_invalid\", \"noHttpApi_conflicts_with_apiIds\")]\n    if no_sql and ids[\"DATA\"]:\n        return None, [_issue(\"design_contract_lock_invalid\", \"noSql_conflicts_with_dataIds\")]\n\n    return {\n        \"sha256\": sha256,\n        \"ids\": ids,\n        \"noHttpApi\": no_http_api,\n        \"noSql\": no_sql,\n    }, []\n\n\ndef load_confirmed_design_contract(base: Path, feature: str) -> tuple[dict[str, Any], list[dict[str, Any]]]:\n    \"\"\"Load the Design-approved snapshot without reading ``design.md``.\"\"\"\n\n    path = design_contract_lock_path(base)\n    if not path.is_file() or path.stat().st_size <= 0:\n        return {}, [_issue(\"design_contract_lock_missing\", str(path))]\n    try:\n        payload = load_json(path)\n    except Exception as exc:\n        return {}, [_issue(\"design_contract_lock_invalid\", f\"error={exc}\")]\n    if not isinstance(payload, dict):\n        return {}, [_issue(\"design_contract_lock_invalid\", \"root_not_object\")]\n    if payload.get(\"version\") != 1:\n        return {}, [_issue(\"design_contract_lock_invalid\", f\"version={payload.get('version')!r}\")]\n    if payload.get(\"featureId\") != feature:\n        return {}, [_issue(\n            \"design_contract_lock_invalid\",\n            f\"featureId={payload.get('featureId')!r};expected={feature}\",\n        )]\n    if payload.get(\"lockOwner\") != \"dev.design\":\n        return {}, [_issue(\n            \"design_contract_lock_invalid\",\n            f\"lockOwner={payload.get('lockOwner')!r};expected=dev.design\",\n        )]\n    if not isinstance(payload.get(\"lockedAt\"), str) or not payload[\"lockedAt\"].strip():\n        return {}, [_issue(\"design_contract_lock_invalid\", \"lockedAt_missing\")]\n    return _normalize_snapshot(payload.get(\"designContract\"))\n\n\ndef validate_design_contract_lock(base: Path, feature: str) -> list[dict[str, Any]]:\n    \"\"\"Design-stage proof that its persisted snapshot matches valid design.md.\"\"\"\n\n    contract, design_errors = load_design_contract(base)\n    if design_errors:\n        return design_errors\n    locked, lock_errors = load_confirmed_design_contract(base, feature)\n    if lock_errors:\n        return lock_errors\n    expected = design_contract_snapshot(contract)\n    actual = design_contract_snapshot(locked)\n    if actual != expected:\n        return [_issue(\n            \"design_contract_lock_outdated\",\n            f\"expected={expected['sha256']};actual={actual['sha256']}\",\n        )]\n    return []\n",
  "hooks/frontend_route_constants.py": "\"\"\"Read-only rules extracted from hooks/resolve_frontend_html_route.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\n\n\nROUTE_ABSOLUTE = \"absolute-html\"\n\n\nROUTE_STANDARD = \"standard-html\"\n\n\nROUTE_SPEC_DRIVEN = \"spec-driven-ui\"\n\n\nROUTE_MISSING = \"missing-html\"\n\n\nROUTE_NONE = \"none\"\n",
  "hooks/implementation_scope.py": "\"\"\"Read-only rules extracted from hooks/implementation_scope.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nimport json\nfrom pathlib import Path\nfrom typing import Any\n\nSCOPE_FILENAME = \"IMPLEMENTATION_SCOPE.json\"\n\n\nVALID_SCOPES = frozenset({\"full_stack\", \"backend_only\", \"frontend_only\"})\n\n\nDEFAULT_SCOPE = \"full_stack\"\n\n\ndef scope_path(feature_dir: Path) -> Path:\n    return feature_dir / SCOPE_FILENAME\n\n\ndef validate_scope_payload(payload: Any, *, feature: str | None = None) -> list[str]:\n    if not isinstance(payload, dict):\n        return [\"implementation_scope_root_must_be_object\"]\n    scope = payload.get(\"implementationScope\")\n    errors: list[str] = []\n    if scope not in VALID_SCOPES:\n        errors.append(\"implementationScope_invalid\")\n    if feature is not None and payload.get(\"featureId\") != feature:\n        errors.append(\"implementationScope_feature_mismatch\")\n    source = payload.get(\"source\")\n    if not isinstance(source, str) or not source.strip():\n        errors.append(\"implementationScope_source_missing\")\n    return errors\n\n\ndef load_scope(feature_dir: Path, *, required: bool = False) -> tuple[str, list[str]]:\n    \"\"\"Return (scope, errors); absent legacy scopes default to full_stack.\"\"\"\n\n    path = scope_path(feature_dir)\n    if not path.is_file():\n        if required:\n            return DEFAULT_SCOPE, [\"implementation_scope_missing\"]\n        return DEFAULT_SCOPE, []\n    try:\n        payload = json.loads(path.read_text(encoding=\"utf-8\"))\n    except (OSError, json.JSONDecodeError) as exc:\n        return DEFAULT_SCOPE, [f\"implementation_scope_unreadable:{exc}\"]\n    errors = validate_scope_payload(payload, feature=feature_dir.name)\n    return str(payload.get(\"implementationScope\", DEFAULT_SCOPE)), errors\n",
  "hooks/parallel_validation_ownership.py": "\"\"\"Read-only rules extracted from hooks/parallel_validation_ownership.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nimport hashlib\nimport json\nfrom pathlib import Path\nfrom typing import Any\nfrom hooks.plan_json import PlanBundle, load_plan_bundle\n\nPIPELINE_SCHEMA_VERSION = \"autobiz.parallel.pipeline.v1\"\n\n\nDELIVERY_STAGES = (\"prepare\", \"implement\", \"review\", \"test\")\n\n\nVALIDATION_BATCHES = (\n    {\n        \"id\": \"V-E2E\",\n        \"type\": \"validation\",\n        \"stage\": \"e2e_test\",\n        \"dependsOn\": \"all_delivery\",\n        \"executionTarget\": \"merged_main\",\n    },\n)\n\n\ndef _canonical(value: Any) -> str:\n    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(\",\", \":\"))\n\n\ndef _pipeline_revision(root: dict[str, Any], batches: dict[str, dict[str, Any]]) -> str:\n    contract = {\n        \"batches\": [\n            {\n                \"id\": entry.get(\"id\"),\n                \"deps\": entry.get(\"deps\", []),\n                \"taskIds\": entry.get(\"taskIds\", []),\n                \"workspaceRef\": entry.get(\"workspaceRef\"),\n                \"writeSet\": [\n                    path\n                    for task in batches.get(str(entry.get(\"id\")), {}).get(\"tasks\", [])\n                    if isinstance(task, dict)\n                    for path in (task.get(\"scope\", {}).get(\"paths\", []) if isinstance(task.get(\"scope\"), dict) else [])\n                ],\n                \"taskVerification\": [\n                    {\n                        \"id\": task.get(\"id\"),\n                        \"testPoints\": task.get(\"testPoints\", []),\n                        \"verificationIntent\": task.get(\"verificationIntent\"),\n                        \"acceptanceCriteria\": task.get(\"acceptanceCriteria\", []),\n                    }\n                    for task in batches.get(str(entry.get(\"id\")), {}).get(\"tasks\", [])\n                    if isinstance(task, dict)\n                ],\n            }\n            for entry in root.get(\"batches\", [])\n            if isinstance(entry, dict)\n        ],\n    }\n    return \"sha256:\" + hashlib.sha256(_canonical(contract).encode(\"utf-8\")).hexdigest()\n\n\ndef build_pipeline_contract(root: dict[str, Any], batches: dict[str, dict[str, Any]]) -> dict[str, Any]:\n    \"\"\"Create the deterministic pipeline projection written by Plan Writer.\"\"\"\n    ownership: dict[str, dict[str, Any]] = {}\n    for entry in root.get(\"batches\", []):\n        if not isinstance(entry, dict) or not isinstance(entry.get(\"id\"), str):\n            continue\n        batch_id = entry[\"id\"]\n        batch = batches.get(batch_id, {})\n        ownership[f\"REVIEW-{batch_id}\"] = {\n            \"ownerBatchId\": batch_id,\n            \"stage\": \"review\",\n            \"kind\": \"review\",\n        }\n        for task in batch.get(\"tasks\", []) if isinstance(batch, dict) else []:\n            if not isinstance(task, dict) or not isinstance(task.get(\"id\"), str):\n                continue\n            if task.get(\"executionMode\") == \"external_dependency\":\n                continue\n            target_id = f\"UTEST-{task['id']}\"\n            ownership[target_id] = {\n                \"ownerBatchId\": batch_id,\n                \"stage\": \"test\",\n                \"kind\": \"utest_target\",\n                \"taskId\": task[\"id\"],\n                \"sourceBatchId\": batch_id,\n            }\n\n    return {\n        \"schemaVersion\": PIPELINE_SCHEMA_VERSION,\n        \"planRevision\": _pipeline_revision(root, batches),\n        \"deliveryStages\": list(DELIVERY_STAGES),\n        \"validationBatches\": [dict(item) for item in VALIDATION_BATCHES],\n        \"validationOwnership\": ownership,\n        \"finalization\": {\n            \"mode\": \"evidence_aggregate_only\",\n            \"forbidPostMergeDuplicateExecution\": True,\n        },\n    }\n\n\ndef validation_ownership_errors(root: dict[str, Any], batches: dict[str, dict[str, Any]]) -> list[str]:\n    pipeline = root.get(\"parallelBatchPipeline\")\n    if not isinstance(pipeline, dict):\n        return [\"parallel_batch_pipeline_missing\"]\n    errors: list[str] = []\n    if pipeline.get(\"schemaVersion\") != PIPELINE_SCHEMA_VERSION:\n        errors.append(\"parallel_batch_pipeline_schema_invalid\")\n    if pipeline.get(\"deliveryStages\") != list(DELIVERY_STAGES):\n        errors.append(\"parallel_batch_pipeline_delivery_stages_invalid\")\n    if not isinstance(pipeline.get(\"planRevision\"), str) or not pipeline[\"planRevision\"].startswith(\"sha256:\"):\n        errors.append(\"parallel_batch_pipeline_revision_invalid\")\n    elif pipeline[\"planRevision\"] != _pipeline_revision(root, batches):\n        errors.append(\"parallel_batch_pipeline_revision_stale\")\n\n    expected_validation = [dict(item) for item in VALIDATION_BATCHES]\n    if pipeline.get(\"validationBatches\") != expected_validation:\n        errors.append(\"parallel_batch_pipeline_validation_batches_invalid\")\n\n    ownership = pipeline.get(\"validationOwnership\")\n    if not isinstance(ownership, dict):\n        return [*errors, \"parallel_validation_ownership_missing\"]\n    expected = build_pipeline_contract(root, batches)[\"validationOwnership\"]\n    source_ids: list[str] = []\n    for entry in root.get(\"batches\", []):\n        if not isinstance(entry, dict) or not isinstance(entry.get(\"id\"), str):\n            continue\n        batch_id = entry[\"id\"]\n        batch = batches.get(batch_id, {})\n        for task in batch.get(\"tasks\", []) if isinstance(batch, dict) else []:\n            if not isinstance(task, dict) or not isinstance(task.get(\"id\"), str):\n                continue\n            if task.get(\"executionMode\") != \"external_dependency\":\n                source_ids.append(f\"UTEST-{task['id']}\")\n    duplicate_ids = sorted({item for item in source_ids if source_ids.count(item) > 1})\n    errors.extend(f\"validation_ownership_duplicate:{command_id}\" for command_id in duplicate_ids)\n    for command_id, owner in expected.items():\n        actual = ownership.get(command_id)\n        if actual != owner:\n            errors.append(f\"validation_ownership_missing_or_invalid:{command_id}\")\n    for command_id, owner in ownership.items():\n        if command_id not in expected:\n            errors.append(f\"validation_ownership_unknown:{command_id}\")\n            continue\n        if not isinstance(owner, dict):\n            errors.append(f\"validation_ownership_invalid:{command_id}\")\n\n    finalization = pipeline.get(\"finalization\")\n    if not isinstance(finalization, dict) or finalization.get(\"mode\") != \"evidence_aggregate_only\":\n        errors.append(\"parallel_batch_pipeline_finalization_invalid\")\n    if isinstance(finalization, dict) and finalization.get(\"forbidPostMergeDuplicateExecution\") is not True:\n        errors.append(\"parallel_batch_pipeline_duplicate_execution_not_forbidden\")\n    return errors\n",
  "hooks/performance_rules.py": "\"\"\"Read-only rules extracted from hooks/performance_checker.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nimport re\nfrom typing import List, Dict, Tuple\n\nRULES: List[Dict] = [\n    {\n        \"id\": \"FRONT-RULE001\",\n        \"risk\": \"高风险\",\n        \"category\": \"性能\",\n        \"title\": \"定时器中直接触发 API 请求\",\n        \"desc\": \"禁止在 setInterval / setTimeout / requestAnimationFrame 中直接触发 API 请求或调用浏览器API\",\n        \"check\": lambda lines: _check_timer_api(lines),\n    },\n    {\n        \"id\": \"FRONT-RULE002\",\n        \"risk\": \"高风险\",\n        \"category\": \"性能\",\n        \"title\": \"资源使用后未显式清除\",\n        \"desc\": \"setInterval、setTimeout、addEventListener、WebSocket、URL.createObjectURL、Web Worker、SharedWorker 使用完成后必须显式清除\",\n        \"check\": lambda lines: _check_resource_cleanup(lines),\n    },\n    {\n        \"id\": \"FRONT-RULE003\",\n        \"risk\": \"高风险\",\n        \"category\": \"性能\",\n        \"title\": \"循环中注册定时器/事件/WebSocket\",\n        \"desc\": \"禁止在循环中使用 setInterval、setTimeout、addEventListener、WebSocket 直接触发 API 请求或调用浏览器API\",\n        \"check\": lambda lines: _check_loop_registration(lines),\n    },\n    {\n        \"id\": \"FRONT-RULE004\",\n        \"risk\": \"中风险\",\n        \"category\": \"性能\",\n        \"title\": \"高频事件未节流/防抖\",\n        \"desc\": \"resize、scroll、mousemove 这些 window 事件监听需要防抖或节流\",\n        \"check\": lambda lines: _check_throttle_debounce(lines),\n    },\n    {\n        \"id\": \"FRONT-RULE005\",\n        \"risk\": \"高风险\",\n        \"category\": \"性能\",\n        \"title\": \"组件卸载时未清理副作用\",\n        \"desc\": \"组件卸载时必须清理定时器、事件监听、WebSocket、未完成请求等副作用\",\n        \"check\": lambda lines: _check_component_cleanup(lines),\n    },\n    {\n        \"id\": \"FRONT-RULE006\",\n        \"risk\": \"中风险\",\n        \"category\": \"性能\",\n        \"title\": \"轮询缺少退避和可见性感知\",\n        \"desc\": \"轮询逻辑必须监听页面可见性，不可见时暂停；失败时指数退避\",\n        \"check\": lambda lines: _check_polling_backoff(lines),\n    },\n    {\n        \"id\": \"FRONT-RULE007\",\n        \"risk\": \"中风险\",\n        \"category\": \"性能\",\n        \"title\": \"相同参数 API 重复调用\",\n        \"desc\": \"相同参数的 API 在短时间内重复调用必须做去重或合并\",\n        \"check\": lambda lines: _check_duplicate_api(lines),\n    },\n]\n\n\ndef _find_lines(code: str, pattern: str, flags: int = 0) -> List[Tuple[int, str]]:\n    \"\"\"在代码中搜索匹配的行，返回 (行号, 行内容) 列表\"\"\"\n    results = []\n    for i, line in enumerate(code.splitlines(), 1):\n        if re.search(pattern, line, flags):\n            results.append((i, line.strip()))\n    return results\n\n\ndef _get_line_snippet(lines: str, line_no: int, max_len: int = 120) -> str:\n    \"\"\"获取指定行的代码片段\"\"\"\n    all_lines = lines.splitlines()\n    if 1 <= line_no <= len(all_lines):\n        return all_lines[line_no - 1][:max_len]\n    return \"\"\n\n\ndef _is_in_string(line: str, pos: int) -> bool:\n    \"\"\"检查位置 pos 是否在字符串引号内\"\"\"\n    before = line[:pos]\n    single_quotes = 0\n    double_quotes = 0\n    i = 0\n    while i < len(before):\n        if before[i] == '\\\\':\n            i += 2\n            continue\n        if before[i] == \"'\":\n            single_quotes += 1\n        elif before[i] == '\"':\n            double_quotes += 1\n        i += 1\n    return single_quotes % 2 == 1 or double_quotes % 2 == 1\n\n\ndef _check_timer_api(lines: str) -> List[Dict]:\n    \"\"\"\n    检测 setInterval/setTimeout/requestAnimationFrame 回调中\n    直接调用 fetch/axios/XMLHttpRequest 等 API 请求或浏览器API。\n    通过括号匹配精确识别定时器回调边界，避免误报。\n    \"\"\"\n    findings = []\n    timer_pattern = r'(setInterval|setTimeout|requestAnimationFrame)\\s*\\('\n    api_pattern = r'(fetch\\s*\\(|axios\\.|\\.ajax\\s*\\(|XMLHttpRequest|new\\s+Request\\s*\\()'\n\n    in_timer = False\n    timer_start = 0\n    timer_code = \"\"\n    paren_depth = 0\n    # print(f\"WARNING 检测 setInterval/setTimeout/requestAnimationFrame 回调中\")\n    for i, line in enumerate(lines.splitlines(), 1):\n        if not in_timer:\n            m = re.search(timer_pattern, line)\n            if m:\n                in_timer = True\n                timer_start = i\n                timer_code = line\n                paren_depth = line.count('(') - line.count(')')\n        else:\n            timer_code += \"\\n\" + line\n            paren_depth += line.count('(') - line.count(')')\n\n            if paren_depth <= 0:\n                clean_code = re.sub(r'//.*', '', timer_code)\n                clean_code = re.sub(r'/\\*.*?\\*/', '', clean_code, flags=re.DOTALL)\n                if re.search(api_pattern, clean_code):\n                    findings.append({\n                        \"line\": timer_start,\n                        \"snippet\": _get_line_snippet(lines, timer_start),\n                        \"detail\": f\"第 {timer_start} 行的定时器回调中直接调用了 API 请求\"\n                    })\n                in_timer = False\n                timer_code = \"\"\n                paren_depth = 0\n\n    return findings\n\n\ndef _check_resource_cleanup(lines: str) -> List[Dict]:\n    \"\"\"\n    检测 setInterval/setTimeout/addEventListener/WebSocket/\n    URL.createObjectURL/Web Worker/SharedWorker 使用后是否显式清除。\n    排除 React useEffect 中有 return cleanup 的情况。\n    每个资源类型独立检测，避免交叉干扰。\n    \"\"\"\n    findings = []\n\n    # ---- 2.1 setInterval 未清除 ----\n    set_intervals = re.finditer(r'setInterval\\s*\\(', lines)\n    for m in set_intervals:\n        pos = m.start()\n        line_no = lines[:pos].count('\\n') + 1\n        snippet = _get_line_snippet(lines, line_no)\n        if _is_in_string(snippet, snippet.find('setInterval')):\n            continue\n        before = lines[max(0, pos - 500):pos]\n        if re.search(r'useEffect\\s*\\(', before):\n            after = lines[pos:pos + 500]\n            if re.search(r'return\\s+.*clearInterval', after):\n                continue\n        # 检查同一行或后续 2000 字符内是否有 clearInterval\n        after = lines[pos:pos + 2000]\n        if re.search(r'clearInterval\\s*\\(', after):\n            continue\n        findings.append({\n            \"line\": line_no,\n            \"snippet\": snippet,\n            \"detail\": f\"第 {line_no} 行使用了 setInterval，但未找到对应的 clearInterval 清除\"\n        })\n\n    # ---- 2.2 setTimeout 未清除（仅当赋值给变量时） ----\n    timeout_vars = re.finditer(r'(?:const|let|var)\\s+(\\w+)\\s*=\\s*setTimeout\\s*\\(', lines)\n    for m in timeout_vars:\n        var_name = m.group(1)\n        pos = m.start()\n        line_no = lines[:pos].count('\\n') + 1\n        after = lines[pos:pos + 2000]\n        if not re.search(r'clearTimeout\\s*\\(\\s*' + re.escape(var_name) + r'\\s*\\)', after):\n            snippet = _get_line_snippet(lines, line_no)\n            findings.append({\n                \"line\": line_no,\n                \"snippet\": snippet,\n                \"detail\": f\"第 {line_no} 行的 setTimeout 赋值给变量 '{var_name}'，但未找到对应的 clearTimeout 清除\"\n            })\n\n    # ---- 2.3 addEventListener 未移除 ----\n    add_listeners = re.finditer(r'(?:document|window|element|el|\\w+)\\s*\\.\\s*addEventListener\\s*\\(', lines)\n    for m in add_listeners:\n        pos = m.start()\n        line_no = lines[:pos].count('\\n') + 1\n        after = lines[m.end():m.end() + 100]\n        event_match = re.search(r'[\"\\'](\\w+)[\"\\']', after)\n        event_type = event_match.group(1) if event_match else \"?\"\n        before = lines[max(0, pos - 500):pos]\n        if re.search(r'useEffect\\s*\\(', before):\n            after_block = lines[pos:pos + 500]\n            if re.search(r'return\\s+.*removeEventListener', after_block):\n                continue\n        after_file = lines[pos:pos + 2000]\n        if re.search(r'removeEventListener\\s*\\(\\s*[\"\\']' + re.escape(event_type) + r'[\"\\']', after_file):\n            continue\n        snippet = _get_line_snippet(lines, line_no)\n        findings.append({\n            \"line\": line_no,\n            \"snippet\": snippet,\n            \"detail\": f\"第 {line_no} 行注册了 '{event_type}' 事件监听，但未找到对应的 removeEventListener 移除\"\n        })\n\n    # ---- 2.4 WebSocket 未 close ----\n    ws_news = re.finditer(r'new\\s+WebSocket\\s*\\(', lines)\n    for m in ws_news:\n        pos = m.start()\n        line_no = lines[:pos].count('\\n') + 1\n        after = lines[pos:pos + 2000]\n        if re.search(r'\\.close\\s*\\(\\)', after):\n            continue\n        snippet = _get_line_snippet(lines, line_no)\n        findings.append({\n            \"line\": line_no,\n            \"snippet\": snippet,\n            \"detail\": f\"第 {line_no} 行创建了 WebSocket，但未找到对应的 .close() 关闭\"\n        })\n\n    # ---- 2.5 URL.createObjectURL 未 revoke ----\n    create_urls = re.finditer(r'URL\\.createObjectURL\\s*\\(', lines)\n    for m in create_urls:\n        pos = m.start()\n        line_no = lines[:pos].count('\\n') + 1\n        after = lines[pos:pos + 2000]\n        if re.search(r'URL\\.revokeObjectURL\\s*\\(', after):\n            continue\n        snippet = _get_line_snippet(lines, line_no)\n        findings.append({\n            \"line\": line_no,\n            \"snippet\": snippet,\n            \"detail\": f\"第 {line_no} 行使用了 URL.createObjectURL，但未找到对应的 URL.revokeObjectURL 释放\"\n        })\n\n    # ---- 2.6 Web Worker / SharedWorker 未 terminate ----\n    worker_news = re.finditer(r'new\\s+(?:Worker|SharedWorker)\\s*\\(', lines)\n    for m in worker_news:\n        pos = m.start()\n        line_no = lines[:pos].count('\\n') + 1\n        after = lines[pos:pos + 2000]\n        if re.search(r'\\.terminate\\s*\\(\\)', after):\n            continue\n        snippet = _get_line_snippet(lines, line_no)\n        findings.append({\n            \"line\": line_no,\n            \"snippet\": snippet,\n            \"detail\": f\"第 {line_no} 行创建了 Worker，但未找到对应的 .terminate() 终止\"\n        })\n\n    return findings\n\n\ndef _check_loop_registration(lines: str) -> List[Dict]:\n    \"\"\"\n    检测在 for/while/forEach/map 等循环结构中\n    注册 setInterval/setTimeout/addEventListener/WebSocket。\n    通过括号匹配精确识别循环体边界。\n    \"\"\"\n    findings = []\n    loop_patterns = [\n        r'\\bfor\\s*\\(',\n        r'\\bwhile\\s*\\(',\n        r'\\.forEach\\s*\\(',\n        r'\\.map\\s*\\(',\n        r'\\.reduce\\s*\\(',\n    ]\n    resource_patterns = [\n        (r'setInterval\\s*\\(', 'setInterval'),\n        (r'setTimeout\\s*\\(', 'setTimeout'),\n        (r'addEventListener\\s*\\(', 'addEventListener'),\n        (r'new\\s+WebSocket\\s*\\(', 'WebSocket'),\n        (r'new\\s+Worker\\s*\\(', 'Worker'),\n        (r'new\\s+SharedWorker\\s*\\(', 'SharedWorker'),\n    ]\n\n    lines_list = lines.splitlines()\n    for i, line in enumerate(lines_list, 1):\n        in_loop = False\n        for lp in loop_patterns:\n            if re.search(lp, line):\n                in_loop = True\n                break\n\n        if not in_loop:\n            continue\n\n        brace_start = line.find('{')\n        if brace_start == -1:\n            for rp, rname in resource_patterns:\n                if re.search(rp, line):\n                    findings.append({\n                        \"line\": i,\n                        \"snippet\": line.strip()[:120],\n                        \"detail\": f\"第 {i} 行的循环中直接注册了 {rname}，可能导致资源泄漏\"\n                    })\n        else:\n            brace_depth = line[brace_start:].count('{') - line[brace_start:].count('}')\n            loop_body = line[brace_start + 1:] + \"\\n\"\n            j = i\n            while brace_depth > 0 and j < len(lines_list):\n                j += 1\n                if j > len(lines_list):\n                    break\n                loop_body += lines_list[j - 1] + \"\\n\"\n                brace_depth += lines_list[j - 1].count('{') - lines_list[j - 1].count('}')\n\n            for rp, rname in resource_patterns:\n                if re.search(rp, loop_body):\n                    findings.append({\n                        \"line\": i,\n                        \"snippet\": lines_list[i - 1].strip()[:120],\n                        \"detail\": f\"第 {i} 行的循环体中注册了 {rname}，可能导致资源泄漏\"\n                    })\n                    break\n\n    return findings\n\n\ndef _check_throttle_debounce(lines: str) -> List[Dict]:\n    \"\"\"\n    检测 resize/scroll/mousemove 等高频事件监听\n    是否使用了节流或防抖。\n    覆盖原生 addEventListener、Vue 模板、React JSX 三种写法。\n    \"\"\"\n    findings = []\n\n    high_freq_events = [\n        (r'(?:window|document)\\s*\\.\\s*addEventListener\\s*\\(\\s*[\"\\'](?:resize|scroll|mousemove)[\"\\']', \"window 事件\"),\n        (r'@(?:resize|scroll|mousemove)', \"Vue 模板事件\"),\n        (r'on(?:Resize|Scroll|MouseMove)\\s*=', \"React JSX 事件\"),\n    ]\n\n    for pat, label in high_freq_events:\n        matches = re.finditer(pat, lines)\n        for m in matches:\n            pos = m.start()\n            line_no = lines[:pos].count('\\n') + 1\n            after = lines[m.end():m.end() + 500]\n            if not re.search(r'(debounce|throttle|防抖|节流|_debounce|_throttle)', after):\n                snippet = _get_line_snippet(lines, line_no)\n                findings.append({\n                    \"line\": line_no,\n                    \"snippet\": snippet,\n                    \"detail\": f\"第 {line_no} 行的 {label} 监听未发现节流或防抖处理\"\n                })\n\n    return findings\n\n\ndef _check_component_cleanup(lines: str) -> List[Dict]:\n    \"\"\"\n    检测 React useEffect / Vue onMounted 中有副作用\n    但缺少对应的 cleanup 函数。\n    覆盖 React useEffect 和 Vue Composition API 两种框架。\n    \"\"\"\n    findings = []\n\n    # ---- 5.1 React useEffect 有副作用但无 cleanup ----\n    use_effect_blocks = re.finditer(\n        r'useEffect\\s*\\(\\s*\\(\\s*\\)\\s*=>\\s*\\{',\n        lines\n    )\n    for m in use_effect_blocks:\n        block_start = m.end()\n        line_no = lines[:m.start()].count('\\n') + 1\n\n        brace_depth = 1\n        pos = block_start\n        block = \"\"\n        while brace_depth > 0 and pos < len(lines):\n            char = lines[pos]\n            if char == '{':\n                brace_depth += 1\n            elif char == '}':\n                brace_depth -= 1\n            block += char\n            pos += 1\n\n        has_side_effect = bool(re.search(\n            r'(setInterval|setTimeout|addEventListener|\\.subscribe\\s*\\(|new\\s+WebSocket)',\n            block\n        ))\n        if not has_side_effect:\n            continue\n\n        has_cleanup = bool(re.search(\n            r'return\\s+\\(?\\s*\\(?\\s*\\)?\\s*=>\\s*\\{',\n            block\n        )) or bool(re.search(\n            r'return\\s+\\(\\)\\s*=>',\n            block\n        )) or bool(re.search(\n            r'return\\s+\\w+\\s*;?\\s*\\}',\n            block\n        ))\n\n        if not has_cleanup:\n            snippet = _get_line_snippet(lines, line_no)\n            findings.append({\n                \"line\": line_no,\n                \"snippet\": snippet,\n                \"detail\": f\"第 {line_no} 行的 useEffect 有副作用（定时器/事件/订阅）但缺少 cleanup 函数\"\n            })\n\n    # ---- 5.2 Vue onMounted/onUnmounted 不配对 ----\n    on_mounted = _find_lines(lines, r'onMounted\\s*\\(')\n    on_unmounted = _find_lines(lines, r'onUnmounted\\s*\\(')\n    if on_mounted and not on_unmounted:\n        for ln, txt in on_mounted:\n            findings.append({\n                \"line\": ln,\n                \"snippet\": txt,\n                \"detail\": f\"第 {ln} 行使用了 onMounted 但未找到对应的 onUnmounted 清理\"\n            })\n\n    # ---- 5.3 Vue watchEffect 未停止 ----\n    watch_effects = _find_lines(lines, r'watchEffect\\s*\\(')\n    for ln, txt in watch_effects:\n        findings.append({\n            \"line\": ln,\n            \"snippet\": txt,\n            \"detail\": f\"第 {ln} 行使用了 watchEffect，组件卸载后可能继续执行，建议在 onUnmounted 中停止\"\n        })\n\n    return findings\n\n\ndef _check_polling_backoff(lines: str) -> List[Dict]:\n    \"\"\"\n    检测轮询逻辑是否具备：\n    1. 页面可见性感知（visibilitychange）\n    2. 指数退避机制\n    通过 setInterval 或递归 setTimeout 实现轮询时检查。\n    \"\"\"\n    findings = []\n\n    # 检测 setInterval 实现的轮询\n    interval_polls = re.finditer(r'setInterval\\s*\\(', lines)\n    for m in interval_polls:\n        pos = m.start()\n        line_no = lines[:pos].count('\\n') + 1\n        after = lines[m.end():m.end() + 500]\n\n        has_visibility = bool(re.search(r'visibilitychange', after))\n        has_backoff = bool(re.search(r'(backoff|退避|Math\\.min|Math\\.pow|\\*=\\s*2|\\*=\\s*1\\.5|delay\\s*\\*=|timeout\\s*\\*=|retryCount|retryDelay|重试次数|重试间隔)', after))\n\n        if not has_visibility or not has_backoff:\n            snippet = _get_line_snippet(lines, line_no)\n            detail_parts = []\n            if not has_visibility:\n                detail_parts.append(\"未监听页面可见性\")\n            if not has_backoff:\n                detail_parts.append(\"未实现指数退避\")\n            findings.append({\n                \"line\": line_no,\n                \"snippet\": snippet,\n                \"detail\": f\"第 {line_no} 行的轮询逻辑{'、'.join(detail_parts)}\"\n            })\n\n    # 检测递归 setTimeout 实现的轮询\n    timeout_polls = re.finditer(r'function\\s+\\w+\\s*\\(\\s*\\)\\s*\\{[^}]*setTimeout\\s*\\(', lines)\n    for m in timeout_polls:\n        pos = m.start()\n        line_no = lines[:pos].count('\\n') + 1\n        after = lines[m.end():m.end() + 500]\n\n        has_visibility = bool(re.search(r'visibilitychange', after))\n        has_backoff = bool(re.search(r'(backoff|退避|Math\\.min|Math\\.pow|\\*=\\s*2|\\*=\\s*1\\.5|delay\\s*\\*=|timeout\\s*\\*=|retryCount|retryDelay|重试次数|重试间隔)', after))\n\n        if not has_visibility or not has_backoff:\n            snippet = _get_line_snippet(lines, line_no)\n            detail_parts = []\n            if not has_visibility:\n                detail_parts.append(\"未监听页面可见性\")\n            if not has_backoff:\n                detail_parts.append(\"未实现指数退避\")\n            findings.append({\n                \"line\": line_no,\n                \"snippet\": snippet,\n                \"detail\": f\"第 {line_no} 行的轮询逻辑{'、'.join(detail_parts)}\"\n            })\n\n    return findings\n\n\ndef _check_duplicate_api(lines: str) -> List[Dict]:\n    \"\"\"\n    检测相同 URL 的 API 调用在代码中出现多次。\n    覆盖 fetch、axios.get/post/put/delete 等常见调用方式。\n    \"\"\"\n    findings = []\n    api_calls = re.finditer(r'(?:fetch|axios\\.(?:get|post|put|delete|patch))\\s*\\(\\s*[\"\\']([^\"\\']+)[\"\\']', lines)\n    api_map = {}\n    for m in api_calls:\n        url = m.group(1)\n        line_no = lines[:m.start()].count('\\n') + 1\n        if url not in api_map:\n            api_map[url] = []\n        api_map[url].append(line_no)\n\n    for url, line_nums in api_map.items():\n        if len(line_nums) > 1:\n            for ln in line_nums:\n                snippet = _get_line_snippet(lines, ln)\n                findings.append({\n                    \"line\": ln,\n                    \"snippet\": snippet,\n                    \"detail\": f\"第 {ln} 行的 API '{url[:60]}' 被重复调用（共 {len(line_nums)} 次），建议做去重或合并\"\n                })\n\n    return findings\n\n\ndef run_check(code: str) -> List[Dict]:\n    \"\"\"运行所有规则检测，返回结果列表\"\"\"\n    all_findings = []\n    for rule in RULES:\n        findings = rule[\"check\"](code)\n        for f in findings:\n            f[\"rule_id\"] = rule[\"id\"]\n            f[\"risk\"] = rule[\"risk\"]\n            f[\"category\"] = rule[\"category\"]\n            f[\"title\"] = rule[\"title\"]\n        all_findings.extend(findings)\n    return all_findings\n\n\nFRONTEND_EXTENSIONS = {'.js', '.jsx', '.ts', '.tsx', '.vue', '.mjs', '.cjs'}\n",
  "hooks/plan_granularity.py": "\"\"\"Read-only rules extracted from hooks/plan_granularity.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nimport re\nfrom typing import Any\n\nSCN_SUBSTRING = re.compile(r\"SCN-\\d{3}\")\n\n\ndef _has_ambiguous_scenario_reference(spec_refs: list[str]) -> bool:\n    \"\"\"Ranges and bare IDs make the downstream coverage set unreliable.\"\"\"\n    for raw_ref in spec_refs:\n        if not isinstance(raw_ref, str):\n            continue\n        stripped = raw_ref.strip()\n        path_part, separator, anchor = stripped.partition(\"#\")\n        if not separator:\n            continue\n        scenario_ids = SCN_SUBSTRING.findall(anchor)\n        if not scenario_ids:\n            continue\n        if not path_part.strip() or len(scenario_ids) != 1 or anchor.strip() != scenario_ids[0]:\n            return True\n    return False\n\n\ndef validate_plan_task_grouping_item(task: dict[str, Any], *, task_id: str) -> list[dict[str, Any]]:\n    \"\"\"Reject only references that would falsely mark a scenario as covered.\"\"\"\n    raw_refs = task.get(\"specRefs\")\n    spec_refs = raw_refs if isinstance(raw_refs, list) else []\n    if not _has_ambiguous_scenario_reference(spec_refs):\n        return []\n    return [{\n        \"reason\": \"invalid_plan_task_scenario_reference\",\n        \"detail\": f\"task={task_id} scenario refs must be individually expanded and fully qualified\",\n        \"taskId\": task_id,\n        \"field\": \"specRefs\",\n        \"repairTarget\": \"task_group\",\n        \"violations\": [{\n            \"code\": \"scenario_reference_not_fully_qualified\",\n            \"expected\": \"one_fully_qualified_scenario_ref_per_item\",\n        }],\n    }]\n\n\ndef validate_plan_task_granularity_item(task: dict[str, Any], *, task_id: str) -> list[dict[str, Any]]:\n    \"\"\"Compatibility entry point for the stage gate; Plan v2 has no size gate.\"\"\"\n    return validate_plan_task_grouping_item(task, task_id=task_id)\n",
  "hooks/plan_json.py": "\"\"\"Read-only rules extracted from hooks/plan_json.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nimport hashlib\nimport json\nimport re\nfrom dataclasses import dataclass\nfrom pathlib import Path, PurePosixPath, PureWindowsPath\nfrom typing import Any\nfrom hooks.plan_write_ownership import write_ownership_error_codes\n\nTASK_ID_RE = re.compile(r\"^T\\d{3}$\")\n\n\nBATCH_ID_RE = re.compile(r\"^B\\d{3}$\")\n\n\nATOMIC_GROUP_ID_RE = re.compile(r\"^AG\\d{3}$\")\n\n\nREQ_ID_RE = re.compile(r\"\\bREQ-\\d{3}\\b\")\n\n\nSCN_ID_RE = re.compile(r\"\\bSCN-\\d{3}\\b\")\n\n\nAPI_ID_RE = re.compile(r\"^API-\\d{3}$\")\n\n\nDATA_ID_RE = re.compile(r\"^DATA-\\d{3}$\")\n\n\nTECH_DECISION_ID_RE = re.compile(r\"^D-\\d{3}$\")\n\n\nEVIDENCE_ID_RE = re.compile(r\"^ev_\\d{4}$\")\n\n\nACCEPTANCE_ID_RE = re.compile(r\"^AC-T\\d{3}-\\d{2,3}$\")\n\n\nREPOSITORY_ID_RE = re.compile(r\"^[A-Za-z0-9._-]+$\")\n\n\nPAGE_ID_RE = re.compile(r\"^PAGE-\\d{3}$\")\n\n\nINTERACTION_ID_RE = re.compile(r\"^UIX-\\d{3}$\")\n\n\nVISUAL_SOURCE_ID_RE = re.compile(r\"^VIS-\\d{3}$\")\n\n\nSOURCE_ID_RE = re.compile(r\"^SRC-\\d{3}$\")\n\n\nFRONTEND_ROUTES = {\"none\", \"spec-driven-ui\", \"absolute-html\", \"standard-html\", \"missing-html\"}\n\n\nCOMPLETION_POLICIES = {\n    \"all_required_validations_pass\",\n    \"external_dependency_recorded\",\n}\n\n\nTASK_EXECUTION_MODES = {\"code\", \"verified_existing\", \"external_dependency\"}\n\n\nTASK_VALIDATION_POLICY_MODES = {\"defer_to_test_stages\"}\n\n\nTASK_VALIDATION_ERROR_CATEGORIES = {\n    \"external_dependency\",\n    \"environment_failure\",\n    \"source_compile_failure\",\n    \"behavior_test_failure\",\n    \"validation_contract_failure\",\n    \"workspace_changed\",\n    \"runner_integrity_failure\",\n}\n\n\nMAX_BATCH_TASKS = 3\n\n\nBATCH_STRATEGY = \"minimal_closed_delivery_v2\"\n\n\nEXECUTION_LANES = {\"backend\", \"frontend\"}\n\n\nIMPLEMENTATION_SCOPES = {\"full_stack\", \"backend_only\", \"frontend_only\"}\n\n\nTASK_SET_STATUSES = {\"collecting\", \"reviewing\", \"finalized\"}\n\n\nFEATURE_STATUSES = {\"todo\", \"in_progress\", \"failed\", \"done\"}\n\n\nBATCH_STATUSES = {\"todo\", \"in_progress\", \"failed\", \"done\"}\n\n\nTEST_STAGE_MAX_REPAIR_ATTEMPTS = 3\n\n\nPARALLEL_EXECUTION_STAGES = {\"parallel\", \"proto\", \"global\", \"integration\"}\n\n\nVALIDATION_DEFERRAL_REASONS = {\n    \"environment_failure\",\n    \"repair_attempts_exhausted\",\n    \"external_dependency\",\n}\n\n\nVALIDATION_DEFERRAL_SCOPES = {\"task\", \"batch\", \"project\"}\n\n\nVALIDATION_DEFERRAL_STATUS = \"deferred\"\n\n\nDEFAULT_WORKSPACE_ROOT = \"default\"\n\n\nTODO_STATUSES = {\"todo\", \"pending\", \"not_started\", \"not-started\", \"待做\", \"未开始\"}\n\n\nIN_PROGRESS_STATUSES = {\"in_progress\", \"in-progress\", \"doing\", \"进行中\"}\n\n\nIMPLEMENTED_STATUSES = {\"implemented\", \"awaiting_validation\", \"awaiting-validation\", \"待验证\"}\n\n\nVALIDATING_STATUSES = {\"validating\", \"验证中\"}\n\n\nDONE_STATUSES = {\"done\", \"completed\", \"complete\", \"pass\", \"passed\", \"完成\", \"已完成\"}\n\n\nFAILED_STATUSES = {\"failed\", \"fail\", \"blocked\", \"失败\", \"阻断\"}\n\n\nclass PlanJsonError(ValueError):\n    \"\"\"Raised when a plan.json file cannot be loaded or validated.\"\"\"\n\n\n@dataclass(frozen=True)\nclass PlanBundle:\n    root: dict[str, Any]\n    batches: dict[str, dict[str, Any]]\n    tasks: list[dict[str, Any]]\n    task_batches: dict[str, str]\n\n\ndef plan_json_path(target_feature_dir: Path) -> Path:\n    return target_feature_dir / \"plan.json\"\n\n\ndef batch_plan_path(target_feature_dir: Path, batch_id: str) -> Path:\n    if not BATCH_ID_RE.fullmatch(batch_id):\n        raise PlanJsonError(f\"invalid_batch_id:{batch_id}\")\n    return target_feature_dir / \"plans\" / batch_id / \"plan.json\"\n\n\ndef normalize_status(status: Any) -> str:\n    if not isinstance(status, str):\n        return \"\"\n    raw = status.strip()\n    lowered = raw.lower().replace(\" \", \"_\")\n    if raw in TODO_STATUSES or lowered in TODO_STATUSES:\n        return \"todo\"\n    if raw in IN_PROGRESS_STATUSES or lowered in IN_PROGRESS_STATUSES:\n        return \"in_progress\"\n    if raw in IMPLEMENTED_STATUSES or lowered in IMPLEMENTED_STATUSES:\n        return \"implemented\"\n    if raw in VALIDATING_STATUSES or lowered in VALIDATING_STATUSES:\n        return \"validating\"\n    if raw in DONE_STATUSES or lowered in DONE_STATUSES:\n        return \"done\"\n    if raw in FAILED_STATUSES or lowered in FAILED_STATUSES:\n        return \"failed\"\n    return \"\"\n\n\ndef task_execution_lane(task: dict[str, Any]) -> str:\n    return \"frontend\" if task.get(\"uiRequired\") is True else \"backend\"\n\n\ndef implementation_scope_task_errors(scope: Any, tasks: list[dict[str, Any]]) -> list[str]:\n    \"\"\"Reject tasks outside the Feature's selected implementation scope.\"\"\"\n\n    if scope is None:\n        return []\n    if scope not in IMPLEMENTATION_SCOPES:\n        return [\"plan_json_implementationScope_invalid\"]\n    if scope == \"full_stack\":\n        return []\n    errors: list[str] = []\n    expected_lane = \"backend\" if scope == \"backend_only\" else \"frontend\"\n    for task in tasks:\n        task_id = str(task.get(\"id\", \"task\"))\n        actual_lane = task_execution_lane(task)\n        if actual_lane != expected_lane:\n            errors.append(\n                f\"{task_id}.implementation_scope_{expected_lane}_only_required:{scope}\"\n            )\n    return errors\n\n\ndef task_execution_mode(task: dict[str, Any]) -> str:\n    \"\"\"Return the structured execution mode, defaulting legacy plans to code.\"\"\"\n\n    value = task.get(\"executionMode\")\n    return value if isinstance(value, str) and value in TASK_EXECUTION_MODES else \"code\"\n\n\ndef defer_to_test_stages_enabled(data: dict[str, Any]) -> bool:\n    \"\"\"Return whether the current Review/UTest validation policy is enabled.\"\"\"\n    policy = data.get(\"taskValidationPolicy\")\n    return (\n        isinstance(policy, dict)\n        and policy.get(\"mode\") == \"defer_to_test_stages\"\n        and policy.get(\"orchestration\") == \"inline\"\n        and policy.get(\"codeGate\") == \"review_only\"\n    )\n\n\ndef normalize_repository_relative_path(value: Any) -> str | None:\n    if not isinstance(value, str) or not value.strip():\n        return None\n    raw = value.strip()\n    if raw == \".\":\n        return \".\"\n    slash_normalized = raw.replace(\"\\\\\", \"/\")\n    posix_path = PurePosixPath(slash_normalized)\n    windows_path = PureWindowsPath(raw)\n    if (\n        not slash_normalized\n        or posix_path.is_absolute()\n        or windows_path.is_absolute()\n        or bool(windows_path.drive)\n        or \"..\" in posix_path.parts\n    ):\n        return None\n    normalized = slash_normalized.strip(\"/\")\n    return posix_path.as_posix()\n\n\ndef _validate_code_workspace_bindings(\n    errors: list[str],\n    data: dict[str, Any],\n    batch_workspace_refs: set[str],\n) -> None:\n    \"\"\"Validate the top-level runtime mapping without touching the filesystem.\"\"\"\n    raw = data.get(\"codeWorkspaces\")\n    if raw is None:\n        return  # Backward-compatible read of Plans created before this contract.\n    if not isinstance(raw, dict) or not raw:\n        errors.append(\"plan_json_codeWorkspaces_must_be_non_empty_object\")\n        return\n    for repository, path in raw.items():\n        if not isinstance(repository, str) or not REPOSITORY_ID_RE.fullmatch(repository):\n            errors.append(f\"plan_json_codeWorkspaces_repository_invalid:{repository}\")\n        if not isinstance(path, str) or not path.strip():\n            errors.append(f\"plan_json_codeWorkspaces_path_missing:{repository}\")\n            continue\n        if not (Path(path).expanduser().is_absolute() or PureWindowsPath(path).is_absolute()):\n            errors.append(f\"plan_json_codeWorkspaces_path_must_be_absolute:{repository}\")\n    missing = sorted(batch_workspace_refs - set(raw))\n    unexpected = sorted(set(raw) - batch_workspace_refs)\n    if missing:\n        errors.append(\"plan_json_codeWorkspaces_missing_refs:\" + \",\".join(missing))\n    if unexpected:\n        errors.append(\"plan_json_codeWorkspaces_unknown_refs:\" + \",\".join(unexpected))\n\n\ndef task_workspace_roots(task: dict[str, Any]) -> dict[str, str]:\n    scope = task.get(\"scope\")\n    raw_roots = scope.get(\"workspaceRoots\") if isinstance(scope, dict) else None\n    if not isinstance(raw_roots, dict):\n        return {}\n    roots: dict[str, str] = {}\n    for key, value in raw_roots.items():\n        normalized = normalize_repository_relative_path(value)\n        if isinstance(key, str) and normalized is not None:\n            roots[key] = normalized\n    return roots\n\n\ndef repository_path_within_workspace(path: str, workspace_root: str) -> bool:\n    normalized_path = normalize_repository_relative_path(path)\n    normalized_root = normalize_repository_relative_path(workspace_root)\n    if normalized_path is None or normalized_root is None:\n        return False\n    if normalized_root == \".\":\n        return True\n    return normalized_path == normalized_root or normalized_path.startswith(f\"{normalized_root}/\")\n\n\ndef _string_list(value: Any) -> list[str] | None:\n    if not isinstance(value, list):\n        return None\n    result: list[str] = []\n    for item in value:\n        if not isinstance(item, str):\n            return None\n        stripped = item.strip()\n        if stripped:\n            result.append(stripped)\n    return result\n\n\ndef _validate_string_list(\n    errors: list[str],\n    task: dict[str, Any],\n    task_id: str,\n    field: str,\n    *,\n    required: bool = True,\n    item_re: re.Pattern[str] | None = None,\n) -> list[str]:\n    values = _string_list(task.get(field))\n    if values is None:\n        errors.append(f\"{task_id}.{field}_must_be_string_array\")\n        return []\n    if required and not values:\n        errors.append(f\"{task_id}.{field}_missing\")\n    if item_re is not None:\n        for value in values:\n            if not item_re.fullmatch(value):\n                errors.append(f\"{task_id}.{field}_invalid:{value}\")\n    return values\n\n\ndef load_plan(path: Path) -> dict[str, Any]:\n    if not path.is_file() or path.stat().st_size <= 0:\n        raise PlanJsonError(f\"missing_plan_json:{path}\")\n    try:\n        data = json.loads(path.read_text(encoding=\"utf-8\"))\n    except json.JSONDecodeError as exc:\n        raise PlanJsonError(f\"invalid_plan_json:{path}:{exc}\") from exc\n    if not isinstance(data, dict):\n        raise PlanJsonError(f\"invalid_plan_json_root:{path}\")\n    return data\n\n\ndef _validate_tasks_container(\n    data: Any,\n    *,\n    require_initial_status: bool = False,\n    require_all_done: bool = False,\n    known_task_ids: set[str] | None = None,\n    defer_to_test_stages: bool = False,\n) -> list[str]:\n    errors: list[str] = []\n    if not isinstance(data, dict):\n        return [\"plan_json_root_must_be_object\"]\n\n    feature_id = data.get(\"featureId\")\n    if not isinstance(feature_id, str) or not feature_id.strip():\n        errors.append(\"plan_json_missing_feature_id\")\n\n    tasks = data.get(\"tasks\")\n    if not isinstance(tasks, list) or not tasks:\n        errors.append(\"plan_json_missing_tasks\")\n        return errors\n\n    task_ids: list[str] = []\n    deps_by_task: dict[str, list[str]] = {}\n    for index, raw_task in enumerate(tasks):\n        if not isinstance(raw_task, dict):\n            errors.append(f\"tasks[{index}]_must_be_object\")\n            continue\n        task_id = raw_task.get(\"id\")\n        if not isinstance(task_id, str) or not TASK_ID_RE.match(task_id):\n            errors.append(f\"tasks[{index}].id_invalid\")\n            task_id = f\"tasks[{index}]\"\n        elif task_id in task_ids:\n            errors.append(f\"duplicate_task_id:{task_id}\")\n        task_ids.append(task_id)\n\n        title = raw_task.get(\"title\")\n        if not isinstance(title, str) or not title.strip():\n            errors.append(f\"{task_id}.title_missing\")\n\n        _validate_task_details(errors, raw_task, task_id)\n\n        status = normalize_status(raw_task.get(\"status\"))\n        if not status:\n            errors.append(f\"{task_id}.status_invalid\")\n        elif require_initial_status and status != \"todo\":\n            errors.append(f\"{task_id}.status_not_initial\")\n        elif require_all_done and status != \"done\":\n            errors.append(f\"{task_id}.status_not_done\")\n\n        deps = _validate_string_list(errors, raw_task, task_id, \"deps\", required=False, item_re=TASK_ID_RE)\n        deps_by_task[task_id] = deps\n        if task_id in deps:\n            errors.append(f\"{task_id}.dependency_self_cycle\")\n\n        spec_refs = _validate_string_list(errors, raw_task, task_id, \"specRefs\")\n        if spec_refs and not any(REQ_ID_RE.search(ref) for ref in spec_refs):\n            errors.append(f\"{task_id}.specRefs_missing_requirement_id\")\n        if spec_refs and not any(SCN_ID_RE.search(ref) for ref in spec_refs):\n            errors.append(f\"{task_id}.specRefs_missing_scenario_id\")\n\n        _validate_string_list(errors, raw_task, task_id, \"designRefs\", required=False)\n        if \"mergedScenarioRefs\" in raw_task:\n            _validate_string_list(errors, raw_task, task_id, \"mergedScenarioRefs\", required=False)\n        _validate_string_list(errors, raw_task, task_id, \"apiIds\", required=False, item_re=API_ID_RE)\n        _validate_string_list(errors, raw_task, task_id, \"dataIds\", required=False, item_re=DATA_ID_RE)\n        _validate_string_list(\n            errors,\n            raw_task,\n            task_id,\n            \"decisionIds\",\n            required=False,\n            item_re=TECH_DECISION_ID_RE,\n        )\n        evidence_ids = _validate_string_list(\n            errors,\n            raw_task,\n            task_id,\n            \"evidenceIds\",\n            required=False,\n            item_re=EVIDENCE_ID_RE,\n        )\n        if require_all_done and not evidence_ids:\n            errors.append(f\"{task_id}.evidenceIds_missing\")\n        implementation_ids = _validate_string_list(\n            errors,\n            raw_task,\n            task_id,\n            \"implementationEvidenceIds\",\n            required=False,\n            item_re=EVIDENCE_ID_RE,\n        ) if \"implementationEvidenceIds\" in raw_task else []\n        validation_ids = _validate_string_list(\n            errors,\n            raw_task,\n            task_id,\n            \"validationEvidenceIds\",\n            required=False,\n            item_re=EVIDENCE_ID_RE,\n        ) if \"validationEvidenceIds\" in raw_task else []\n        for evidence_id in [*implementation_ids, *validation_ids]:\n            if evidence_id not in evidence_ids:\n                errors.append(f\"{task_id}.runtimeEvidenceId_not_in_evidenceIds:{evidence_id}\")\n        latest_implementation = raw_task.get(\"latestImplementationEvidenceId\")\n        if (\n            (implementation_ids and latest_implementation != implementation_ids[-1])\n            or (not implementation_ids and latest_implementation is not None)\n        ):\n            errors.append(f\"{task_id}.latestImplementationEvidenceId_invalid\")\n        revision = raw_task.get(\"implementationRevision\")\n        if revision is not None and (not isinstance(revision, int) or isinstance(revision, bool) or revision < 0):\n            errors.append(f\"{task_id}.implementationRevision_invalid\")\n        elif revision is not None and revision != len(implementation_ids):\n            errors.append(f\"{task_id}.implementationRevision_evidence_mismatch\")\n        repair_attempts = raw_task.get(\"validationRepairAttempts\", 0)\n        if (\n            not isinstance(repair_attempts, int)\n            or isinstance(repair_attempts, bool)\n            or repair_attempts < 0\n        ):\n            errors.append(f\"{task_id}.validationRepairAttempts_invalid\")\n        disposition = raw_task.get(\"validationDisposition\")\n        if disposition is not None:\n            _validate_validation_deferral(\n                errors,\n                disposition,\n                context=f\"{task_id}.validationDisposition\",\n                expected_scope=\"task\",\n            )\n            if isinstance(disposition, dict) and disposition.get(\"taskId\") != task_id:\n                errors.append(f\"{task_id}.validationDisposition.taskId_mismatch\")\n        completion_evidence_ids = _validate_string_list(\n            errors,\n            raw_task,\n            task_id,\n            \"completionEvidenceIds\",\n            required=False,\n            item_re=EVIDENCE_ID_RE,\n        )\n        for completion_id in completion_evidence_ids:\n            if completion_id not in evidence_ids:\n                errors.append(f\"{task_id}.completionEvidenceId_not_in_evidenceIds:{completion_id}\")\n        latest_pass = raw_task.get(\"latestPassEvidenceId\")\n        if latest_pass is not None and (\n            not isinstance(latest_pass, str) or not EVIDENCE_ID_RE.fullmatch(latest_pass)\n        ):\n            errors.append(f\"{task_id}.latestPassEvidenceId_invalid\")\n        if require_all_done:\n            # defer_to_test_stages 下任务 done 不强制要求 completion evidence；\n            # Review/UTest/Merge Train 负责后续验证闭环。\n            validation_deferred = isinstance(disposition, dict)\n            defer_to_test = defer_to_test_stages\n\n            if not completion_evidence_ids and not validation_deferred and not defer_to_test:\n                errors.append(f\"{task_id}.completionEvidenceIds_missing\")\n            if validation_deferred and latest_pass is not None:\n                errors.append(f\"{task_id}.latestPassEvidenceId_forbidden_when_deferred\")\n            elif not validation_deferred and not defer_to_test and (not isinstance(latest_pass, str) or not latest_pass):\n                errors.append(f\"{task_id}.latestPassEvidenceId_missing\")\n            elif isinstance(latest_pass, str) and latest_pass not in completion_evidence_ids:\n                errors.append(f\"{task_id}.latestPassEvidenceId_not_completion_evidence:{latest_pass}\")\n            elif isinstance(latest_pass, str) and latest_pass != completion_evidence_ids[-1]:\n                errors.append(f\"{task_id}.latestPassEvidenceId_not_latest:{latest_pass}\")\n        _validate_string_list(errors, raw_task, task_id, \"expectedFiles\", required=False)\n        if \"sourceRefs\" in raw_task:\n            _validate_string_list(\n                errors, raw_task, task_id, \"sourceRefs\", required=False, item_re=SOURCE_ID_RE,\n            )\n        blockers = _validate_string_list(errors, raw_task, task_id, \"blockers\", required=False)\n        if require_all_done and blockers:\n            errors.append(f\"{task_id}.blockers_unresolved\")\n\n        ui_required = raw_task.get(\"uiRequired\")\n        is_ui_required = ui_required is True\n        if ui_required is not None and not isinstance(ui_required, bool):\n            errors.append(f\"{task_id}.uiRequired_must_be_bool\")\n        ui_refs = raw_task.get(\"uiRefs\")\n        if ui_refs is None:\n            if is_ui_required:\n                errors.append(f\"{task_id}.uiRefs_missing\")\n        elif not isinstance(ui_refs, dict):\n            errors.append(f\"{task_id}.uiRefs_must_be_object\")\n        else:\n            for field, item_re in (\n                (\"pageRefs\", PAGE_ID_RE),\n                (\"interactionRefs\", INTERACTION_ID_RE),\n                (\"visualSourceRefs\", VISUAL_SOURCE_ID_RE),\n            ):\n                if field not in ui_refs and is_ui_required:\n                    errors.append(f\"{task_id}.uiRefs.{field}_missing\")\n                elif field in ui_refs:\n                    _validate_string_list(errors, ui_refs, task_id, field, required=False, item_re=item_re)\n            frontend_route = ui_refs.get(\"frontendRoute\")\n            if frontend_route is None and is_ui_required:\n                errors.append(f\"{task_id}.uiRefs.frontendRoute_missing\")\n            elif frontend_route is not None and (\n                not isinstance(frontend_route, str) or frontend_route not in FRONTEND_ROUTES\n            ):\n                errors.append(f\"{task_id}.uiRefs.frontendRoute_invalid\")\n\n    known_ids = known_task_ids or {task_id for task_id in task_ids if TASK_ID_RE.match(task_id)}\n    for task_id, deps in deps_by_task.items():\n        for dep in deps:\n            if dep not in known_ids:\n                errors.append(f\"{task_id}.dependency_unknown:{dep}\")\n    errors.extend(_dag_errors(deps_by_task))\n    return errors\n\n\ndef atomic_group_errors(\n    task_items: list[dict[str, Any]],\n    *,\n    allow_incomplete: bool = False,\n) -> list[str]:\n    \"\"\"Validate the cross-Task contract for explicit atomic delivery groups.\"\"\"\n\n    groups: dict[str, list[dict[str, Any]]] = {}\n    for task in task_items:\n        raw = task.get(\"atomicGroup\")\n        if raw is None:\n            continue\n        task_id = str(task.get(\"id\", \"task\"))\n        if not isinstance(raw, dict):\n            continue  # The per-Task validator reports the shape error.\n        group_id = raw.get(\"id\")\n        if isinstance(group_id, str) and ATOMIC_GROUP_ID_RE.fullmatch(group_id):\n            groups.setdefault(group_id, []).append(task)\n\n    errors: list[str] = []\n    for group_id, members in groups.items():\n        member_ids = \",\".join(str(item.get(\"id\")) for item in members)\n        if len(members) == 1 and not allow_incomplete:\n            errors.append(f\"atomicGroup.{group_id}_requires_two_or_three_tasks:taskIds={member_ids}\")\n            continue\n        if len(members) > MAX_BATCH_TASKS:\n            errors.append(f\"atomicGroup.{group_id}_task_limit_exceeded:{len(members)}>{MAX_BATCH_TASKS}\")\n        workspace_refs = {item.get(\"workspaceRef\") for item in members}\n        lanes = {task_execution_lane(item) for item in members}\n        stages = {str(item.get(\"executionStage\") or \"parallel\") for item in members}\n        rationales = {\n            str(item.get(\"atomicGroup\", {}).get(\"rationale\")).strip()\n            for item in members\n            if isinstance(item.get(\"atomicGroup\"), dict)\n        }\n        if len(workspace_refs) > 1:\n            errors.append(f\"atomicGroup.{group_id}_workspaceRef_mismatch:taskIds={member_ids}\")\n        if len(lanes) > 1:\n            errors.append(f\"atomicGroup.{group_id}_executionLane_mismatch:taskIds={member_ids}\")\n        if len(stages) > 1:\n            errors.append(f\"atomicGroup.{group_id}_executionStage_mismatch:taskIds={member_ids}\")\n        if len(rationales) > 1:\n            errors.append(f\"atomicGroup.{group_id}_rationale_mismatch:taskIds={member_ids}\")\n    return errors\n\n\ndef validate_plan_data(\n    data: Any,\n    *,\n    require_initial_status: bool = False,\n    require_all_done: bool = False,\n) -> list[str]:\n    \"\"\"Validate the root batch index. Task contracts live in batch plans.\"\"\"\n\n    errors: list[str] = []\n    if not isinstance(data, dict):\n        return [\"plan_json_root_must_be_object\"]\n    if \"tasks\" in data:\n        errors.append(\"monolithic_plan_requires_rebuild\")\n    if \"version\" in data or \"taskDetailVersion\" in data:\n        errors.append(\"legacy_plan_requires_rebuild\")\n    feature_id = data.get(\"featureId\")\n    if not isinstance(feature_id, str) or not feature_id.strip():\n        errors.append(\"plan_json_missing_feature_id\")\n    implementation_scope = data.get(\"implementationScope\")\n    if implementation_scope is not None and implementation_scope not in IMPLEMENTATION_SCOPES:\n        errors.append(\"plan_json_implementationScope_invalid\")\n    if data.get(\"taskSetStatus\") not in TASK_SET_STATUSES:\n        errors.append(\"plan_json_taskSetStatus_invalid\")\n    status = data.get(\"status\")\n    if status not in FEATURE_STATUSES:\n        errors.append(\"plan_json_status_invalid\")\n    elif require_initial_status and status != \"todo\":\n        errors.append(\"plan_json_status_not_initial\")\n    elif require_all_done and status != \"done\":\n        errors.append(\"plan_json_status_not_done\")\n\n    policy = data.get(\"batchPolicy\")\n    if not isinstance(policy, dict):\n        errors.append(\"plan_json_batchPolicy_missing\")\n    else:\n        strategy = policy.get(\"strategy\")\n        if strategy == BATCH_STRATEGY:\n            if policy.get(\"maxTasks\") != MAX_BATCH_TASKS:\n                errors.append(f\"plan_json_batchPolicy_maxTasks_must_be:{MAX_BATCH_TASKS}\")\n        else:\n            errors.append(f\"plan_json_batchPolicy_strategy_must_be:{BATCH_STRATEGY}\")\n    _validate_task_validation_policy(errors, data)\n\n    raw_batches = data.get(\"batches\")\n    batch_ids: list[str] = []\n    if not isinstance(raw_batches, list) or not raw_batches:\n        errors.append(\"plan_json_missing_batches\")\n    else:\n        for index, entry in enumerate(raw_batches):\n            context = f\"batches[{index}]\"\n            if not isinstance(entry, dict):\n                errors.append(f\"{context}_must_be_object\")\n                continue\n            batch_id = entry.get(\"id\")\n            if not isinstance(batch_id, str) or not BATCH_ID_RE.fullmatch(batch_id):\n                errors.append(f\"{context}.id_invalid\")\n                continue\n            if batch_id in batch_ids:\n                errors.append(f\"duplicate_batch_id:{batch_id}\")\n            batch_ids.append(batch_id)\n            expected_path = f\"plans/{batch_id}/plan.json\"\n            if entry.get(\"path\") != expected_path:\n                errors.append(f\"{batch_id}.path_invalid\")\n            if not isinstance(entry.get(\"title\"), str) or not str(entry.get(\"title\")).strip():\n                errors.append(f\"{batch_id}.title_missing\")\n            if entry.get(\"executionLane\") not in EXECUTION_LANES:\n                errors.append(f\"{batch_id}.executionLane_invalid\")\n            workspace_ref = entry.get(\"workspaceRef\")\n            if workspace_ref is not None and (\n                not isinstance(workspace_ref, str) or not workspace_ref.strip()\n            ):\n                errors.append(f\"{batch_id}.workspaceRef_invalid\")\n            if \"executionStage\" in entry and entry.get(\"executionStage\") not in PARALLEL_EXECUTION_STAGES:\n                errors.append(f\"{batch_id}.executionStage_invalid\")\n            _validate_string_list(errors, entry, batch_id, \"specRoots\", required=True)\n            _validate_string_list(errors, entry, batch_id, \"deps\", required=False, item_re=BATCH_ID_RE)\n            task_ids = _validate_string_list(errors, entry, batch_id, \"taskIds\", required=True, item_re=TASK_ID_RE)\n            delivery_kind = entry.get(\"deliveryKind\")\n            if delivery_kind not in {\"single_task\", \"atomic_group\"}:\n                errors.append(f\"{batch_id}.deliveryKind_invalid\")\n            elif delivery_kind == \"single_task\":\n                if len(task_ids) != 1:\n                    errors.append(f\"{batch_id}.single_task_requires_one_task\")\n                if \"atomicGroupId\" in entry or \"batchRationale\" in entry:\n                    errors.append(f\"{batch_id}.single_task_atomic_fields_forbidden\")\n            else:\n                group_id = entry.get(\"atomicGroupId\")\n                rationale = entry.get(\"batchRationale\")\n                if not isinstance(group_id, str) or not ATOMIC_GROUP_ID_RE.fullmatch(group_id):\n                    errors.append(f\"{batch_id}.atomicGroupId_invalid\")\n                if not isinstance(rationale, str) or len(rationale.strip()) < 10:\n                    errors.append(f\"{batch_id}.batchRationale_missing_or_too_short\")\n                if len(task_ids) > MAX_BATCH_TASKS:\n                    errors.append(f\"{batch_id}.atomic_group_task_limit_invalid\")\n            batch_status = entry.get(\"status\")\n            if batch_status not in BATCH_STATUSES:\n                errors.append(f\"{batch_id}.status_invalid\")\n            elif require_initial_status and batch_status != \"todo\":\n                errors.append(f\"{batch_id}.status_not_initial\")\n            elif require_all_done and batch_status != \"done\":\n                errors.append(f\"{batch_id}.status_not_done\")\n\n    used_lanes = {\n        str(entry.get(\"executionLane\"))\n        for entry in raw_batches or []\n        if isinstance(entry, dict) and entry.get(\"executionLane\") in EXECUTION_LANES\n    }\n    batch_workspace_refs = {\n        str(entry.get(\"workspaceRef\"))\n        for entry in raw_batches or []\n        if isinstance(entry, dict)\n        and isinstance(entry.get(\"workspaceRef\"), str)\n        and entry.get(\"workspaceRef\")\n    }\n    _validate_code_workspace_bindings(errors, data, batch_workspace_refs)\n\n    known_batches = set(batch_ids)\n    for field in (\"activeBatchId\", \"nextBatchId\"):\n        value = data.get(field)\n        if value is not None and (not isinstance(value, str) or value not in known_batches):\n            errors.append(f\"plan_json_{field}_invalid\")\n    if require_all_done and (data.get(\"activeBatchId\") is not None or data.get(\"nextBatchId\") is not None):\n        errors.append(\"plan_json_done_with_pending_batch_pointer\")\n\n    return errors\n\n\ndef validate_batch_plan_data(\n    data: Any,\n    *,\n    expected_feature_id: str | None = None,\n    expected_batch_id: str | None = None,\n    known_task_ids: set[str] | None = None,\n    require_initial_status: bool = False,\n    require_all_done: bool = False,\n    defer_to_test_stages: bool = False,\n) -> list[str]:\n    errors: list[str] = []\n    if not isinstance(data, dict):\n        return [\"batch_plan_root_must_be_object\"]\n    if \"version\" in data or \"taskDetailVersion\" in data:\n        errors.append(\"legacy_plan_requires_rebuild\")\n    feature_id = data.get(\"featureId\")\n    if not isinstance(feature_id, str) or not feature_id.strip():\n        errors.append(\"batch_plan_missing_feature_id\")\n    elif expected_feature_id is not None and feature_id != expected_feature_id:\n        errors.append(f\"batch_plan_feature_mismatch:{feature_id}\")\n    batch_id = data.get(\"batchId\")\n    if not isinstance(batch_id, str) or not BATCH_ID_RE.fullmatch(batch_id):\n        errors.append(\"batch_plan_id_invalid\")\n        batch_id = \"batch\"\n    elif expected_batch_id is not None and batch_id != expected_batch_id:\n        errors.append(f\"batch_plan_id_mismatch:{batch_id}\")\n    if data.get(\"executionLane\") not in EXECUTION_LANES:\n        errors.append(f\"{batch_id}.executionLane_invalid\")\n    if not isinstance(data.get(\"title\"), str) or not str(data.get(\"title\")).strip():\n        errors.append(f\"{batch_id}.title_missing\")\n    status = data.get(\"status\")\n    if status not in BATCH_STATUSES:\n        errors.append(f\"{batch_id}.status_invalid\")\n    elif require_initial_status and status != \"todo\":\n        errors.append(f\"{batch_id}.status_not_initial\")\n    elif require_all_done and status != \"done\":\n        errors.append(f\"{batch_id}.status_not_done\")\n\n    batch_tasks = tasks(data)\n    if len(batch_tasks) > MAX_BATCH_TASKS:\n        errors.append(f\"{batch_id}.batch_task_limit_exceeded:{len(batch_tasks)}>{MAX_BATCH_TASKS}\")\n    if data.get(\"taskCount\") != len(batch_tasks):\n        errors.append(f\"{batch_id}.taskCount_mismatch\")\n    completed_count = sum(normalize_status(item.get(\"status\")) == \"done\" for item in batch_tasks)\n    if data.get(\"completedTaskCount\") != completed_count:\n        errors.append(f\"{batch_id}.completedTaskCount_mismatch\")\n    if \"taskValidation\" in data:\n        errors.append(f\"{batch_id}.taskValidation_forbidden\")\n    delivery_kind = data.get(\"deliveryKind\")\n    if delivery_kind not in {\"single_task\", \"atomic_group\"}:\n        errors.append(f\"{batch_id}.deliveryKind_invalid\")\n    elif delivery_kind == \"single_task\":\n        if len(batch_tasks) != 1:\n            errors.append(f\"{batch_id}.single_task_requires_one_task\")\n        if \"atomicGroupId\" in data or \"batchRationale\" in data:\n            errors.append(f\"{batch_id}.single_task_atomic_fields_forbidden\")\n    elif delivery_kind == \"atomic_group\":\n        group_id = data.get(\"atomicGroupId\")\n        rationale = data.get(\"batchRationale\")\n        if not isinstance(group_id, str) or not ATOMIC_GROUP_ID_RE.fullmatch(group_id):\n            errors.append(f\"{batch_id}.atomicGroupId_invalid\")\n        if not isinstance(rationale, str) or len(rationale.strip()) < 10:\n            errors.append(f\"{batch_id}.batchRationale_missing_or_too_short\")\n        if len(batch_tasks) > MAX_BATCH_TASKS:\n            errors.append(f\"{batch_id}.atomic_group_task_limit_invalid\")\n    workspace_root_sets = [\n        task_workspace_roots(item)\n        for item in batch_tasks\n        if task_workspace_roots(item)\n    ]\n    workspace_refs = {\n        item.get(\"workspaceRef\")\n        for item in batch_tasks\n        if isinstance(item.get(\"workspaceRef\"), str)\n    }\n    if len(workspace_refs) > 1:\n        errors.append(f\"{batch_id}.mixed_task_workspace_refs\")\n    workspace_roots = workspace_root_sets[0] if workspace_root_sets else {}\n    if any(item != workspace_roots for item in workspace_root_sets[1:]):\n        errors.append(f\"{batch_id}.mixed_task_workspace_roots\")\n    frontend_routes = {\n        ui_refs.get(\"frontendRoute\")\n        for item in batch_tasks\n        if item.get(\"uiRequired\") is True\n        for ui_refs in [item.get(\"uiRefs\")]\n        if isinstance(ui_refs, dict) and isinstance(ui_refs.get(\"frontendRoute\"), str)\n    }\n    if len(frontend_routes) > 1:\n        errors.append(f\"{batch_id}.mixed_task_frontend_routes\")\n    _validate_string_list(errors, data, str(batch_id), \"completionEvidenceIds\", required=False, item_re=EVIDENCE_ID_RE)\n    for field in (\"startedAt\", \"completedAt\"):\n        value = data.get(field)\n        if value is not None and (not isinstance(value, str) or not value.strip()):\n            errors.append(f\"{batch_id}.{field}_invalid\")\n    errors.extend(\n        _validate_tasks_container(\n            data,\n            require_initial_status=require_initial_status,\n            require_all_done=require_all_done,\n            known_task_ids=known_task_ids,\n            defer_to_test_stages=defer_to_test_stages,\n        )\n    )\n    return errors\n\n\ndef _validate_acceptance_criteria(errors: list[str], task: dict[str, Any], task_id: str) -> None:\n    criteria = task.get(\"acceptanceCriteria\")\n    if not isinstance(criteria, list):\n        errors.append(f\"{task_id}.acceptanceCriteria_must_be_array\")\n        return\n    if not criteria:\n        errors.append(f\"{task_id}.acceptanceCriteria_missing\")\n        return\n    seen: set[str] = set()\n    task_scenario_ids = {\n        match.group(0)\n        for ref in (_string_list(task.get(\"specRefs\")) or [])\n        for match in SCN_ID_RE.finditer(ref)\n    }\n    for index, criterion in enumerate(criteria):\n        context = f\"{task_id}.acceptanceCriteria[{index}]\"\n        if not isinstance(criterion, dict):\n            errors.append(f\"{context}_must_be_object\")\n            continue\n        criterion_id = criterion.get(\"id\")\n        if not isinstance(criterion_id, str) or not ACCEPTANCE_ID_RE.fullmatch(criterion_id):\n            errors.append(f\"{context}.id_invalid\")\n        elif not criterion_id.startswith(f\"AC-{task_id}-\"):\n            errors.append(f\"{context}.id_task_mismatch:{criterion_id}\")\n        elif criterion_id in seen:\n            errors.append(f\"{task_id}.acceptanceCriteria_duplicate:{criterion_id}\")\n        else:\n            seen.add(criterion_id)\n        text = criterion.get(\"text\")\n        if not isinstance(text, str) or not text.strip():\n            errors.append(f\"{context}.text_missing\")\n        scenario_refs = _string_list(criterion.get(\"scenarioRefs\"))\n        if scenario_refs is None:\n            errors.append(f\"{context}.scenarioRefs_must_be_string_array\")\n        elif not scenario_refs or not all(SCN_ID_RE.search(ref) for ref in scenario_refs):\n            errors.append(f\"{context}.scenarioRefs_missing_scenario_id\")\n        else:\n            criterion_scenario_ids = {\n                match.group(0)\n                for ref in scenario_refs\n                for match in SCN_ID_RE.finditer(ref)\n            }\n            for scenario_id in sorted(criterion_scenario_ids - task_scenario_ids):\n                errors.append(f\"{context}.scenario_not_in_task_specRefs:{scenario_id}\")\n\n\ndef _validate_task_validation_policy(errors: list[str], data: dict[str, Any]) -> None:\n    policy = data.get(\"taskValidationPolicy\")\n    if policy is None:\n        errors.append(\"taskValidationPolicy_missing\")\n        return\n    if not isinstance(policy, dict):\n        errors.append(\"taskValidationPolicy_must_be_object\")\n        return\n    if policy.get(\"mode\") not in TASK_VALIDATION_POLICY_MODES:\n        errors.append(\"taskValidationPolicy.mode_invalid\")\n\n    if policy.get(\"orchestration\") != \"inline\":\n        errors.append(\"taskValidationPolicy.orchestration_must_be_inline\")\n    if policy.get(\"codeGate\") != \"review_only\":\n        errors.append(\"taskValidationPolicy.codeGate_must_be_review_only\")\n    if policy.get(\"maxTestStageRepairAttempts\") != TEST_STAGE_MAX_REPAIR_ATTEMPTS:\n        errors.append(\n            f\"taskValidationPolicy.maxTestStageRepairAttempts_must_be:{TEST_STAGE_MAX_REPAIR_ATTEMPTS}\"\n        )\n    allowed_fields = {\n        \"mode\",\n        \"orchestration\",\n        \"codeGate\",\n        \"maxTestStageRepairAttempts\",\n    }\n    for field in sorted(set(policy) - allowed_fields):\n        errors.append(f\"taskValidationPolicy.{field}_forbidden\")\n\n\ndef _validate_validation_deferral(\n    errors: list[str],\n    issue: Any,\n    *,\n    context: str,\n    expected_scope: str | None = None,\n) -> None:\n    if not isinstance(issue, dict):\n        errors.append(f\"{context}_must_be_object\")\n        return\n    if not isinstance(issue.get(\"issueId\"), str) or not issue.get(\"issueId\", \"\").strip():\n        errors.append(f\"{context}.issueId_invalid\")\n    scope = issue.get(\"scope\")\n    if scope not in VALIDATION_DEFERRAL_SCOPES or (\n        expected_scope is not None and scope != expected_scope\n    ):\n        errors.append(f\"{context}.scope_invalid\")\n    if issue.get(\"status\") != VALIDATION_DEFERRAL_STATUS:\n        errors.append(f\"{context}.status_invalid\")\n    if issue.get(\"reason\") not in VALIDATION_DEFERRAL_REASONS:\n        errors.append(f\"{context}.reason_invalid\")\n    if issue.get(\"errorCategory\") not in TASK_VALIDATION_ERROR_CATEGORIES:\n        errors.append(f\"{context}.errorCategory_invalid\")\n    command_id = issue.get(\"commandId\")\n    if command_id is not None and (not isinstance(command_id, str) or not command_id.strip()):\n        errors.append(f\"{context}.commandId_invalid\")\n    attempts = issue.get(\"repairAttempts\")\n    if not isinstance(attempts, int) or isinstance(attempts, bool) or attempts < 0:\n        errors.append(f\"{context}.repairAttempts_invalid\")\n    max_attempts = issue.get(\"maxRepairAttempts\")\n    if not isinstance(max_attempts, int) or isinstance(max_attempts, bool) or max_attempts < 0:\n        errors.append(f\"{context}.maxRepairAttempts_invalid\")\n    evidence_ids = _string_list(issue.get(\"evidenceIds\"))\n    if evidence_ids is None or any(not EVIDENCE_ID_RE.fullmatch(item) for item in evidence_ids):\n        errors.append(f\"{context}.evidenceIds_invalid\")\n    owner_stages = _string_list(issue.get(\"handoffStages\"))\n    if owner_stages is None or not owner_stages:\n        errors.append(f\"{context}.handoffStages_invalid\")\n    if not isinstance(issue.get(\"createdAt\"), str) or not issue.get(\"createdAt\", \"\").strip():\n        errors.append(f\"{context}.createdAt_invalid\")\n\n\ndef _validate_task_details(\n    errors: list[str],\n    task: dict[str, Any],\n    task_id: str,\n) -> None:\n    atomic_group = task.get(\"atomicGroup\")\n    if atomic_group is not None:\n        if not isinstance(atomic_group, dict):\n            errors.append(f\"{task_id}.atomicGroup_must_be_object\")\n        else:\n            unknown = sorted(set(atomic_group) - {\"id\", \"rationale\"})\n            if unknown:\n                errors.append(f\"{task_id}.atomicGroup_unknown_fields:{','.join(unknown)}\")\n            group_id = atomic_group.get(\"id\")\n            rationale = atomic_group.get(\"rationale\")\n            if not isinstance(group_id, str) or not ATOMIC_GROUP_ID_RE.fullmatch(group_id):\n                errors.append(f\"{task_id}.atomicGroup.id_invalid\")\n            if not isinstance(rationale, str) or len(rationale.strip()) < 10:\n                errors.append(f\"{task_id}.atomicGroup.rationale_missing_or_too_short\")\n\n    raw_execution_mode = task.get(\"executionMode\")\n    if raw_execution_mode is not None and raw_execution_mode not in TASK_EXECUTION_MODES:\n        errors.append(f\"{task_id}.executionMode_invalid\")\n    execution_mode = task_execution_mode(task)\n    external_dependency = task.get(\"externalDependency\")\n    if execution_mode == \"external_dependency\":\n        if not isinstance(external_dependency, dict):\n            errors.append(f\"{task_id}.externalDependency_missing\")\n        else:\n            for field in (\"system\", \"owner\"):\n                value = external_dependency.get(field)\n                if not isinstance(value, str) or not value.strip():\n                    errors.append(f\"{task_id}.externalDependency.{field}_missing\")\n            tracking_refs = _string_list(external_dependency.get(\"trackingRefs\"))\n            if not tracking_refs:\n                errors.append(f\"{task_id}.externalDependency.trackingRefs_missing\")\n    elif external_dependency is not None:\n        errors.append(f\"{task_id}.externalDependency_forbidden\")\n\n    goal = task.get(\"goal\")\n    if not isinstance(goal, str) or not goal.strip():\n        errors.append(f\"{task_id}.goal_missing\")\n\n    scope = task.get(\"scope\")\n    scope_pages: list[str] = []\n    scope_paths: list[str] = []\n    workspace_roots: dict[str, str] = {}\n    if not isinstance(scope, dict):\n        errors.append(f\"{task_id}.scope_must_be_object\")\n    else:\n        for field in (\"modules\", \"entrypoints\", \"pages\", \"dataObjects\", \"paths\"):\n            values = _string_list(scope.get(field))\n            if field == \"paths\" and values is None:\n                continue\n            if values is None:\n                errors.append(f\"{task_id}.scope.{field}_must_be_string_array\")\n                continue\n            if field == \"paths\":\n                scope_paths = values\n                for value in values:\n                    raw_path = value.partition(\":\")[2] if \":\" in value else value\n                    if normalize_repository_relative_path(raw_path) is None:\n                        errors.append(f\"{task_id}.scope.paths_invalid:{value}\")\n            if field == \"pages\":\n                scope_pages = values\n                for value in values:\n                    if not PAGE_ID_RE.fullmatch(value):\n                        errors.append(f\"{task_id}.scope.pages_invalid:{value}\")\n\n        raw_workspace_roots = scope.get(\"workspaceRoots\")\n        if scope_paths and not isinstance(raw_workspace_roots, dict):\n            errors.append(f\"{task_id}.scope.workspaceRoots_missing\")\n        elif raw_workspace_roots is not None:\n            if not isinstance(raw_workspace_roots, dict) or not raw_workspace_roots:\n                errors.append(f\"{task_id}.scope.workspaceRoots_must_be_object\")\n            else:\n                for key, value in raw_workspace_roots.items():\n                    if not isinstance(key, str) or (\n                        key != DEFAULT_WORKSPACE_ROOT and not REPOSITORY_ID_RE.fullmatch(key)\n                    ):\n                        errors.append(f\"{task_id}.scope.workspaceRoots_key_invalid:{key}\")\n                        continue\n                    normalized_root = normalize_repository_relative_path(value)\n                    if normalized_root is None:\n                        errors.append(f\"{task_id}.scope.workspaceRoots_path_invalid:{value}\")\n                    else:\n                        workspace_roots[key] = normalized_root\n                if DEFAULT_WORKSPACE_ROOT in workspace_roots and len(workspace_roots) != 1:\n                    errors.append(f\"{task_id}.scope.workspaceRoots_default_must_be_single\")\n                if len(workspace_roots) > 1:\n                    errors.append(f\"{task_id}.scope.workspaceRoots_multiple_forbidden\")\n\n        for value in scope_paths:\n            repository: str | None = None\n            relative = value\n            if DEFAULT_WORKSPACE_ROOT not in workspace_roots and workspace_roots:\n                repository, separator, relative = value.partition(\":\")\n                if not separator or repository not in workspace_roots:\n                    errors.append(f\"{task_id}.scope.path_workspace_prefix_invalid:{value}\")\n                    continue\n            elif \":\" in value:\n                errors.append(f\"{task_id}.scope.path_workspace_prefix_unexpected:{value}\")\n                continue\n            workspace_root = workspace_roots.get(repository or DEFAULT_WORKSPACE_ROOT)\n            normalized_relative = normalize_repository_relative_path(relative)\n            if (\n                workspace_root\n                and workspace_root != \".\"\n                and normalized_relative is not None\n                and repository_path_within_workspace(normalized_relative, workspace_root)\n            ):\n                errors.append(f\"{task_id}.scope.path_repeats_workspace_root:{value}\")\n\n    workspace_ref = task.get(\"workspaceRef\")\n    if not isinstance(workspace_ref, str) or not REPOSITORY_ID_RE.fullmatch(workspace_ref):\n        errors.append(f\"{task_id}.workspaceRef_missing_or_invalid\")\n    elif workspace_roots:\n        expected_key = DEFAULT_WORKSPACE_ROOT if workspace_ref == DEFAULT_WORKSPACE_ROOT else workspace_ref\n        if expected_key not in workspace_roots:\n            errors.append(f\"{task_id}.workspaceRef_not_in_workspaceRoots:{workspace_ref}\")\n\n    implementation_points = _string_list(task.get(\"implementationPoints\"))\n    if implementation_points is None:\n        errors.append(f\"{task_id}.implementationPoints_must_be_string_array\")\n\n    _validate_acceptance_criteria(errors, task, task_id)\n    completion_policy = task.get(\"completionPolicy\")\n    if completion_policy not in COMPLETION_POLICIES:\n        errors.append(f\"{task_id}.completionPolicy_invalid\")\n    expected_completion_policy = (\n        \"external_dependency_recorded\"\n        if execution_mode == \"external_dependency\"\n        else \"all_required_validations_pass\"\n    )\n    if completion_policy in COMPLETION_POLICIES and completion_policy != expected_completion_policy:\n        errors.append(f\"{task_id}.completionPolicy_executionMode_mismatch\")\n\n    validation_boundary = task.get(\"validationBoundary\")\n    if not isinstance(validation_boundary, str) or not validation_boundary.strip():\n        errors.append(f\"{task_id}.validationBoundary_missing\")\n\n    raw_non_goals = task.get(\"nonGoals\")\n    non_goals = _string_list(task.get(\"nonGoals\"))\n    if non_goals is None:\n        errors.append(f\"{task_id}.nonGoals_must_be_string_array\")\n    elif isinstance(raw_non_goals, list) and len(non_goals) != len(raw_non_goals):\n        errors.append(f\"{task_id}.nonGoals_empty_item\")\n\n    ui_required = task.get(\"uiRequired\") is True\n    ui_refs = task.get(\"uiRefs\")\n    page_refs: list[str] = []\n    if isinstance(ui_refs, dict):\n        page_refs = _string_list(ui_refs.get(\"pageRefs\")) or []\n    if ui_required and sorted(scope_pages) != sorted(page_refs):\n        errors.append(f\"{task_id}.scope.pages_mismatch_uiRefs\")\n\n\ndef _dag_errors(deps_by_task: dict[str, list[str]]) -> list[str]:\n    errors: list[str] = []\n    visiting: set[str] = set()\n    visited: set[str] = set()\n\n    def visit(task_id: str, stack: list[str]) -> None:\n        if task_id in visited:\n            return\n        if task_id in visiting:\n            errors.append(\"task_dependency_cycle:\" + \"->\".join([*stack, task_id]))\n            return\n        visiting.add(task_id)\n        for dep in deps_by_task.get(task_id, []):\n            if dep in deps_by_task:\n                visit(dep, [*stack, task_id])\n        visiting.remove(task_id)\n        visited.add(task_id)\n\n    for task_id in deps_by_task:\n        visit(task_id, [])\n    return errors\n\n\ndef tasks(data: dict[str, Any]) -> list[dict[str, Any]]:\n    bundle_tasks = data.get(\"_bundleTasks\")\n    if isinstance(bundle_tasks, list):\n        return [task for task in bundle_tasks if isinstance(task, dict)]\n    raw_tasks = data.get(\"tasks\")\n    return [task for task in raw_tasks if isinstance(task, dict)] if isinstance(raw_tasks, list) else []\n\n\ndef task_ids(data: dict[str, Any]) -> set[str]:\n    return {task[\"id\"] for task in tasks(data) if isinstance(task.get(\"id\"), str)}\n\n\ndef _bundle_consistency_errors(\n    root: dict[str, Any],\n    batch_data: dict[str, dict[str, Any]],\n    *,\n    require_initial_status: bool = False,\n    require_all_done: bool = False,\n) -> list[str]:\n    entries = [entry for entry in root.get(\"batches\", []) if isinstance(entry, dict)]\n    all_tasks: list[dict[str, Any]] = []\n    task_batches: dict[str, str] = {}\n    errors: list[str] = []\n    for entry in entries:\n        batch_id = str(entry.get(\"id\", \"\"))\n        data = batch_data.get(batch_id)\n        if not isinstance(data, dict):\n            errors.append(f\"missing_batch_plan:{batch_id}\")\n            continue\n        for item in tasks(data):\n            task_id = item.get(\"id\")\n            if not isinstance(task_id, str):\n                continue\n            if task_id in task_batches:\n                errors.append(f\"duplicate_task_id:{task_id}\")\n            else:\n                task_batches[task_id] = batch_id\n                all_tasks.append(item)\n    if errors:\n        return errors\n    known_task_ids = set(task_batches)\n    strategy = root.get(\"batchPolicy\", {}).get(\"strategy\") if isinstance(root.get(\"batchPolicy\"), dict) else None\n    if strategy == BATCH_STRATEGY:\n        errors.extend(atomic_group_errors(\n            all_tasks,\n            allow_incomplete=root.get(\"taskSetStatus\") == \"collecting\",\n        ))\n    batch_order = {str(entry.get(\"id\")): index for index, entry in enumerate(entries)}\n    task_by_id = {str(item.get(\"id\")): item for item in all_tasks}\n    # Plan v2 has no speculative physical write set. When a producer later\n    # records actual changes, impact analysis invalidates same-repository\n    # concurrent evidence conservatively; Merge Train handles real conflicts.\n    errors.extend(write_ownership_error_codes(\n        all_tasks,\n        ownership_scope_by_task=task_batches,\n    ))\n    deps_by_task: dict[str, list[str]] = {}\n    for entry in entries:\n        batch_id = str(entry.get(\"id\"))\n        data = batch_data[batch_id]\n        entry_lane = entry.get(\"executionLane\")\n        errors.extend(\n            validate_batch_plan_data(\n                data,\n                expected_feature_id=str(root.get(\"featureId\")),\n                expected_batch_id=batch_id,\n                known_task_ids=known_task_ids,\n                require_initial_status=require_initial_status,\n                require_all_done=require_all_done,\n                defer_to_test_stages=defer_to_test_stages_enabled(root),\n            )\n        )\n        if root.get(\"batchPolicy\", {}).get(\"strategy\") == BATCH_STRATEGY:\n            for field in (\"deliveryKind\",):\n                if entry.get(field) != data.get(field):\n                    errors.append(f\"{batch_id}.{field}_projection_mismatch\")\n            delivery_kind = entry.get(\"deliveryKind\")\n            if delivery_kind == \"atomic_group\":\n                for field in (\"atomicGroupId\", \"batchRationale\"):\n                    if entry.get(field) != data.get(field):\n                        errors.append(f\"{batch_id}.{field}_projection_mismatch\")\n            if data.get(\"deliveryKind\") is None:\n                errors.append(f\"{batch_id}.deliveryKind_missing\")\n        actual_ids = [str(item.get(\"id\")) for item in tasks(data)]\n        if entry.get(\"taskIds\") != actual_ids:\n            errors.append(f\"{batch_id}.taskIds_mismatch\")\n        if entry.get(\"status\") != data.get(\"status\"):\n            errors.append(f\"{batch_id}.root_status_projection_mismatch\")\n        if strategy == BATCH_STRATEGY:\n            task_atomic_ids = {\n                item.get(\"atomicGroup\", {}).get(\"id\")\n                for item in tasks(data)\n                if isinstance(item.get(\"atomicGroup\"), dict)\n            }\n            if entry.get(\"deliveryKind\") == \"single_task\" and task_atomic_ids:\n                errors.append(f\"{batch_id}.single_task_contains_atomic_task\")\n            if entry.get(\"deliveryKind\") == \"atomic_group\":\n                if task_atomic_ids != {entry.get(\"atomicGroupId\")}:\n                    errors.append(f\"{batch_id}.atomicGroup_task_membership_mismatch\")\n        root_lane = entry.get(\"executionLane\")\n        batch_lane = data.get(\"executionLane\")\n        if root_lane != batch_lane:\n            errors.append(f\"{batch_id}.executionLane_projection_mismatch\")\n        task_lanes = {task_execution_lane(item) for item in tasks(data)}\n        if len(task_lanes) > 1:\n            errors.append(f\"{batch_id}.mixed_execution_lanes\")\n        elif task_lanes and batch_lane not in task_lanes:\n            errors.append(f\"{batch_id}.executionLane_task_mismatch\")\n        task_workspace_refs = {\n            item.get(\"workspaceRef\")\n            for item in tasks(data)\n            if isinstance(item.get(\"workspaceRef\"), str) and item.get(\"workspaceRef\")\n        }\n        if len(task_workspace_refs) > 1:\n            errors.append(f\"{batch_id}.workspaceRef_ambiguous\")\n        elif entry.get(\"workspaceRef\") is not None and entry.get(\"workspaceRef\") not in task_workspace_refs:\n            errors.append(f\"{batch_id}.workspaceRef_projection_mismatch\")\n        if \"taskValidation\" in data:\n            errors.append(f\"{batch_id}.taskValidation_forbidden\")\n\n        declared_batch_deps = set(entry.get(\"deps\") or [])\n        for dep_batch in declared_batch_deps:\n            if dep_batch not in batch_order:\n                errors.append(f\"{batch_id}.dependency_unknown:{dep_batch}\")\n            elif batch_order[dep_batch] >= batch_order[batch_id]:\n                errors.append(f\"{batch_id}.dependency_not_earlier:{dep_batch}\")\n        required_batch_deps: set[str] = set()\n        for item in tasks(data):\n            task_id = str(item.get(\"id\"))\n            deps = [dep for dep in item.get(\"deps\", []) if isinstance(dep, str)]\n            deps_by_task[task_id] = deps\n            for dep in deps:\n                dep_batch = task_batches.get(dep)\n                if dep_batch is None:\n                    continue\n                if batch_order[dep_batch] > batch_order[batch_id]:\n                    errors.append(f\"{task_id}.dependency_not_in_earlier_batch:{dep}\")\n                elif dep_batch != batch_id:\n                    required_batch_deps.add(dep_batch)\n        for dep_batch in sorted(required_batch_deps - declared_batch_deps):\n            errors.append(f\"{batch_id}.missing_batch_dependency:{dep_batch}\")\n\n    for task_id, item in task_by_id.items():\n        for dep in item.get(\"deps\", []):\n            if isinstance(dep, str) and dep not in known_task_ids:\n                errors.append(f\"{task_id}.dependency_unknown:{dep}\")\n    errors.extend(_dag_errors(deps_by_task))\n\n    active = root.get(\"activeBatchId\")\n    next_batch = root.get(\"nextBatchId\")\n    status = root.get(\"status\")\n    if status == \"done\" and (active is not None or next_batch is not None):\n        errors.append(\"done_plan_has_pending_batch_pointer\")\n    if isinstance(active, str):\n        active_entry = next((entry for entry in entries if entry.get(\"id\") == active), None)\n        if isinstance(active_entry, dict) and active_entry.get(\"status\") == \"done\":\n            errors.append(f\"active_batch_already_done:{active}\")\n    if isinstance(next_batch, str):\n        next_entry = next((entry for entry in entries if entry.get(\"id\") == next_batch), None)\n        if isinstance(next_entry, dict) and next_entry.get(\"status\") != \"todo\":\n            errors.append(f\"next_batch_not_todo:{next_batch}\")\n    return errors\n\n\ndef validate_plan_bundle_data(\n    root: dict[str, Any],\n    batch_data: dict[str, dict[str, Any]],\n    *,\n    require_initial_status: bool = False,\n    require_all_done: bool = False,\n) -> list[str]:\n    errors = validate_plan_data(\n        root,\n        require_initial_status=require_initial_status,\n        require_all_done=require_all_done,\n    )\n    if errors:\n        return errors\n    scope_errors = implementation_scope_task_errors(root.get(\"implementationScope\"), [\n        task\n        for batch in batch_data.values()\n        for task in tasks(batch)\n        if isinstance(task, dict)\n    ])\n    if scope_errors:\n        return scope_errors\n    errors.extend(_bundle_consistency_errors(\n        root,\n        batch_data,\n        require_initial_status=require_initial_status,\n        require_all_done=require_all_done,\n    ))\n    return sorted(set(errors))\n\n\ndef load_plan_bundle(\n    target_feature_dir: Path,\n    *,\n    require_initial_status: bool = False,\n    require_all_done: bool = False,\n) -> PlanBundle:\n    root = load_plan(plan_json_path(target_feature_dir))\n    root_errors = validate_plan_data(\n        root,\n        require_initial_status=require_initial_status,\n        require_all_done=require_all_done,\n    )\n    if root_errors:\n        raise PlanJsonError(\";\".join(root_errors))\n\n    entries = [entry for entry in root.get(\"batches\", []) if isinstance(entry, dict)]\n    batch_data: dict[str, dict[str, Any]] = {}\n    all_tasks: list[dict[str, Any]] = []\n    task_batches: dict[str, str] = {}\n    load_errors: list[str] = []\n    for entry in entries:\n        batch_id = str(entry.get(\"id\", \"\"))\n        path = batch_plan_path(target_feature_dir, batch_id)\n        try:\n            data = load_plan(path)\n        except PlanJsonError as exc:\n            load_errors.append(str(exc))\n            continue\n        batch_data[batch_id] = data\n        for item in tasks(data):\n            task_id = item.get(\"id\")\n            if not isinstance(task_id, str):\n                continue\n            if task_id in task_batches:\n                load_errors.append(f\"duplicate_task_id:{task_id}\")\n            else:\n                task_batches[task_id] = batch_id\n                all_tasks.append(item)\n    if load_errors:\n        raise PlanJsonError(\";\".join(load_errors))\n\n    errors = validate_plan_bundle_data(\n        root,\n        batch_data,\n        require_initial_status=require_initial_status,\n        require_all_done=require_all_done,\n    )\n    if errors:\n        raise PlanJsonError(\";\".join(errors))\n    return PlanBundle(root=root, batches=batch_data, tasks=all_tasks, task_batches=task_batches)\n\n\ndef load_and_validate_plan(path: Path, **kwargs: Any) -> tuple[dict[str, Any] | None, list[str]]:\n    try:\n        data = load_plan(path)\n    except PlanJsonError as exc:\n        return None, [str(exc)]\n    errors = validate_plan_data(data, **kwargs)\n    if errors:\n        return data, errors\n    try:\n        bundle = load_plan_bundle(path.parent, **kwargs)\n    except PlanJsonError as exc:\n        return data, str(exc).split(\";\")\n    view = dict(data)\n    view[\"_bundleTasks\"] = bundle.tasks\n    view[\"_bundleTaskBatches\"] = bundle.task_batches\n    view[\"_bundleBatches\"] = bundle.batches\n    view[\"tasks\"] = bundle.tasks\n    return view, []\n",
  "hooks/plan_scope.py": "\"\"\"Read-only rules extracted from hooks/plan_scope.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nimport json\nimport re\nfrom pathlib import Path\nfrom typing import Any, NamedTuple\nfrom hooks.implementation_scope import scope_path\nfrom hooks.spec_contract import SPEC_SCENARIO_DEF_RE\nfrom hooks.design_contract_lock import load_confirmed_design_contract\nfrom hooks.source_context import load_source_context, source_index\n\nSCOPE_KINDS = {\n    \"scenario\": (\"includedScenarioRefs\", \"deferredScenarioRefs\", \"Scenario 引用\"),\n    \"design\": (\"includedDesignIds\", \"deferredDesignIds\", \"Design ID\"),\n    \"source\": (\"includedSourceRefs\", \"deferredSourceRefs\", \"来源要求 ID\"),\n}\n\n\nclass ScopeSelection(NamedTuple):\n    \"\"\"What the current round must cover, what it defers, what it never named.\"\"\"\n\n    included: set[str]\n    deferred: set[str]\n    unpartitioned: set[str]\n\n\ndef _scope_error(reason: str, detail: str, field: str, suggestion: str) -> dict[str, Any]:\n    return {\n        \"reason\": reason,\n        \"detail\": detail,\n        \"field\": field,\n        \"repairTarget\": \"implementation_scope\",\n        \"repairSuggestion\": suggestion,\n    }\n\n\ndef _ref_set(value: Any, field: str) -> tuple[set[str], list[dict[str, Any]]]:\n    if value is None:\n        return set(), []\n    if not isinstance(value, list) or any(not isinstance(item, str) for item in value):\n        return set(), [_scope_error(\n            \"implementation_scope_partition_must_be_string_array\",\n            f\"field={field}\",\n            field,\n            f\"把 IMPLEMENTATION_SCOPE.json 的 {field} 写成字符串数组，每项一个 ID/引用\",\n        )]\n    return {item.strip() for item in value if item.strip()}, []\n\n\nclass PlanScope:\n    \"\"\"The included/deferred partition a Feature declared, if it declared one.\"\"\"\n\n    def __init__(self, partitions: dict[str, tuple[set[str], set[str]]]):\n        self._partitions = partitions\n\n    def declares(self, kind: str) -> bool:\n        return kind in self._partitions\n\n    @property\n    def declared_kinds(self) -> list[str]:\n        return sorted(self._partitions)\n\n    def select(self, kind: str, universe: set[str]) -> tuple[ScopeSelection, list[dict[str, Any]]]:\n        \"\"\"Split ``universe`` into what this round covers, defers and never named.\"\"\"\n\n        universe = set(universe)\n        if kind not in self._partitions:\n            return ScopeSelection(universe, set(), set()), []\n        included, deferred = self._partitions[kind]\n        included_field, deferred_field, label = SCOPE_KINDS[kind]\n        errors: list[dict[str, Any]] = []\n        unknown = sorted((included | deferred) - universe)\n        if unknown:\n            errors.append(_scope_error(\n                \"implementation_scope_unknown_ref\",\n                f\"kind={kind};ids={','.join(unknown)}\",\n                included_field,\n                (\n                    f\"IMPLEMENTATION_SCOPE.json 声明了不存在的 {label}：{', '.join(unknown)}。\"\n                    f\"从 {included_field} / {deferred_field} 中删除这些条目，或到上游产物补回对应定义\"\n                ),\n            ))\n        return (\n            ScopeSelection(\n                included & universe,\n                deferred & universe,\n                universe - included - deferred,\n            ),\n            errors,\n        )\n\n\ndef load_plan_scope(feature_dir: Path) -> tuple[PlanScope, list[dict[str, Any]]]:\n    \"\"\"Read the optional partition. Shape problems block; a missing file does not.\"\"\"\n\n    path = scope_path(feature_dir)\n    if not path.is_file():\n        return PlanScope({}), []\n    try:\n        payload = json.loads(path.read_text(encoding=\"utf-8\"))\n    except (OSError, json.JSONDecodeError):\n        # load_scope() already reports unreadable scope files; do not double-report.\n        return PlanScope({}), []\n    if not isinstance(payload, dict):\n        return PlanScope({}), []\n    return partition_from_payload(payload)\n\n\ndef partition_from_payload(payload: dict[str, Any]) -> tuple[PlanScope, list[dict[str, Any]]]:\n    partitions: dict[str, tuple[set[str], set[str]]] = {}\n    errors: list[dict[str, Any]] = []\n    for kind in sorted(SCOPE_KINDS):\n        included_field, deferred_field, label = SCOPE_KINDS[kind]\n        raw_included = payload.get(included_field)\n        raw_deferred = payload.get(deferred_field)\n        if raw_included is None and raw_deferred is None:\n            continue\n        included, included_errors = _ref_set(raw_included, included_field)\n        deferred, deferred_errors = _ref_set(raw_deferred, deferred_field)\n        errors.extend(included_errors)\n        errors.extend(deferred_errors)\n        if included_errors or deferred_errors:\n            continue\n        overlap = sorted(included & deferred)\n        if overlap:\n            errors.append(_scope_error(\n                \"implementation_scope_partition_overlap\",\n                f\"kind={kind};ids={','.join(overlap)}\",\n                included_field,\n                (\n                    f\"这些 {label} 同时出现在 {included_field} 和 {deferred_field}：\"\n                    f\"{', '.join(overlap)}。每条只能归属一侧，从其中一个数组里删除\"\n                ),\n            ))\n            continue\n        partitions[kind] = (included, deferred)\n    return PlanScope(partitions), errors\n\n\ndef scope_report(selections: dict[str, ScopeSelection]) -> dict[str, Any]:\n    \"\"\"Report what the round defers, so deferred work stays visible without tasks.\"\"\"\n\n    report: dict[str, Any] = {}\n    for kind, selection in sorted(selections.items()):\n        if not selection.deferred and not selection.unpartitioned:\n            continue\n        report[kind] = {\n            \"includedCount\": len(selection.included),\n            \"deferred\": sorted(selection.deferred),\n            \"unpartitioned\": sorted(selection.unpartitioned),\n        }\n    return report\n\n\ndef resolve_plan_scope(feature_dir: Path) -> tuple[dict[str, ScopeSelection], list[dict[str, Any]]]:\n    \"\"\"Use the same coverage universe in publishing and stage validation.\"\"\"\n    scope, errors = load_plan_scope(feature_dir)\n    scenarios: set[str] = set()\n    for spec in sorted((feature_dir / \"specs\").glob(\"**/*.md\")):\n        scenarios.update(\n            f\"{spec.relative_to(feature_dir).as_posix()}#{anchor}\"\n            for anchor in SPEC_SCENARIO_DEF_RE.findall(spec.read_text(encoding=\"utf-8\"))\n        )\n    # Plan must use the Design snapshot already accepted by dev.design.  Reading\n    # design.md here would let an unvalidated edit silently narrow Plan\n    # coverage after the lock was produced.\n    design_contract, design_errors = load_confirmed_design_contract(feature_dir, feature_dir.name)\n    errors.extend(design_errors)\n    design_ids = {\n        value\n        for kind in (\"API\", \"DATA\", \"D\")\n        for value in design_contract.get(\"ids\", {}).get(kind, set())\n        if isinstance(value, str)\n    }\n    context, source_errors = load_source_context(feature_dir)\n    errors.extend({\"reason\": \"invalid_source_context\", \"detail\": error} for error in source_errors)\n    source_ids = set(source_index(context))\n    selections: dict[str, ScopeSelection] = {}\n    for kind, universe in (\n        (\"scenario\", scenarios),\n        (\"design\", design_ids),\n        (\"source\", source_ids),\n    ):\n        selections[kind], issues = scope.select(kind, universe)\n        errors.extend(issues)\n    return selections, errors\n",
  "hooks/plan_write_ownership.py": "\"\"\"Read-only rules extracted from hooks/plan_write_ownership.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nfrom collections import defaultdict\nfrom typing import Any, Iterable, Mapping\n\nTEST_ASSET_ROOT_CONFIGS = frozenset({\n    \"pytest.ini\",\n    \"tox.ini\",\n    \".coveragerc\",\n    \"jest.config.js\",\n    \"jest.config.cjs\",\n    \"jest.config.mjs\",\n    \"jest.config.ts\",\n    \"vitest.config.js\",\n    \"vitest.config.mjs\",\n    \"vitest.config.ts\",\n    \"karma.conf.js\",\n    \"playwright.config.js\",\n    \"playwright.config.ts\",\n    \"cypress.config.js\",\n    \"cypress.config.ts\",\n})\n\n\ndef normalize_owned_path(value: Any, workspace_ref: Any) -> str | None:\n    \"\"\"Normalize the writer's ``Repo:path`` and ``Repo/path`` spellings.\n\n    Plan artifacts historically used both forms.  The scheduler only needs a\n    repository-relative path, so normalize both before deciding ownership.\n    \"\"\"\n\n    if not isinstance(value, str) or not value.strip():\n        return None\n    raw = value.replace(\"\\\\\", \"/\").strip().strip(\"/\")\n    if not raw:\n        return None\n    repository = workspace_ref.strip() if isinstance(workspace_ref, str) else \"\"\n    if repository:\n        for prefix in (f\"{repository}:\", f\"{repository}/\"):\n            if raw.startswith(prefix):\n                raw = raw[len(prefix):].strip(\"/\")\n                break\n    return raw or None\n\n\ndef is_test_asset_path(path: str) -> bool:\n    \"\"\"Return whether a repository-relative path belongs to UTest ownership.\"\"\"\n\n    parts = tuple(part for part in path.replace(\"\\\\\", \"/\").split(\"/\") if part)\n    basename = parts[-1] if parts else \"\"\n    return (\n        (parts and parts[0] in {\"test\", \"tests\", \"__tests__\", \"e2e\", \"playwright\", \"cypress\"})\n        or any(parts[index:index + 2] == (\"src\", \"test\") for index in range(len(parts) - 1))\n        or basename in TEST_ASSET_ROOT_CONFIGS\n        or basename.startswith(\"test_\")\n        or \".test.\" in basename\n        or \".spec.\" in basename\n    )\n\n\ndef task_write_paths(task: dict[str, Any]) -> set[str]:\n    \"\"\"Return Code-stage physical write paths for one Task.\n\n    Test assets are generated only after business-code Review by the UTest\n    stage. They cannot serialize Code Batches or be used as a Review\n    completeness requirement.\n    \"\"\"\n\n    workspace_ref = task.get(\"workspaceRef\")\n    raw_paths: list[Any] = []\n    scope = task.get(\"scope\")\n    if isinstance(scope, dict) and isinstance(scope.get(\"paths\"), list):\n        raw_paths.extend(scope[\"paths\"])\n    if isinstance(task.get(\"expectedFiles\"), list):\n        raw_paths.extend(task[\"expectedFiles\"])\n    paths: set[str] = set()\n    for value in raw_paths:\n        path = normalize_owned_path(value, workspace_ref)\n        if path is not None and not is_test_asset_path(path):\n            paths.add(path)\n    return paths\n\n\ndef task_write_targets(task: dict[str, Any]) -> dict[str, set[str] | None]:\n    \"\"\"Return physical paths and optional member anchors for one task.\n\n    ``None`` denotes a whole-file claim for an observed ownership record.\n    \"\"\"\n\n    workspace_ref = task.get(\"workspaceRef\")\n    declared: dict[str, set[str] | None] = {}\n    raw_targets = task.get(\"writeTargets\")\n    if isinstance(raw_targets, list):\n        for item in raw_targets:\n            if not isinstance(item, dict):\n                continue\n            path = normalize_owned_path(item.get(\"path\"), workspace_ref)\n            if path is None or is_test_asset_path(path):\n                continue\n            raw_symbols = item.get(\"symbols\")\n            if not isinstance(raw_symbols, list) or any(\n                not isinstance(symbol, str) or not symbol.strip() for symbol in raw_symbols\n            ):\n                declared[path] = None\n                continue\n            symbols = {symbol.strip() for symbol in raw_symbols}\n            if not symbols:\n                declared[path] = None\n                continue\n            prior = declared.get(path)\n            declared[path] = None if prior is None and path in declared else (prior or set()) | symbols\n\n    # scope.paths/expectedFiles remain physical source of truth. A target only\n    # refines a matching path; no declared anchor can hide another file write.\n    for path in task_write_paths(task):\n        declared.setdefault(path, None)\n    return declared\n\n\ndef write_ownership_violations(\n    tasks: Iterable[dict[str, Any]],\n    *,\n    ownership_scope_by_task: Mapping[str, str] | None = None,\n) -> list[dict[str, Any]]:\n    \"\"\"Return structured errors for files claimed by more than one Batch.\n\n    Tasks in one Batch execute as one ordered delivery, so they may share an\n    implementation file without reducing inter-Batch parallelism.  The\n    ownership boundary is therefore a projected Batch, not an individual\n    Task.  When a scope map is omitted each Task is treated as its own Batch;\n    this is useful only for callers that do not have a Batch projection yet.\n    \"\"\"\n\n    owners: dict[tuple[str, str], dict[str, dict[str, set[str] | None]]] = defaultdict(\n        lambda: defaultdict(dict)\n    )\n    for task in tasks:\n        if not isinstance(task, dict) or task.get(\"executionMode\") == \"external_dependency\":\n            continue\n        task_id = task.get(\"id\")\n        workspace_ref = task.get(\"workspaceRef\")\n        if not isinstance(task_id, str) or not task_id.strip():\n            continue\n        if not isinstance(workspace_ref, str) or not workspace_ref.strip():\n            continue\n        scope = (\n            ownership_scope_by_task.get(task_id, task_id)\n            if ownership_scope_by_task is not None\n            else task_id\n        )\n        for path, symbols in task_write_targets(task).items():\n            scoped = owners[(workspace_ref.strip(), path)][scope]\n            prior = scoped.get(task_id)\n            if prior is None and task_id in scoped:\n                continue\n            if symbols is None:\n                scoped[task_id] = None\n            else:\n                scoped[task_id] = (prior or set()) | symbols\n\n    violations: list[dict[str, Any]] = []\n    for (workspace_ref, path), scoped_claims in sorted(owners.items()):\n        if len(scoped_claims) < 2:\n            continue\n        whole_file_scopes = {\n            scope\n            for scope, claims in scoped_claims.items()\n            if any(symbols is None for symbols in claims.values())\n        }\n        symbol_scopes: dict[str, set[str]] = defaultdict(set)\n        for scope, claims in scoped_claims.items():\n            for symbols in claims.values():\n                if symbols is not None:\n                    for symbol in symbols:\n                        symbol_scopes[symbol].add(scope)\n        overlapping_symbols = sorted(\n            symbol for symbol, scopes in symbol_scopes.items() if len(scopes) > 1\n        )\n        if not whole_file_scopes and not overlapping_symbols:\n            continue\n        violating_scopes = set(whole_file_scopes)\n        if whole_file_scopes:\n            violating_scopes.update(scoped_claims)\n        for symbol in overlapping_symbols:\n            violating_scopes.update(symbol_scopes[symbol])\n        ordered_task_ids = sorted({\n            task_id\n            for scope, claims in scoped_claims.items()\n            if scope in violating_scopes\n            for task_id in claims\n        })\n        ownership_kind = \"whole_file\" if whole_file_scopes else \"member_anchor\"\n        violations.append({\n            \"reason\": \"shared_write_path_requires_single_owner\",\n            \"workspaceRef\": workspace_ref,\n            \"path\": path,\n            \"detail\": (\n                f\"workspace={workspace_ref};path={path};\"\n                f\"taskIds={','.join(ordered_task_ids)};ownership={ownership_kind}\"\n            ),\n            \"taskIds\": ordered_task_ids,\n            \"field\": \"writeTargets\" if ownership_kind == \"member_anchor\" else \"touches\",\n            \"repairTarget\": \"task_group\",\n            \"repairSuggestion\": (\n                f\"{workspace_ref}:{path} 被多个 Task 以 {ownership_kind} 方式声明。\"\n                \"如确为同一 Controller/Service 的不同方法，可为每个 Task 在 writeTargets 中声明\"\n                \"互不重叠的稳定 symbols；否则保留一个前置 owner Task，消费者通过 deps 消费其产出，\"\n                \"并从 touches、scope.paths、expectedFiles 和 implementationPoints 中移除该文件。\"\n            ),\n        })\n    return violations\n\n\ndef write_ownership_error_codes(\n    tasks: Iterable[dict[str, Any]],\n    *,\n    ownership_scope_by_task: Mapping[str, str] | None = None,\n) -> list[str]:\n    \"\"\"Stable compact form for the low-level plan.json validator.\"\"\"\n\n    return [\n        \"{reason}:workspace={workspace}:path={path}:taskIds={task_ids}\".format(\n            reason=violation[\"reason\"],\n            workspace=violation[\"workspaceRef\"],\n            path=violation[\"path\"],\n            task_ids=\",\".join(violation[\"taskIds\"]),\n        )\n        for violation in write_ownership_violations(\n            tasks,\n            ownership_scope_by_task=ownership_scope_by_task,\n        )\n    ]\n",
  "hooks/secret_rules.py": "\"\"\"Read-only rules extracted from hooks/check-secrets-new.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nimport re\n\ndef is_encrypted_value(value: str) -> bool:\n    encrypted_prefixes = ['BEE', 'ENC', '{ciph', 'encrypt:', 'M_ENC', 'LSFI_ENV_COMMON', 'http://']\n    for prefix in encrypted_prefixes:\n        if value.startswith(prefix):\n            return True\n    return False\n\n\ndef is_variable_reference(value: str) -> bool:\n    patterns = [r'^\\$\\(.*?\\)$', r'^\\$\\{.*?\\}$', r'^<.*?>$', r'^@.*?@$']\n    for pattern in patterns:\n        if re.match(pattern, value):\n            return True\n    return False\n\n\ndef is_masked_value(value: str) -> bool:\n    if len(value) >= 1 and re.sub(r'[*]', '', value) == '':\n        return True\n    return False\n\n\ndef should_skip_key(key: str) -> bool:\n    k = key.lower().strip()\n    public_access_keys = ['publickey', 'public-key', 'pubkey', 'public_key', 'appkey', 'access-key', 'accesskey']\n    if k in public_access_keys or re.match(r'^public\\s+key$', k) or re.match(r'^access\\s+key$', k):\n        return True\n    if k in ['topickey', 'relatedkey', 'related-key', 'binding-routing-key'] or 'relatedkey' in k:\n        return True\n    if 'poseidon' in k:\n        return True\n    if k in ['ignoretoken', 'bee.microservice.token']:\n        return True\n    return False\n\n\ndef check_line(line: str):\n    line = line.strip()\n    if not line or line.startswith('#'):\n        return None\n    match = re.match(r'^\\s*([^=:]+)\\s*[=:]\\s*(.*)$', line)\n    if not match:\n        return None\n    full_key = match.group(1).strip()\n    value = match.group(2).strip()\n    k = full_key.lower().strip()\n    v = value.strip()\n    if should_skip_key(k):\n        return None\n    is_target = False\n    rule = \"\"\n    if 'zoo_server_passwords' in k or 'zoo.server.passwords' in k:\n        is_target = True\n        rule = \"Zookeeper\"\n    elif 'sasl.jaas.config' in k:\n        is_target = True\n        rule = \"Kafka\"\n    elif 'redis' in k and any(k.endswith(suffix) for suffix in ['password', 'auth', 'pass', 'secret']):\n        is_target = True\n        rule = \"Redis\"\n    elif any(k.endswith(suffix) for suffix in ['password', 'secret', 'pwd', 'key', 'token']):\n        is_target = True\n        rule = \"GENERAL\"\n    if not is_target:\n        return None\n    if is_encrypted_value(v):\n        return None\n    if is_masked_value(v):\n        return None\n    if is_variable_reference(v):\n        return None\n    return (True, rule, full_key, value)\n",
  "hooks/source_context.py": "\"\"\"Read-only rules extracted from hooks/source_context.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nimport json\nimport re\nfrom pathlib import Path\nfrom typing import Any, Dict, List, Optional, Set, Tuple\n\nSOURCE_CONTEXT_FILE = \"source-context.json\"\n\n\nSOURCE_ID_RE = re.compile(r\"^SRC-\\d{3}$\")\n\n\nVALID_AVAILABILITY = {\"live\", \"snapshot_only\", \"never_provided\"}\n\n\nVALID_READ_STATUS = {\"complete\", \"partial\", \"unreadable\"}\n\n\nVALID_FRESHNESS = {\"current\", \"stale\", \"unknown\"}\n\n\ndef source_context_path(feature_dir: Path) -> Path:\n    return feature_dir / SOURCE_CONTEXT_FILE\n\n\ndef load_source_context(feature_dir: Path) -> Tuple[Optional[Dict[str, Any]], List[str]]:\n    path = source_context_path(feature_dir)\n    if not path.is_file() or path.stat().st_size <= 0:\n        return None, []\n    try:\n        data = json.loads(path.read_text(encoding=\"utf-8\"))\n    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:\n        return None, [\"source-context.json 无法读取: %s\" % exc]\n    if not isinstance(data, dict):\n        return None, [\"source-context.json 顶层必须是对象\"]\n    return data, []\n\n\ndef source_index(data: Optional[Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:\n    \"\"\"按 SRC-NNN 索引每份资料，下游只透传这些字段。\"\"\"\n    result = {}  # type: Dict[str, Dict[str, Any]]\n    if not isinstance(data, dict):\n        return result\n    sources = data.get(\"sources\")\n    if not isinstance(sources, list):\n        return result\n    for source in sources:\n        if not isinstance(source, dict):\n            continue\n        source_id = source.get(\"id\")\n        if not isinstance(source_id, str):\n            continue\n        result[source_id] = {\n            \"id\": source_id,\n            \"name\": source.get(\"name\"),\n            \"sourcePath\": source.get(\"path\"),\n            \"availability\": source.get(\"availability\"),\n            \"readStatus\": source.get(\"readStatus\"),\n            \"freshness\": source.get(\"freshness\", \"unknown\"),\n        }\n    return result\n\n\ndef _safe_snapshot_path(feature_dir: Path, source_id: str, raw_path: Any) -> Tuple[Optional[Path], Optional[str]]:\n    if not isinstance(raw_path, str) or not raw_path.strip():\n        return None, \"%s 缺少快照 path\" % source_id\n    path = Path(raw_path)\n    if path.is_absolute():\n        return None, \"%s.path 必须是 Feature 目录相对路径\" % source_id\n    candidate = (feature_dir / path).resolve(strict=False)\n    base = feature_dir.resolve(strict=False)\n    try:\n        relative = candidate.relative_to(base)\n    except ValueError:\n        return None, \"%s.path 越出 Feature 目录\" % source_id\n    parts = relative.parts\n    if len(parts) < 3 or parts[0] != \"sources\" or parts[1] != source_id:\n        return None, \"%s.path 必须位于 sources/%s/\" % (source_id, source_id)\n    if not candidate.is_file() or candidate.stat().st_size <= 0:\n        return None, \"%s 快照不存在或为空: %s\" % (source_id, raw_path)\n    return candidate, None\n\n\ndef validate_source_context(\n    feature_dir: Path,\n    expected_source_ids: Optional[Set[str]] = None,\n) -> Tuple[List[str], List[str]]:\n    \"\"\"校验 source-context.json，返回 (errors, warnings)。\n\n    errors 只保留会让下游引用悬空的项：ID 可解析、\n    PRD 与 json 的来源集合一致。其余字段下游只做透传渲染，一律降级为\n    warnings，避免 discuss 阶段的严格度阻断 Plan / Code。\n    \"\"\"\n    data, load_errors = load_source_context(feature_dir)\n    errors = list(load_errors)  # type: List[str]\n    warnings = []  # type: List[str]\n    if data is None:\n        if expected_source_ids:\n            errors.append(\n                \"PRD 登记了外部资料，必须生成 source-context.json；\"\n                \"修复：运行 source_context.py sync --feature-dir <Feature 目录>\"\n            )\n        return errors, warnings\n\n    if data.get(\"version\") != 1:\n        errors.append(\"source-context.json.version 必须为 1；修复：把 version 字段设为整数 1\")\n    sources = data.get(\"sources\")\n    if not isinstance(sources, list) or not sources:\n        errors.append(\n            \"source-context.json.sources 必须是非空数组；\"\n            \"修复：运行 source_context.py sync --feature-dir <Feature 目录> 依据 PRD 来源表重建\"\n        )\n        return errors, warnings\n\n    seen_sources = set()  # type: Set[str]\n\n    for source_index_position, source in enumerate(sources):\n        context = \"sources[%d]\" % source_index_position\n        if not isinstance(source, dict):\n            errors.append(\"%s 必须是对象\" % context)\n            continue\n        source_id = source.get(\"id\")\n        if not isinstance(source_id, str) or SOURCE_ID_RE.fullmatch(source_id) is None:\n            errors.append(\"%s.id 格式非法；修复：改为 SRC-001 形式的三位编号\" % context)\n            continue\n        if source_id in seen_sources:\n            errors.append(\n                \"source-context.json 来源 ID 重复: %s；修复：保留一条，其余改用未使用的 SRC-NNN\"\n                % source_id\n            )\n        seen_sources.add(source_id)\n\n        name = source.get(\"name\")\n        if not isinstance(name, str) or not name.strip():\n            warnings.append(\"%s.name 缺失\" % source_id)\n        availability = source.get(\"availability\")\n        if availability not in VALID_AVAILABILITY:\n            warnings.append(\n                \"%s.availability 非法；可选值: %s\"\n                % (source_id, \"/\".join(sorted(VALID_AVAILABILITY)))\n            )\n        read_status = source.get(\"readStatus\")\n        if read_status not in VALID_READ_STATUS:\n            warnings.append(\n                \"%s.readStatus 非法；可选值: %s\"\n                % (source_id, \"/\".join(sorted(VALID_READ_STATUS)))\n            )\n        elif availability != \"never_provided\" and read_status != \"complete\":\n            warnings.append(\"%s 尚未完整读取（readStatus=%s）\" % (source_id, read_status))\n        if source.get(\"freshness\", \"unknown\") not in VALID_FRESHNESS:\n            warnings.append(\n                \"%s.freshness 非法；可选值: %s\"\n                % (source_id, \"/\".join(sorted(VALID_FRESHNESS)))\n            )\n        if availability == \"never_provided\":\n            warnings.append(\n                \"%s 标记为从未提供；出口只有三个：当场提供资料、移除该依赖、或暂停等待材料\"\n                % source_id\n            )\n            continue\n\n        _, path_error = _safe_snapshot_path(feature_dir, source_id, source.get(\"path\"))\n        if path_error:\n            warnings.append(\n                \"%s；修复：运行 source_context.py sync 自动写入快照路径\" % path_error\n            )\n\n    if expected_source_ids is not None:\n        missing = sorted(expected_source_ids - seen_sources)\n        unknown = sorted(seen_sources - expected_source_ids)\n        if missing:\n            errors.append(\n                \"source-context.json 缺少 PRD 来源: %s；\"\n                \"修复：运行 source_context.py sync 依据 PRD 来源表补齐\" % \", \".join(missing)\n            )\n        if unknown:\n            errors.append(\n                \"source-context.json 存在 PRD 未登记来源: %s；\"\n                \"修复：在 PRD 的「外部资料与实现约束」补登记，或从 json 中移除\"\n                % \", \".join(unknown)\n            )\n    return errors, warnings\n",
  "hooks/source_references.py": "\"\"\"Read-only rules extracted from hooks/source_references.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nimport re\nfrom dataclasses import dataclass\n\nSOURCE_SECTION_TITLE = \"外部资料与实现约束\"\n\n\nSOURCE_ID_RE = re.compile(r\"\\bSRC-\\d{3}\\b\")\n\n\n_HEADING_RE = re.compile(r\"^ {0,3}(#{1,6})\\s+(.*?)\\s*$\")\n\n\n_SEPARATOR_CELL_RE = re.compile(r\"^:?-{3,}:?$\")\n\n\n_EMPTY_VALUES = {\"\", \"-\", \"—\", \"无\", \"none\", \"n/a\", \"na\", \"不适用\"}\n\n\n@dataclass(frozen=True)\nclass SourceReference:\n    source_id: str\n    kind: str\n    name: str\n    locator: str\n    scope: str\n    status: str\n\n    @property\n    def is_external_interface(self) -> bool:\n        normalized = re.sub(r\"[\\s_-]+\", \"\", self.kind).casefold()\n        return (\n            \"外部接口\" in normalized\n            or \"第三方接口\" in normalized\n            or \"externalapi\" in normalized\n            or ((\"外部\" in normalized or \"第三方\" in normalized) and \"api\" in normalized)\n        )\n\n\ndef _normalize_header(value: str) -> str:\n    return re.sub(r\"[\\s`*_]+\", \"\", value).casefold()\n\n\ndef _table_cells(line: str) -> list[str]:\n    stripped = line.strip()\n    if not stripped.startswith(\"|\") or not stripped.endswith(\"|\"):\n        return []\n    return [cell.strip() for cell in stripped.strip(\"|\").split(\"|\")]\n\n\ndef _section_body(text: str) -> str | None:\n    lines = text.splitlines()\n    start = None\n    level = None\n    for index, line in enumerate(lines):\n        match = _HEADING_RE.match(line)\n        if match and SOURCE_SECTION_TITLE in match.group(2):\n            start = index + 1\n            level = len(match.group(1))\n            break\n    if start is None or level is None:\n        return None\n\n    end = len(lines)\n    for index in range(start, len(lines)):\n        match = _HEADING_RE.match(lines[index])\n        if match and len(match.group(1)) <= level:\n            end = index\n            break\n    return \"\\n\".join(lines[start:end]).strip()\n\n\ndef has_source_section(text: str) -> bool:\n    return _section_body(text) is not None\n\n\ndef extract_source_references(text: str) -> list[SourceReference]:\n    \"\"\"Return valid ``SRC-NNN`` rows from the PRD source table.\n\n    Unknown columns are ignored.  The parser intentionally accepts a few\n    header aliases so wording can evolve without weakening stable-ID checks.\n    Invalid rows are reported by :func:`validate_source_reference_section`.\n    \"\"\"\n\n    body = _section_body(text)\n    if body is None:\n        return []\n\n    lines = body.splitlines()\n    header_index = None\n    headers: list[str] = []\n    for index, line in enumerate(lines):\n        cells = _table_cells(line)\n        normalized = {_normalize_header(cell) for cell in cells}\n        if cells and {\"id\", \"类型\"}.issubset(normalized):\n            header_index = index\n            headers = [_normalize_header(cell) for cell in cells]\n            break\n    if header_index is None:\n        return []\n\n    aliases = {\n        \"source_id\": {\"id\", \"资料id\", \"sourceid\"},\n        \"kind\": {\"类型\", \"资料类型\", \"type\"},\n        \"name\": {\"名称\", \"资料名称\", \"name\"},\n        \"locator\": {\"地址/路径\", \"地址路径\", \"地址\", \"路径\", \"url/path\", \"locator\"},\n        \"scope\": {\"约束范围\", \"关联需求\", \"适用范围\", \"scope\"},\n        \"status\": {\"状态\", \"status\"},\n    }\n    positions: dict[str, int] = {}\n    for field, names in aliases.items():\n        for index, header in enumerate(headers):\n            if header in names:\n                positions[field] = index\n                break\n\n    references: list[SourceReference] = []\n    for line in lines[header_index + 1 :]:\n        cells = _table_cells(line)\n        if not cells:\n            continue\n        if all(_SEPARATOR_CELL_RE.match(cell.replace(\" \", \"\")) for cell in cells):\n            continue\n\n        def value(field: str) -> str:\n            index = positions.get(field)\n            return cells[index].strip() if index is not None and index < len(cells) else \"\"\n\n        source_match = SOURCE_ID_RE.fullmatch(value(\"source_id\"))\n        if source_match is None:\n            continue\n        references.append(\n            SourceReference(\n                source_id=source_match.group(0),\n                kind=value(\"kind\"),\n                name=value(\"name\"),\n                locator=value(\"locator\"),\n                scope=value(\"scope\"),\n                status=value(\"status\"),\n            )\n        )\n    return references\n\n\ndef split_source_reference_section(text: str) -> tuple[list[str], list[str]]:\n    \"\"\"Return ``(errors, warnings)`` for the PRD-owned source index.\n\n    Only the checks that keep downstream ``SRC-NNN`` references resolvable\n    block.  Field completeness on non-interface rows is advisory: the skill\n    text only demands full fields for 外部接口 / 第三方接口 rows.\n    \"\"\"\n\n    body = _section_body(text)\n    if body is None:\n        return (\n            [\n                f\"PRD.md 缺少必要段落: {SOURCE_SECTION_TITLE}；\"\n                \"修复：新增该章节，没有外部资料时正文写「无」\"\n            ],\n            [],\n        )\n\n    lowered = body.strip().casefold()\n    if lowered in _EMPTY_VALUES:\n        return [], []\n\n    references = extract_source_references(text)\n    errors: list[str] = []\n    warnings: list[str] = []\n    if not references:\n        return (\n            [\n                f\"{SOURCE_SECTION_TITLE} 必须写“无”，或使用包含 ID、类型、名称、地址/路径、\"\n                \"约束范围、状态的表格；修复：补齐表头后每行以 SRC-NNN 开头\"\n            ],\n            [],\n        )\n\n    ids = [reference.source_id for reference in references]\n    duplicates = sorted({source_id for source_id in ids if ids.count(source_id) > 1})\n    if duplicates:\n        errors.append(\n            f\"外部资料 ID 重复: {', '.join(duplicates)}；\"\n            \"修复：SRC-NNN 是跨阶段稳定引用，重复项改用未使用的编号\"\n        )\n\n    for reference in references:\n        missing = []\n        if reference.kind.casefold() in _EMPTY_VALUES:\n            missing.append(\"类型\")\n        if reference.name.casefold() in _EMPTY_VALUES:\n            missing.append(\"名称\")\n        if reference.locator.casefold() in _EMPTY_VALUES:\n            missing.append(\"地址/路径\")\n        if reference.scope.casefold() in _EMPTY_VALUES:\n            missing.append(\"约束范围\")\n        if reference.status.casefold() in _EMPTY_VALUES:\n            missing.append(\"状态\")\n\n        if reference.is_external_interface:\n            if missing:\n                errors.append(\n                    f\"{reference.source_id} 是外部接口，缺少字段: {', '.join(missing)}；\"\n                    \"修复：补齐后续阶段据以调用的地址/路径、约束范围与状态\"\n                )\n        elif missing:\n            warnings.append(f\"{reference.source_id} 缺少字段: {', '.join(missing)}\")\n    return errors, warnings\n",
  "hooks/spec_contract.py": "\"\"\"Read-only rules extracted from hooks/spec_contract.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nimport re\nfrom typing import Match, Optional, Pattern\n\ndef _definition(kind: str, prefix: str, level: int) -> Pattern[str]:\n    return re.compile(\n        rf\"^{'#' * level}\\s+{kind}\\s+\"\n        rf\"(?=\\[?({prefix}-\\d{{3}})\\]?:\\s+.+$)\"\n        rf\"(?:\\[{prefix}-\\d{{3}}\\]|{prefix}-\\d{{3}}):\\s+.+$\",\n        re.MULTILINE,\n    )\n\n\nSPEC_REQUIREMENT_DEF_RE = _definition(\"Requirement\", \"REQ\", 3)\n\n\nSPEC_SCENARIO_DEF_RE = _definition(\"Scenario\", \"SCN\", 4)\n\n\ndef spec_heading(text: str, anchor: str) -> Optional[Match[str]]:\n    pattern = SPEC_REQUIREMENT_DEF_RE if anchor.startswith(\"REQ-\") else SPEC_SCENARIO_DEF_RE\n    return next((match for match in pattern.finditer(text) if match.group(1) == anchor), None)\n",
  "hooks/ui_context.py": "\"\"\"Read-only rules extracted from hooks/ui_context.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nimport json\nimport re\nfrom pathlib import Path\nfrom typing import Any\n\nUI_CONTEXT_VERSION = 1\n\n\nUI_CONTEXT_NAME = \"UI_CONTEXT.json\"\n\n\nDECISION_STATUSES = {\"defaulted\", \"confirmed\", \"locked\"}\n\n\nDECISION_SOURCES = {\"user_confirmed\", \"prd_inferred\", \"default_false\", \"legacy_import\"}\n\n\nVISUAL_SOURCE_TYPES = {\"high_fidelity_html\", \"standard_html\", \"design_link\", \"prototype_link\", \"image\", \"other\"}\n\n\nFRONTEND_ROUTES = {\"none\", \"spec-driven-ui\", \"absolute-html\", \"standard-html\", \"missing-html\"}\n\n\nVISUAL_SOURCE_ROUTES = FRONTEND_ROUTES - {\"none\"}\n\n\nPAGE_ID_RE = re.compile(r\"^PAGE-\\d{3}$\")\n\n\nINTERACTION_ID_RE = re.compile(r\"^UIX-\\d{3}$\")\n\n\nVISUAL_SOURCE_ID_RE = re.compile(r\"^VIS-\\d{3}$\")\n\n\nCAPABILITY_ID_RE = re.compile(r\"^[a-z0-9]+(?:-[a-z0-9]+)*$\")\n\n\nREQ_ID_RE = re.compile(r\"\\bREQ-\\d{3}\\b\")\n\n\nSCN_ID_RE = re.compile(r\"\\bSCN-\\d{3}\\b\")\n\n\nSHA256_RE = re.compile(r\"^[0-9a-f]{64}$\")\n\n\nclass UIContextError(ValueError):\n    \"\"\"Raised when UI_CONTEXT.json cannot be loaded.\"\"\"\n\n\ndef ui_context_path(feature_dir: Path) -> Path:\n    return feature_dir / UI_CONTEXT_NAME\n\n\ndef load_ui_context(feature_dir: Path) -> dict[str, Any] | None:\n    path = ui_context_path(feature_dir)\n    if not path.is_file() or path.stat().st_size <= 0:\n        return None\n    try:\n        data = json.loads(path.read_text(encoding=\"utf-8\"))\n    except json.JSONDecodeError as exc:\n        raise UIContextError(f\"invalid_ui_context_json:{path}:{exc}\") from exc\n    if not isinstance(data, dict):\n        raise UIContextError(f\"invalid_ui_context_root:{path}\")\n    return data\n\n\ndef _string_list(value: Any) -> list[str] | None:\n    if not isinstance(value, list):\n        return None\n    result: list[str] = []\n    for item in value:\n        if not isinstance(item, str):\n            return None\n        stripped = item.strip()\n        if stripped:\n            result.append(stripped)\n    return result\n\n\ndef _object_list(value: Any) -> list[dict[str, Any]] | None:\n    if not isinstance(value, list):\n        return None\n    if not all(isinstance(item, dict) for item in value):\n        return None\n    return value\n\n\ndef _validate_string_field(errors: list[str], item: dict[str, Any], field: str, context: str, *, required: bool = True) -> None:\n    value = item.get(field)\n    if value is None and not required:\n        return\n    if not isinstance(value, str) or not value.strip():\n        errors.append(f\"{context}.{field}_missing\")\n\n\ndef _validate_string_array(\n    errors: list[str],\n    item: dict[str, Any],\n    field: str,\n    context: str,\n    *,\n    required: bool = False,\n    item_re: re.Pattern[str] | None = None,\n) -> list[str]:\n    values = _string_list(item.get(field))\n    if values is None:\n        errors.append(f\"{context}.{field}_must_be_string_array\")\n        return []\n    if required and not values:\n        errors.append(f\"{context}.{field}_missing\")\n    if item_re is not None:\n        for value in values:\n            if not item_re.fullmatch(value):\n                errors.append(f\"{context}.{field}_invalid:{value}\")\n    return values\n\n\ndef validate_ui_context_data(\n    data: Any,\n    *,\n    feature_id: str | None = None,\n    require_confirmed: bool = False,\n    require_locked: bool = False,\n    defined_requirements: set[str] | None = None,\n    defined_scenarios: set[str] | None = None,\n) -> list[str]:\n    errors: list[str] = []\n    if not isinstance(data, dict):\n        return [\"ui_context_root_must_be_object\"]\n\n    if data.get(\"version\") != UI_CONTEXT_VERSION:\n        errors.append(\"ui_context_invalid_version\")\n    raw_feature_id = data.get(\"featureId\")\n    if not isinstance(raw_feature_id, str) or not raw_feature_id.strip():\n        errors.append(\"ui_context_missing_feature_id\")\n    elif feature_id and raw_feature_id != feature_id:\n        errors.append(f\"ui_context_feature_id_mismatch:{raw_feature_id}\")\n\n    ui_required = data.get(\"uiRequired\")\n    if not isinstance(ui_required, bool):\n        errors.append(\"ui_context_uiRequired_must_be_bool\")\n\n    status = data.get(\"decisionStatus\")\n    if not isinstance(status, str) or status not in DECISION_STATUSES:\n        errors.append(\"ui_context_invalid_decision_status\")\n    elif require_confirmed and status not in {\"confirmed\", \"locked\"}:\n        errors.append(\"ui_context_not_confirmed\")\n    elif require_locked and status != \"locked\":\n        errors.append(\"ui_context_not_locked\")\n\n    source = data.get(\"decisionSource\")\n    if source is not None and (not isinstance(source, str) or source not in DECISION_SOURCES):\n        errors.append(\"ui_context_invalid_decision_source\")\n\n    for field in (\"confirmedAtCheckpoint\", \"lockedAtCheckpoint\"):\n        value = data.get(field)\n        if value is not None and (not isinstance(value, str) or not value.strip()):\n            errors.append(f\"ui_context_{field}_invalid\")\n\n    pages = _object_list(data.get(\"pages\"))\n    interactions = _object_list(data.get(\"interactions\"))\n    visual_sources = _object_list(data.get(\"visualSources\"))\n    capabilities = _object_list(data.get(\"capabilities\"))\n    for field, values in (\n        (\"pages\", pages),\n        (\"interactions\", interactions),\n        (\"visualSources\", visual_sources),\n        (\"capabilities\", capabilities),\n    ):\n        if values is None:\n            errors.append(f\"ui_context_{field}_must_be_array\")\n\n    pages = pages or []\n    interactions = interactions or []\n    visual_sources = visual_sources or []\n    capabilities = capabilities or []\n\n    if ui_required is True and not (pages or interactions or capabilities):\n        errors.append(\"ui_context_required_without_ui_scope\")\n    if ui_required is True and (require_locked or status == \"locked\"):\n        active_ui_capabilities = [\n            capability for capability in capabilities if capability.get(\"uiRequired\") is not False\n        ]\n        if not active_ui_capabilities:\n            errors.append(\"ui_context_locked_without_ui_capability\")\n    if ui_required is False:\n        reason = data.get(\"notApplicableReason\")\n        if not isinstance(reason, str) or not reason.strip():\n            errors.append(\"ui_context_not_applicable_reason_missing\")\n        if any(cap.get(\"uiRequired\") is True for cap in capabilities):\n            errors.append(\"ui_context_false_has_ui_capability\")\n\n    page_ids: set[str] = set()\n    for index, page in enumerate(pages):\n        context = f\"pages[{index}]\"\n        page_id = page.get(\"pageId\")\n        if not isinstance(page_id, str) or not PAGE_ID_RE.fullmatch(page_id):\n            errors.append(f\"{context}.pageId_invalid\")\n            continue\n        if page_id in page_ids:\n            errors.append(f\"{context}.pageId_duplicate:{page_id}\")\n        page_ids.add(page_id)\n        _validate_string_field(errors, page, \"name\", context)\n        _validate_string_field(errors, page, \"goal\", context)\n        _validate_string_field(errors, page, \"routeHint\", context, required=False)\n        states = page.get(\"states\")\n        if states is not None and _string_list(states) is None:\n            errors.append(f\"{context}.states_must_be_string_array\")\n\n    interaction_ids: set[str] = set()\n    for index, interaction in enumerate(interactions):\n        context = f\"interactions[{index}]\"\n        interaction_id = interaction.get(\"interactionId\")\n        if not isinstance(interaction_id, str) or not INTERACTION_ID_RE.fullmatch(interaction_id):\n            errors.append(f\"{context}.interactionId_invalid\")\n            continue\n        if interaction_id in interaction_ids:\n            errors.append(f\"{context}.interactionId_duplicate:{interaction_id}\")\n        interaction_ids.add(interaction_id)\n        page_id = interaction.get(\"pageId\")\n        if not isinstance(page_id, str) or page_id not in page_ids:\n            errors.append(f\"{context}.pageId_unknown:{page_id}\")\n        _validate_string_field(errors, interaction, \"summary\", context)\n        if interaction.get(\"stateRefs\") is not None and _string_list(interaction.get(\"stateRefs\")) is None:\n            errors.append(f\"{context}.stateRefs_must_be_string_array\")\n        _validate_spec_refs(errors, interaction, context, defined_requirements, defined_scenarios, required=False)\n\n    visual_source_ids: set[str] = set()\n    for index, visual_source in enumerate(visual_sources):\n        context = f\"visualSources[{index}]\"\n        source_id = visual_source.get(\"sourceId\")\n        if not isinstance(source_id, str) or not VISUAL_SOURCE_ID_RE.fullmatch(source_id):\n            errors.append(f\"{context}.sourceId_invalid\")\n            continue\n        if source_id in visual_source_ids:\n            errors.append(f\"{context}.sourceId_duplicate:{source_id}\")\n        visual_source_ids.add(source_id)\n        source_type = visual_source.get(\"type\")\n        if not isinstance(source_type, str) or source_type not in VISUAL_SOURCE_TYPES:\n            errors.append(f\"{context}.type_invalid\")\n        _validate_string_field(errors, visual_source, \"path\", context)\n        route = visual_source.get(\"route\")\n        if route is not None and (not isinstance(route, str) or route not in VISUAL_SOURCE_ROUTES):\n            errors.append(f\"{context}.route_invalid\")\n        required = visual_source.get(\"required\")\n        if required is not None and not isinstance(required, bool):\n            errors.append(f\"{context}.required_must_be_bool\")\n        for field in (\"contentSha256\", \"bundleSha256\"):\n            digest = visual_source.get(field)\n            if digest is not None and (not isinstance(digest, str) or not SHA256_RE.fullmatch(digest)):\n                errors.append(f\"{context}.{field}_invalid\")\n\n    capability_ids: set[str] = set()\n    referenced_visual_source_ids: set[str] = set()\n    for index, capability in enumerate(capabilities):\n        context = f\"capabilities[{index}]\"\n        capability_id = capability.get(\"capabilityId\")\n        if not isinstance(capability_id, str) or not CAPABILITY_ID_RE.fullmatch(capability_id):\n            errors.append(f\"{context}.capabilityId_invalid\")\n        elif capability_id in capability_ids:\n            errors.append(f\"{context}.capabilityId_duplicate:{capability_id}\")\n        else:\n            capability_ids.add(capability_id)\n        if capability.get(\"uiRequired\") is not None and not isinstance(capability.get(\"uiRequired\"), bool):\n            errors.append(f\"{context}.uiRequired_must_be_bool\")\n        for page_id in _validate_string_array(errors, capability, \"pageRefs\", context, required=False, item_re=PAGE_ID_RE):\n            if page_id not in page_ids:\n                errors.append(f\"{context}.pageRef_unknown:{page_id}\")\n        for interaction_id in _validate_string_array(errors, capability, \"interactionRefs\", context, required=False, item_re=INTERACTION_ID_RE):\n            if interaction_id not in interaction_ids:\n                errors.append(f\"{context}.interactionRef_unknown:{interaction_id}\")\n        visual_source_refs = (\n            _validate_string_array(\n                errors,\n                capability,\n                \"visualSourceRefs\",\n                context,\n                required=False,\n                item_re=VISUAL_SOURCE_ID_RE,\n            )\n            if \"visualSourceRefs\" in capability\n            else []\n        )\n        for source_id in visual_source_refs:\n            if source_id not in visual_source_ids:\n                errors.append(f\"{context}.visualSourceRef_unknown:{source_id}\")\n            else:\n                referenced_visual_source_ids.add(source_id)\n        _validate_spec_refs(\n            errors,\n            capability,\n            context,\n            defined_requirements,\n            defined_scenarios,\n            required=require_locked or status == \"locked\",\n        )\n\n    if require_locked or status == \"locked\":\n        for visual_source in visual_sources:\n            source_id = visual_source.get(\"sourceId\")\n            if (\n                isinstance(source_id, str)\n                and visual_source.get(\"required\") is True\n                and isinstance(visual_source.get(\"contentSha256\"), str)\n                and source_id not in referenced_visual_source_ids\n            ):\n                errors.append(f\"visualSources.required_archived_source_unbound:{source_id}\")\n\n    return errors\n\n\ndef _validate_spec_refs(\n    errors: list[str],\n    item: dict[str, Any],\n    context: str,\n    defined_requirements: set[str] | None,\n    defined_scenarios: set[str] | None,\n    *,\n    required: bool,\n) -> list[str]:\n    if item.get(\"specRefs\") is None and not required:\n        return []\n    spec_refs = _validate_string_array(errors, item, \"specRefs\", context, required=required)\n    req_refs = set(REQ_ID_RE.findall(\" \".join(spec_refs)))\n    scn_refs = set(SCN_ID_RE.findall(\" \".join(spec_refs)))\n    if spec_refs and not req_refs:\n        errors.append(f\"{context}.specRefs_missing_requirement_id\")\n    if spec_refs and not scn_refs:\n        errors.append(f\"{context}.specRefs_missing_scenario_id\")\n    if defined_requirements is not None:\n        for req_id in sorted(req_refs):\n            if req_id not in defined_requirements:\n                errors.append(f\"{context}.specRefs_unknown_requirement:{req_id}\")\n    if defined_scenarios is not None:\n        for scn_id in sorted(scn_refs):\n            if scn_id not in defined_scenarios:\n                errors.append(f\"{context}.specRefs_unknown_scenario:{scn_id}\")\n    return spec_refs\n\n\ndef ui_context_indexes(data: dict[str, Any] | None) -> dict[str, set[str]]:\n    if not isinstance(data, dict):\n        return {\"page\": set(), \"interaction\": set(), \"visualSource\": set(), \"capability\": set()}\n    return {\n        \"page\": {\n            item[\"pageId\"]\n            for item in data.get(\"pages\", [])\n            if isinstance(item, dict) and isinstance(item.get(\"pageId\"), str)\n        },\n        \"interaction\": {\n            item[\"interactionId\"]\n            for item in data.get(\"interactions\", [])\n            if isinstance(item, dict) and isinstance(item.get(\"interactionId\"), str)\n        },\n        \"visualSource\": {\n            item[\"sourceId\"]\n            for item in data.get(\"visualSources\", [])\n            if isinstance(item, dict) and isinstance(item.get(\"sourceId\"), str)\n        },\n        \"capability\": {\n            item[\"capabilityId\"]\n            for item in data.get(\"capabilities\", [])\n            if isinstance(item, dict) and isinstance(item.get(\"capabilityId\"), str)\n        },\n    }\n",
  "hooks/utest_command_policy.py": "\"\"\"Read-only rules extracted from hooks/utest_plan_contract.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nfrom pathlib import Path\n\nMAVEN_EXECUTABLES = {\n    \"mvn\",\n    \"mvn.cmd\",\n    \"mvn.bat\",\n    \"mvn.exe\",\n    \"mvnw\",\n    \"mvnw.cmd\",\n    \"mvnw.bat\",\n    \"mvnw.exe\",\n    \"./mvnw\",\n    \".\\\\mvnw.cmd\",\n}\n\n\nGRADLE_EXECUTABLES = {\n    \"gradle\",\n    \"gradle.bat\",\n    \"gradlew\",\n    \"gradlew.bat\",\n    \"./gradlew\",\n    \".\\\\gradlew.bat\",\n}\n\n\nPACKAGE_EXECUTABLES = {\n    \"npm\",\n    \"npm.cmd\",\n    \"pnpm\",\n    \"pnpm.cmd\",\n    \"yarn\",\n    \"yarn.cmd\",\n    \"bun\",\n    \"bun.exe\",\n    \"npx\",\n    \"npx.cmd\",\n}\n\n\nDIRECT_TEST_EXECUTABLES = {\n    \"pytest\",\n    \"pytest.exe\",\n    \"py.test\",\n    \"jest\",\n    \"jest.cmd\",\n    \"vitest\",\n    \"vitest.cmd\",\n}\n\n\ndef command_executes_tests(command):\n    \"\"\"Return whether a validation command can execute test cases.\"\"\"\n    if not isinstance(command, dict):\n        return False\n    argv = command.get(\"argv\")\n    if not isinstance(argv, list) or not argv or not all(\n        isinstance(item, str) and item for item in argv\n    ):\n        return False\n    executable = Path(argv[0].replace(\"\\\\\", \"/\")).name.lower()\n    executable_raw = argv[0].lower()\n    lowered = [item.lower() for item in argv[1:]]\n    if executable in DIRECT_TEST_EXECUTABLES:\n        return True\n    if executable in {\"python\", \"python.exe\", \"python3\", \"python3.exe\"} or executable.startswith(\"python3.\"):\n        if \"-m\" in lowered:\n            module_index = lowered.index(\"-m\") + 1\n            return module_index < len(lowered) and lowered[module_index] in {\"pytest\", \"unittest\"}\n        return False\n    if executable in MAVEN_EXECUTABLES or executable_raw in MAVEN_EXECUTABLES:\n        if any(value in {\"-dskiptests\", \"-dmaven.test.skip=true\", \"-dskiptests=true\"} for value in lowered):\n            return False\n        goals = [value for value in lowered if value and not value.startswith(\"-\")]\n        return any(value in {\"test\", \"integration-test\", \"verify\", \"package\", \"install\"} for value in goals)\n    if executable in GRADLE_EXECUTABLES or executable_raw in GRADLE_EXECUTABLES:\n        return any(\"test\" in value and not value.startswith(\"-\") for value in lowered)\n    if executable in PACKAGE_EXECUTABLES:\n        return any(\n            value in {\"test\", \"test:unit\", \"test:integration\", \"vitest\", \"jest\"}\n            or value.startswith(\"test:\")\n            for value in lowered\n        )\n    return False\n",
  "hooks/utest_repair_contract.py": "\"\"\"Read-only rules extracted from hooks/utest_plan_contract.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nimport hashlib\nimport json\nimport re\nfrom pathlib import Path\n\nTASK_CONTRACT_FIELDS = (\n    \"id\",\n    \"title\",\n    \"goal\",\n    \"implementationPoints\",\n    \"testPoints\",\n    \"nonGoals\",\n    \"validationBoundary\",\n    \"verificationIntent\",\n    \"workspaceRef\",\n    \"specRefs\",\n    \"acceptanceCriteria\",\n    \"validationLocations\",\n)\n\n\nTASK_ID_RE = re.compile(r\"^T\\d{3}$\")\n\n\nUTEST_COMMAND_PREFIX = \"UTEST-\"\n\n\nPENDING_TEST_COMMAND = \"待生成测试命令\"\n\n\nMAVEN_EXECUTABLES = {\n    \"mvn\",\n    \"mvn.cmd\",\n    \"mvn.bat\",\n    \"mvn.exe\",\n    \"mvnw\",\n    \"mvnw.cmd\",\n    \"mvnw.bat\",\n    \"mvnw.exe\",\n    \"./mvnw\",\n    \".\\\\mvnw.cmd\",\n}\n\n\nGRADLE_EXECUTABLES = {\n    \"gradle\",\n    \"gradle.bat\",\n    \"gradlew\",\n    \"gradlew.bat\",\n    \"./gradlew\",\n    \".\\\\gradlew.bat\",\n}\n\n\nPACKAGE_EXECUTABLES = {\n    \"npm\",\n    \"npm.cmd\",\n    \"pnpm\",\n    \"pnpm.cmd\",\n    \"yarn\",\n    \"yarn.cmd\",\n    \"bun\",\n    \"bun.exe\",\n    \"npx\",\n    \"npx.cmd\",\n}\n\n\nDIRECT_TEST_EXECUTABLES = {\n    \"pytest\",\n    \"pytest.exe\",\n    \"py.test\",\n    \"jest\",\n    \"jest.cmd\",\n    \"vitest\",\n    \"vitest.cmd\",\n}\n\n\nclass UTestPlanContractError(ValueError):\n    \"\"\"Raised when a plan cannot authorize a UTest action.\"\"\"\n\n\ndef _error(message):\n    raise UTestPlanContractError(\"{}。修复：回到 /autodev-plan 修正测试契约后重试。\".format(message))\n\n\ndef _read_object(path):\n    try:\n        data = json.loads(path.read_text(encoding=\"utf-8\"))\n    except OSError as exc:\n        _error(\"无法读取计划 {}：{}\".format(path, exc))\n    except ValueError as exc:\n        _error(\"计划不是合法 JSON {}：{}\".format(path, exc))\n    if not isinstance(data, dict):\n        _error(\"计划顶层不是 object：{}\".format(path))\n    return data\n\n\ndef _batch_path(feature_dir, raw_path):\n    if not isinstance(raw_path, str) or not raw_path.strip():\n        _error(\"root plan batch.path 缺失\")\n    requested = Path(raw_path)\n    if requested.is_absolute():\n        _error(\"Batch plan path 不能是绝对路径：{}\".format(raw_path))\n    root = Path(feature_dir).resolve()\n    resolved = (root / requested).resolve()\n    try:\n        resolved.relative_to(root)\n    except ValueError:\n        _error(\"Batch plan path 越界：{}\".format(raw_path))\n    return resolved\n\n\ndef validation_locations(task):\n    \"\"\"Return the Plan V2 workspace boundary for UTest-generated commands.\"\"\"\n    if not isinstance(task, dict):\n        return []\n    workspace_ref = task.get(\"workspaceRef\")\n    return [{\"repo\": workspace_ref, \"cwd\": \".\"}]\n\n\ndef canonical_task_contract(task):\n    if not isinstance(task, dict):\n        _error(\"TASK 不是 object\")\n    source = dict(task)\n    source[\"validationLocations\"] = validation_locations(task)\n    return {field: source.get(field) for field in TASK_CONTRACT_FIELDS}\n\n\ndef canonical_task_digest(task):\n    payload = canonical_task_contract(task)\n    encoded = json.dumps(\n        payload,\n        ensure_ascii=False,\n        sort_keys=True,\n        separators=(\",\", \":\"),\n    ).encode(\"utf-8\")\n    return hashlib.sha256(encoded).hexdigest()\n\n\ndef _string_list(value, context, allow_empty=False):\n    if not isinstance(value, list) or (not allow_empty and not value):\n        _error(\"{} 必须是{}字符串数组\".format(context, \"可空\" if allow_empty else \"非空\"))\n    if not all(isinstance(item, str) and item.strip() for item in value):\n        _error(\"{} 包含空值或非字符串\".format(context))\n    return list(value)\n\n\ndef command_executes_tests(command):\n    \"\"\"Return whether a validation command can execute test cases.\"\"\"\n    if not isinstance(command, dict):\n        return False\n    argv = command.get(\"argv\")\n    if not isinstance(argv, list) or not argv or not all(\n        isinstance(item, str) and item for item in argv\n    ):\n        return False\n    executable = Path(argv[0].replace(\"\\\\\", \"/\")).name.lower()\n    executable_raw = argv[0].lower()\n    lowered = [item.lower() for item in argv[1:]]\n    if executable in DIRECT_TEST_EXECUTABLES:\n        return True\n    if executable in {\"python\", \"python.exe\", \"python3\", \"python3.exe\"} or executable.startswith(\"python3.\"):\n        if \"-m\" in lowered:\n            module_index = lowered.index(\"-m\") + 1\n            return module_index < len(lowered) and lowered[module_index] in {\"pytest\", \"unittest\"}\n        return False\n    if executable in MAVEN_EXECUTABLES or executable_raw in MAVEN_EXECUTABLES:\n        if any(value in {\"-dskiptests\", \"-dmaven.test.skip=true\", \"-dskiptests=true\"} for value in lowered):\n            return False\n        goals = [value for value in lowered if value and not value.startswith(\"-\")]\n        return any(value in {\"test\", \"integration-test\", \"verify\", \"package\", \"install\"} for value in goals)\n    if executable in GRADLE_EXECUTABLES or executable_raw in GRADLE_EXECUTABLES:\n        return any(\"test\" in value and not value.startswith(\"-\") for value in lowered)\n    if executable in PACKAGE_EXECUTABLES:\n        return any(\n            value in {\"test\", \"test:unit\", \"test:integration\", \"vitest\", \"jest\"}\n            or value.startswith(\"test:\")\n            for value in lowered\n        )\n    return False\n\n\ndef _validate_task(task, batch_id):\n    task_id = task.get(\"id\") if isinstance(task, dict) else None\n    context = \"{} {}\".format(batch_id, task_id or \"TASK\")\n    if not isinstance(task_id, str) or not TASK_ID_RE.fullmatch(task_id):\n        _error(\"{} id 无效，必须形如 T001\".format(context))\n    title = task.get(\"title\")\n    if not isinstance(title, str) or not title.strip():\n        _error(\"{} title 缺失\".format(context))\n    goal = task.get(\"goal\")\n    if not isinstance(goal, str) or not goal.strip():\n        _error(\"{} goal 缺失\".format(context))\n    implementation_points = _string_list(\n        task.get(\"implementationPoints\"),\n        \"{} implementationPoints\".format(context),\n        allow_empty=True,\n    )\n    test_points = _string_list(task.get(\"testPoints\", []), \"{} testPoints\".format(context), allow_empty=True)\n    workspace_ref = task.get(\"workspaceRef\")\n    if not isinstance(workspace_ref, str) or not workspace_ref.strip():\n        _error(\"{} workspaceRef 缺失\".format(context))\n    boundary = task.get(\"validationBoundary\")\n    if not isinstance(boundary, str) or not boundary.strip():\n        _error(\"{} validationBoundary 缺失\".format(context))\n    verification_intent = task.get(\"verificationIntent\") or boundary\n    if not isinstance(verification_intent, str) or not verification_intent.strip():\n        _error(\"{} verificationIntent 缺失\".format(context))\n    non_goals = _string_list(task.get(\"nonGoals\"), \"{} nonGoals\".format(context), allow_empty=True)\n    spec_refs = _string_list(task.get(\"specRefs\"), \"{} specRefs\".format(context))\n\n    raw_acceptance = task.get(\"acceptanceCriteria\")\n    if not isinstance(raw_acceptance, list) or not raw_acceptance:\n        _error(\"{} acceptanceCriteria 必须是非空数组\".format(context))\n    acceptance_ids = []\n    for index, criterion in enumerate(raw_acceptance):\n        criterion_id = criterion.get(\"id\") if isinstance(criterion, dict) else None\n        if not isinstance(criterion_id, str) or not criterion_id.strip():\n            _error(\"{} acceptanceCriteria[{}].id 缺失\".format(context, index))\n        if criterion_id in acceptance_ids:\n            _error(\"{} acceptanceCriteria ID 重复：{}\".format(context, criterion_id))\n        criterion_text = criterion.get(\"text\") if isinstance(criterion, dict) else None\n        if not isinstance(criterion_text, str) or not criterion_text.strip():\n            _error(\"{} acceptanceCriteria[{}].text 缺失\".format(context, index))\n        acceptance_ids.append(criterion_id)\n\n    locations = validation_locations(task)\n\n    return {\n        \"id\": task_id,\n        \"title\": title,\n        \"goal\": goal,\n        \"implementationPoints\": implementation_points,\n        \"testPoints\": test_points,\n        \"workspaceRef\": workspace_ref,\n        \"validationBoundary\": boundary,\n        \"verificationIntent\": verification_intent,\n        \"nonGoals\": non_goals,\n        \"specRefs\": spec_refs,\n        \"acceptanceCriteria\": raw_acceptance,\n        \"validationLocations\": locations,\n        \"taskDigest\": canonical_task_digest(task),\n        \"rawTask\": task,\n        \"acceptanceIds\": acceptance_ids,\n    }\n\n\ndef load_utest_plan(feature_dir):\n    feature_root = Path(feature_dir).expanduser().resolve()\n    root = _read_object(feature_root / \"plan.json\")\n    batches = root.get(\"batches\")\n    if not isinstance(batches, list) or not batches:\n        _error(\"root plan.batches 必须是非空数组\")\n    result = []\n    seen_tasks = set()\n    for root_index, entry in enumerate(batches):\n        if not isinstance(entry, dict):\n            _error(\"root plan.batches[{}] 不是 object\".format(root_index))\n        path = _batch_path(feature_root, entry.get(\"path\"))\n        batch = _read_object(path)\n        batch_id = batch.get(\"batchId\") or entry.get(\"id\") or entry.get(\"batchId\")\n        lane = batch.get(\"executionLane\")\n        if not isinstance(batch_id, str) or not batch_id.strip():\n            _error(\"第 {} 个 Batch 缺少 batchId\".format(root_index + 1))\n        if not isinstance(lane, str) or not lane.strip():\n            _error(\"{} executionLane 缺失\".format(batch_id))\n        tasks = batch.get(\"tasks\")\n        if not isinstance(tasks, list) or not tasks:\n            _error(\"{} tasks 必须是非空数组\".format(batch_id))\n        projected_tasks = []\n        for task in tasks:\n            projected = _validate_task(task, batch_id)\n            if projected[\"id\"] in seen_tasks:\n                _error(\"TASK ID 跨 Batch 重复：{}\".format(projected[\"id\"]))\n            seen_tasks.add(projected[\"id\"])\n            projected_tasks.append(projected)\n        result.append(\n            {\n                \"batchId\": batch_id,\n                \"executionLane\": lane,\n                \"planPath\": path.relative_to(feature_root).as_posix(),\n                \"rootOrder\": root_index,\n                \"tasks\": projected_tasks,\n            }\n        )\n    return {\"featureDir\": feature_root, \"root\": root, \"batches\": result}\n\n\ndef expand_plan_targets(plan):\n    targets = []\n    for batch in plan.get(\"batches\", []):\n        for task in batch.get(\"tasks\", []):\n            targets.append(\n                {\n                    \"targetId\": \"UT-{:03d}\".format(len(targets) + 1),\n                    \"taskId\": task[\"id\"],\n                    \"taskDigest\": task[\"taskDigest\"],\n                    \"commandId\": \"{}{}\".format(UTEST_COMMAND_PREFIX, task[\"id\"]),\n                    \"specRefs\": list(task[\"specRefs\"]),\n                    \"covers\": list(task[\"acceptanceIds\"]),\n                    \"result\": \"BLOCKED\",\n                    \"command\": PENDING_TEST_COMMAND,\n                    \"evidenceIds\": [],\n                    \"validationLocations\": list(task[\"validationLocations\"]),\n                    \"required\": True,\n                    \"assetType\": \"unit_test\",\n                    \"acceptanceCriteria\": task[\"acceptanceCriteria\"],\n                }\n            )\n    if not targets:\n        _error(\"plan 没有可生成单测的 TASK\")\n    return targets\n\n\ndef shell_join_argv(argv):\n    try:\n        import shlex\n\n        return shlex.join(argv)\n    except AttributeError:\n        import shlex\n\n        return \" \".join(shlex.quote(value) for value in argv)\n\n\ndef public_target(target):\n    return {\n        \"targetId\": target[\"targetId\"],\n        \"taskId\": target[\"taskId\"],\n        \"taskDigest\": target[\"taskDigest\"],\n        \"commandId\": target[\"commandId\"],\n        \"specRefs\": list(target[\"specRefs\"]),\n        \"covers\": list(target[\"covers\"]),\n        \"evidenceIds\": list(target.get(\"evidenceIds\", [])),\n        \"result\": target.get(\"result\", \"BLOCKED\"),\n        \"command\": target[\"command\"],\n    }\n\n\ndef resolve_plan_target(feature_dir, task_id, command_id=None):\n    plan = load_utest_plan(feature_dir)\n    matches = [\n        target\n        for target in expand_plan_targets(plan)\n        if target[\"taskId\"] == task_id\n        and (command_id is None or target[\"commandId\"] == command_id)\n    ]\n    if len(matches) != 1:\n        _error(\n            \"--task-id {}{} 未唯一映射 UTest target\".format(\n                task_id,\n                \" 与 --command-id {}\".format(command_id) if command_id else \"\",\n            )\n        )\n    return plan, matches[0]\n\n\ndef read_evidence_records(feature_dir):\n    path = Path(feature_dir) / \"evidence\" / \"EVIDENCE.jsonl\"\n    if not path.is_file():\n        return []\n    records = []\n    try:\n        lines = path.read_text(encoding=\"utf-8\", errors=\"ignore\").splitlines()\n    except OSError as exc:\n        _error(\"无法读取 Evidence：{}\".format(exc))\n    for line_no, raw in enumerate(lines, 1):\n        if not raw.strip():\n            continue\n        try:\n            value = json.loads(raw)\n        except ValueError:\n            _error(\"Evidence 第 {} 行不是合法 JSON\".format(line_no))\n        if not isinstance(value, dict):\n            _error(\"Evidence 第 {} 行不是 object\".format(line_no))\n        records.append(value)\n    return records\n\n\ndef result_for_evidence(record):\n    validation = record.get(\"validation\") if isinstance(record, dict) else None\n    if not isinstance(validation, dict):\n        return \"BLOCKED\"\n    result = str(validation.get(\"result\", \"\")).strip().lower()\n    exit_code = validation.get(\"exitCode\")\n    if result == \"pass\" and exit_code == 0:\n        if \"testsExecuted\" in validation and (not isinstance(validation[\"testsExecuted\"], int) or validation[\"testsExecuted\"] <= 0):\n            return \"BLOCKED\"\n        return \"PASS\"\n    if result == \"fail\" and isinstance(exit_code, int) and exit_code != 0:\n        return \"FAIL\"\n    return \"BLOCKED\"\n\n\ndef derive_verdict(targets, plan_targets):\n    required_results = []\n    optional_results = []\n    required_by_id = {item[\"targetId\"]: item[\"required\"] for item in plan_targets}\n    for target in targets:\n        result = target.get(\"result\", \"BLOCKED\")\n        if required_by_id.get(target.get(\"targetId\"), True):\n            required_results.append(result)\n        else:\n            optional_results.append(result)\n    if \"FAIL\" in required_results or \"FAIL\" in optional_results:\n        return \"FAIL\"\n    if any(result != \"PASS\" for result in required_results + optional_results):\n        return \"BLOCKED\"\n    return \"PASS\"\n\n\ndef derive_check_matrix(result_targets, plan_targets, runtime_block=None):\n    required_by_id = {item[\"targetId\"]: item[\"required\"] for item in plan_targets}\n    block_code = runtime_block.get(\"reasonCode\") if isinstance(runtime_block, dict) else None\n    result = []\n    for target in result_targets:\n        raw_result = target.get(\"result\", \"BLOCKED\")\n        if raw_result in {\"PASS\", \"PASS_WITH_WARNINGS\"}:\n            status = \"passed\"\n            reason_code = None\n        elif raw_result == \"FAIL\":\n            status = \"failed\"\n            reason_code = None\n        elif raw_result == \"SKIP\":\n            status = \"skipped\"\n            reason_code = \"optional_check_skipped\"\n        elif block_code:\n            status = \"blocked\"\n            reason_code = block_code\n        else:\n            status = \"not_run\"\n            reason_code = \"not_executed\"\n        row = {\n            \"checkId\": \"CHECK-{}\".format(target.get(\"targetId\")),\n            \"targetId\": target.get(\"targetId\"),\n            \"kind\": \"unit_test\",\n            \"required\": required_by_id.get(target.get(\"targetId\"), True),\n            \"status\": status,\n        }\n        if reason_code is not None:\n            row[\"reasonCode\"] = reason_code\n        result.append(row)\n    return result\n\n\ndef derive_unverified_checks(checks):\n    return [\n        {\n            \"checkId\": item.get(\"checkId\"),\n            \"kind\": item.get(\"kind\"),\n            \"reasonCode\": item.get(\"reasonCode\", \"not_executed\"),\n        }\n        for item in checks\n        if isinstance(item, dict) and item.get(\"status\") in {\"blocked\", \"not_run\", \"skipped\"}\n    ]\n\n\ndef _scenario_ids(refs):\n    result = []\n    for ref in refs:\n        if not isinstance(ref, str):\n            continue\n        for value in re.findall(r\"\\bSCN-\\d{3}\\b\", ref):\n            if value not in result:\n                result.append(value)\n    return result\n\n\ndef plan_scenario_refs(plan):\n    refs = []\n    for batch in plan.get(\"batches\", []):\n        for task in batch.get(\"tasks\", []):\n            source_refs = list(task.get(\"specRefs\", []))\n            for criterion in task.get(\"acceptanceCriteria\", []):\n                if isinstance(criterion, dict) and isinstance(\n                    criterion.get(\"scenarioRefs\"), list\n                ):\n                    source_refs.extend(criterion[\"scenarioRefs\"])\n            for scenario_id in _scenario_ids(source_refs):\n                if scenario_id not in refs:\n                    refs.append(scenario_id)\n    return refs\n\n\ndef derive_scenario_coverage(\n    plan_targets, result_targets, evidence_by_id, scenario_refs=None\n):\n    result_by_id = {\n        item.get(\"targetId\"): item for item in result_targets if isinstance(item, dict)\n    }\n    scenario_order = list(scenario_refs or [])\n    scenario_targets = {scenario_id: [] for scenario_id in scenario_order}\n    for plan_target in plan_targets:\n        criteria_by_id = {\n            criterion.get(\"id\"): criterion\n            for criterion in plan_target.get(\"acceptanceCriteria\", [])\n            if isinstance(criterion, dict)\n        }\n        refs = []\n        for criterion_id in plan_target.get(\"covers\", []):\n            criterion = criteria_by_id.get(criterion_id, {})\n            raw_refs = criterion.get(\"scenarioRefs\") if isinstance(criterion, dict) else []\n            if isinstance(raw_refs, list):\n                refs.extend(raw_refs)\n        if not refs:\n            refs = plan_target.get(\"specRefs\", [])\n        for scenario_id in _scenario_ids(refs):\n            if scenario_id not in scenario_targets:\n                scenario_targets[scenario_id] = []\n                scenario_order.append(scenario_id)\n            scenario_targets[scenario_id].append(plan_target[\"targetId\"])\n    rows = []\n    for scenario_id in scenario_order:\n        statuses = []\n        evidence_ids = []\n        for target_id in scenario_targets[scenario_id]:\n            result_target = result_by_id.get(target_id, {})\n            statuses.append(result_target.get(\"result\", \"BLOCKED\"))\n            target_evidence = result_target.get(\"evidenceIds\", [])\n            if target_evidence:\n                latest = evidence_by_id.get(target_evidence[-1])\n                if result_for_evidence(latest) == \"PASS\":\n                    evidence_ids.append(target_evidence[-1])\n        if \"FAIL\" in statuses:\n            verdict = \"fail\"\n            evidence_ids = []\n        elif statuses and all(status == \"PASS\" for status in statuses):\n            verdict = \"pass\"\n        else:\n            verdict = \"missing\"\n            evidence_ids = []\n        rows.append(\n            {\"scenarioRef\": scenario_id, \"evidenceIds\": evidence_ids, \"verdict\": verdict}\n        )\n    return rows\n\n\ndef validate_result_against_plan(feature_dir, data):\n    \"\"\"Return stable semantic errors for writer and board stage gates.\"\"\"\n    errors = []\n    try:\n        plan = load_utest_plan(feature_dir)\n        plan_targets = expand_plan_targets(plan)\n    except UTestPlanContractError as exc:\n        return [\"utest_plan_contract_invalid:{}\".format(exc)]\n    if not isinstance(data, dict):\n        return [\"unit_test_result_root_invalid\"]\n    if data.get(\"version\") != 1:\n        errors.append(\"invalid_unit_test_result_version\")\n    targets = data.get(\"targets\")\n    if not isinstance(targets, list):\n        return [\"unit_test_targets_invalid\"]\n    expected_by_id = {target[\"targetId\"]: target for target in plan_targets}\n    actual_by_id = {\n        target.get(\"targetId\"): target\n        for target in targets\n        if isinstance(target, dict) and isinstance(target.get(\"targetId\"), str)\n    }\n    if set(actual_by_id) != set(expected_by_id) or len(targets) != len(plan_targets):\n        errors.append(\"unit_test_targets_not_initialized_from_plan_tasks\")\n    try:\n        records = read_evidence_records(feature_dir)\n    except UTestPlanContractError as exc:\n        return errors + [\"unit_test_evidence_contract_invalid:{}\".format(exc)]\n    evidence_by_id = {\n        record.get(\"evidenceId\"): record\n        for record in records\n        if isinstance(record.get(\"evidenceId\"), str)\n    }\n    for target_id, expected in expected_by_id.items():\n        actual = actual_by_id.get(target_id)\n        if not isinstance(actual, dict):\n            errors.append(\"required_unit_test_target_missing:{}\".format(target_id))\n            continue\n        for field in (\"taskId\", \"taskDigest\", \"commandId\", \"specRefs\", \"covers\"):\n            expected_value = expected[field]\n            if actual.get(field) != expected_value:\n                errors.append(\"unit_test_target_plan_mismatch:{}:{}\".format(target_id, field))\n        if not isinstance(actual.get(\"command\"), str) or not actual.get(\"command\", \"\").strip():\n            errors.append(\"unit_test_target_command_invalid:{}\".format(target_id))\n        evidence_ids = actual.get(\"evidenceIds\")\n        if not isinstance(evidence_ids, list) or not all(\n            isinstance(value, str) and value for value in evidence_ids\n        ):\n            errors.append(\"unit_test_target_evidenceIds_invalid:{}\".format(target_id))\n            continue\n        latest_result = \"BLOCKED\"\n        latest_command = PENDING_TEST_COMMAND\n        for evidence_id in evidence_ids:\n            record = evidence_by_id.get(evidence_id)\n            if record is None:\n                errors.append(\"unit_test_target_evidence_missing:{}:{}\".format(target_id, evidence_id))\n                continue\n            validation = record.get(\"validation\")\n            if not isinstance(validation, dict):\n                errors.append(\"unit_test_evidence_validation_missing:{}\".format(evidence_id))\n                continue\n            expected_fields = {\n                \"taskId\": expected[\"taskId\"],\n                \"taskDigest\": expected[\"taskDigest\"],\n                \"specRefs\": expected[\"specRefs\"],\n                \"covers\": expected[\"covers\"],\n            }\n            for field, expected_value in expected_fields.items():\n                if record.get(field) != expected_value:\n                    errors.append(\"unit_test_evidence_plan_mismatch:{}:{}\".format(evidence_id, field))\n            if validation.get(\"commandId\") != expected[\"commandId\"]:\n                errors.append(\"unit_test_evidence_plan_mismatch:{}:commandId\".format(evidence_id))\n            if validation.get(\"required\") is not True:\n                errors.append(\"unit_test_evidence_plan_mismatch:{}:required\".format(evidence_id))\n            if validation.get(\"covers\") != expected[\"covers\"]:\n                errors.append(\"unit_test_evidence_plan_mismatch:{}:covers\".format(evidence_id))\n            location = {\n                \"repo\": validation.get(\"repo\"),\n                \"cwd\": validation.get(\"cwd\"),\n            }\n            if location not in expected[\"validationLocations\"]:\n                errors.append(\"unit_test_evidence_location_not_allowed:{}\".format(evidence_id))\n            if not command_executes_tests(validation):\n                errors.append(\"unit_test_evidence_command_not_test:{}\".format(evidence_id))\n            argv = validation.get(\"argv\")\n            if isinstance(argv, list) and argv and all(\n                isinstance(value, str) and value for value in argv\n            ):\n                derived_command = shell_join_argv(argv)\n                if validation.get(\"command\") != derived_command:\n                    errors.append(\"unit_test_evidence_command_not_derived:{}\".format(evidence_id))\n            test_files = validation.get(\"testFiles\")\n            if not isinstance(test_files, list) or not test_files or not all(\n                isinstance(value, str) and value for value in test_files\n            ):\n                errors.append(\"unit_test_evidence_testFiles_invalid:{}\".format(evidence_id))\n            elif record.get(\"changedFiles\") != test_files:\n                errors.append(\"unit_test_evidence_testFiles_not_bound:{}\".format(evidence_id))\n            if isinstance(validation.get(\"command\"), str) and validation.get(\"command\"):\n                latest_command = validation[\"command\"]\n            latest_result = result_for_evidence(record)\n        if actual.get(\"result\") != latest_result:\n            errors.append(\"unit_test_target_result_not_derived:{}\".format(target_id))\n        if actual.get(\"command\") != latest_command:\n            errors.append(\"unit_test_target_command_not_derived:{}\".format(target_id))\n    expected_verdict = derive_verdict(targets, plan_targets)\n    if data.get(\"verdict\") != expected_verdict:\n        errors.append(\"unit_test_verdict_not_derived:{}\".format(expected_verdict))\n    expected_coverage = derive_scenario_coverage(\n        plan_targets,\n        targets,\n        evidence_by_id,\n        scenario_refs=plan_scenario_refs(plan),\n    )\n    if data.get(\"scenarioCoverage\") != expected_coverage:\n        errors.append(\"unit_test_coverage_not_derived_from_plan_evidence\")\n    expected_checks = derive_check_matrix(targets, plan_targets, data.get(\"runtimeBlock\"))\n    if data.get(\"checks\") != expected_checks:\n        errors.append(\"unit_test_checks_not_derived_from_plan_evidence\")\n    if data.get(\"unverifiedChecks\") != derive_unverified_checks(expected_checks):\n        errors.append(\"unit_test_unverified_checks_not_derived\")\n    return errors\n\n\ndef validate_source_bug(feature_dir, data, task_id, command_id, target_id, task_digest, evidence_id):\n    errors = validate_result_against_plan(feature_dir, data)\n    if errors:\n        _error(\"UNIT_TEST_RESULT 不满足可信契约：{}\".format(\",\".join(errors)))\n    plan, expected = resolve_plan_target(feature_dir, task_id, command_id)\n    del plan\n    if target_id != expected[\"targetId\"]:\n        _error(\"source_bug targetId 与当前 TASK 的 UTest target 不一致\")\n    if task_digest != expected[\"taskDigest\"]:\n        _error(\"source_bug taskDigest 与当前 plan 不一致\")\n    targets = data.get(\"targets\", [])\n    target = next(\n        (item for item in targets if isinstance(item, dict) and item.get(\"targetId\") == target_id),\n        None,\n    )\n    if target is None or target.get(\"result\") != \"FAIL\":\n        _error(\"source_bug 必须绑定 result=FAIL 的真实 UT target\")\n    evidence_ids = target.get(\"evidenceIds\", [])\n    if not evidence_ids or evidence_id != evidence_ids[-1]:\n        _error(\"source_bug 必须绑定 target 最新一次失败 Evidence\")\n    records = read_evidence_records(feature_dir)\n    record = next((item for item in records if item.get(\"evidenceId\") == evidence_id), None)\n    validation = record.get(\"validation\") if isinstance(record, dict) else None\n    if not isinstance(validation, dict) or validation.get(\"result\") != \"fail\":\n        _error(\"source_bug Evidence 必须是失败测试证据\")\n    exit_code = validation.get(\"exitCode\")\n    if not isinstance(exit_code, int) or exit_code == 0:\n        _error(\"source_bug Evidence exitCode 必须非 0\")\n    if record.get(\"covers\") != expected[\"covers\"]:\n        _error(\"source_bug covers 必须映射当前 TASK 的真实 acceptanceCriteria\")\n    return {\n        \"taskId\": task_id,\n        \"commandId\": command_id,\n        \"targetId\": target_id,\n        \"taskDigest\": task_digest,\n        \"evidenceId\": evidence_id,\n        \"covers\": list(expected[\"covers\"]),\n    }\n",
  "native_context.py": "\"\"\"Read-only adapter for extracted business checks; no outer workflow state API.\"\"\"\nfrom pathlib import Path\n\n\nclass HookContext:\n    def __init__(self, directory: Path, feature: str, stage: str):\n        self.feature_dir = directory\n        self.slug = feature\n        self.skill = \"autobiz-requirement-discuss\" if stage == \"prd\" else \"autodev-\" + stage\n        self.errors = []\n        self.warnings = []\n\n    def file(self, name):\n        return self.feature_dir / name\n\n    def requires_artifact(self, name):\n        return name in {\"UI_CONTEXT.json\", \"plan.json\"}\n\n\ndef fail_line(ctx, reason, detail=\"\", **kwargs):\n    ctx.errors.append({\"code\": reason, \"detail\": detail, **kwargs})\n    return 1\n\n\ndef info(ctx, reason, detail=\"\", **kwargs):\n    ctx.warnings.append({\"code\": reason, \"detail\": detail, **kwargs})\n\n\ndef is_nonempty(path):\n    return path.is_file() and path.stat().st_size > 0\n\n\ndef read_text(path):\n    return path.read_text(encoding=\"utf-8\")\n",
  "ops.py": "\"\"\"Native read-only CI/CD preparation and immutable archive rules.\n\nDerived from autoops-cicd/autoops-archive SKILL contracts, not the old state writer.\nExternal publication requires a separately bound native provider and original receipts.\nThis package deliberately cannot claim it performed an external deployment.\n\"\"\"\nimport hashlib\nimport json\n\nARTIFACTS = [\"NORMALIZED_REQUIREMENTS.json\", \"PRD.bundle.json\", \"SPECS.bundle.json\", \"DESIGN.bundle.json\", \"PLAN.bundle.json\", \"CODE_RESULT.json\"]\n\ndef check(request):\n    stage, current, sources = request[\"stage\"], request[\"current\"], request[\"sources\"]\n    feature = json.loads(sources[\"NORMALIZED_REQUIREMENTS.json\"])[\"feature\"]\n    if current.get(\"feature\") != feature or current.get(\"stage\") != stage:\n        raise ValueError(\"AUTOBIZ_OPS_IDENTITY_MISMATCH\")\n    if stage == \"cicd\":\n        if current.get(\"publication\") != {\"mode\": \"not-requested\", \"status\": \"prepared-only\"}:\n            raise ValueError(\"AUTOBIZ_EXTERNAL_PUBLICATION_PROVIDER_REQUIRED\")\n        files = current.get(\"files\", {})\n        if set(files) != {\"CICD_CHECKLIST.md\", \"PR_BODY.md\"} or any(not isinstance(text, str) or not text.strip() for text in files.values()):\n            raise ValueError(\"AUTOBIZ_CICD_DOCUMENTS_REQUIRED\")\n        checklist = files[\"CICD_CHECKLIST.md\"]\n        for heading in [\"## 交付范围\", \"## 验证证据\", \"## 发布状态\", \"## 已知阻断问题\", \"## 回滚计划\"]:\n            if heading not in checklist:\n                raise ValueError(\"AUTOBIZ_CICD_SECTION_MISSING:\" + heading)\n        if \"未请求外部发布\" not in checklist or \"prepared-only\" not in checklist:\n            raise ValueError(\"AUTOBIZ_CICD_PREPARATION_MUST_BE_EXPLICIT\")\n        code = json.loads(sources[\"CODE_RESULT.json\"])\n        if current.get(\"codeRunId\") != code.get(\"runId\") or code.get(\"feature\") != feature:\n            raise ValueError(\"AUTOBIZ_CICD_CODE_RUN_CHANGED\")\n        if code[\"runId\"] not in checklist or not all(path in checklist for path in [\"PRD.bundle.json\", \"SPECS.bundle.json\", \"DESIGN.bundle.json\"]):\n            raise ValueError(\"AUTOBIZ_CICD_SOURCE_LINEAGE_REQUIRED\")\n    elif stage == \"archive\":\n        expected = ARTIFACTS + [\"CICD.bundle.json\"]\n        files, digests = current.get(\"files\", {}), current.get(\"artifactDigests\", {})\n        if set(files) != set(expected) or set(digests) != set(expected):\n            raise ValueError(\"AUTOBIZ_ARCHIVE_ARTIFACT_COVERAGE_INVALID\")\n        for name in expected:\n            if files[name] != sources[name] or digests[name] != hashlib.sha256(sources[name].encode(\"utf-8\")).hexdigest():\n                raise ValueError(\"AUTOBIZ_ARCHIVE_SOURCE_CHANGED:\" + name)\n        if current.get(\"publicationStatus\") != \"prepared-only\":\n            raise ValueError(\"AUTOBIZ_ARCHIVE_PUBLICATION_CLAIM_INVALID\")\n        check({\"stage\": \"cicd\", \"current\": json.loads(sources[\"CICD.bundle.json\"]), \"sources\": sources})\n    else:\n        raise ValueError(\"AUTOBIZ_OPS_STAGE_INVALID\")\n    return {\"passed\": True, \"errors\": [], \"warnings\": [\"未请求或执行外部发布；成果仅为CI/CD准备及过程归档。\"], \"publicationStatus\": \"prepared-only\"}\n",
  "performance.py": "\"\"\"Apply the original seven rules to bounded, actual changed Git blobs.\n\nOnly immutable blob bytes enter the rule engine. Diagnostics expose rule IDs and\nline numbers, never source snippets, URLs, or exception details.\n\"\"\"\nimport hashlib\nimport re\nimport subprocess\nfrom pathlib import PurePosixPath\nfrom hooks.performance_rules import FRONTEND_EXTENSIONS, run_check\n\nMAX_FILES = 64\nMAX_FILE_BYTES = 64 * 1024\nMAX_TOTAL_BYTES = 256 * 1024\n\n\ndef git(*args):\n    result = subprocess.run([\"git\", *args], capture_output=True, timeout=20)\n    if result.returncode != 0:\n        raise ValueError(\"PERFORMANCE_GIT_READ_FAILED\")\n    return result.stdout\n\n\ndef check(command):\n    try:\n        baseline, commit = command.get(\"baselineCommit\"), command.get(\"expectedCommit\")\n        if any(not isinstance(value, str) or not re.fullmatch(r\"[a-f0-9]{40,64}\", value)\n               for value in (baseline, commit)):\n            raise ValueError(\"PERFORMANCE_COMMIT_REQUIRED\")\n        if git(\"rev-parse\", \"HEAD\").decode(\"ascii\").strip() != commit:\n            raise ValueError(\"PERFORMANCE_HEAD_CHANGED\")\n        diff = git(\"diff\", \"--no-ext-diff\", \"--name-only\", \"--diff-filter=ACMR\", \"-z\", baseline, commit)\n        if len(diff) > 64000:\n            raise ValueError(\"PERFORMANCE_DIFF_LIMIT\")\n        paths = [item.decode(\"utf-8\", errors=\"strict\") for item in diff.split(b\"\\0\") if item]\n        selected = [path for path in paths if PurePosixPath(path).suffix in FRONTEND_EXTENSIONS]\n        if len(selected) > MAX_FILES:\n            raise ValueError(\"PERFORMANCE_FILE_COUNT_LIMIT\")\n        files, errors, total = [], [], 0\n        for path in selected:\n            # Reject symlinks/gitlinks instead of checking their target spelling as source code.\n            tree = git(\"ls-tree\", \"-z\", commit, \"--\", path).split(b\"\\0\")\n            if len(tree) != 2 or tree[1] or tree[0].split(b\" \", 1)[0] not in {b\"100644\", b\"100755\"}:\n                raise ValueError(\"PERFORMANCE_REGULAR_BLOB_REQUIRED\")\n            size = int(git(\"cat-file\", \"-s\", commit + \":\" + path))\n            total += size\n            if size > MAX_FILE_BYTES or total > MAX_TOTAL_BYTES:\n                raise ValueError(\"PERFORMANCE_SOURCE_LIMIT\")\n            content = git(\"show\", \"--no-ext-diff\", \"--no-textconv\", commit + \":\" + path)\n            if len(content) != size:\n                raise ValueError(\"PERFORMANCE_BLOB_CHANGED\")\n            text = content.decode(\"utf-8\", errors=\"strict\")\n            findings = run_check(text)\n            files.append({\"path\": path, \"sha256\": hashlib.sha256(content).hexdigest(), \"bytes\": size})\n            errors.extend({\"code\": item[\"rule_id\"], \"path\": path, \"line\": item[\"line\"]}\n                          for item in findings)\n            if len(errors) > 128:\n                raise ValueError(\"PERFORMANCE_FINDINGS_LIMIT\")\n        if git(\"rev-parse\", \"HEAD\").decode(\"ascii\").strip() != commit:\n            raise ValueError(\"PERFORMANCE_HEAD_CHANGED\")\n        return {\"passed\": not errors, \"errors\": errors, \"warnings\": [],\n                \"baselineCommit\": baseline, \"headCommit\": commit, \"files\": files}\n    except Exception as error:\n        # Never serialize raw Git/Python exceptions: they can contain source or local paths.\n        allowed = {\"PERFORMANCE_GIT_READ_FAILED\", \"PERFORMANCE_COMMIT_REQUIRED\",\n                   \"PERFORMANCE_HEAD_CHANGED\", \"PERFORMANCE_DIFF_LIMIT\", \"PERFORMANCE_FILE_COUNT_LIMIT\",\n                   \"PERFORMANCE_REGULAR_BLOB_REQUIRED\", \"PERFORMANCE_SOURCE_LIMIT\",\n                   \"PERFORMANCE_BLOB_CHANGED\", \"PERFORMANCE_FINDINGS_LIMIT\"}\n        code = str(error) if isinstance(error, ValueError) and str(error) in allowed else \"PERFORMANCE_READ_INVALID\"\n        return {\"passed\": False, \"errors\": [{\"code\": code}], \"warnings\": []}\n",
  "prd_rules.py": "\"\"\"Read-only rules extracted from skills/autobiz/hooks/prd_rules.py. See provenance.json.\"\"\"\nfrom __future__ import annotations\nimport re\nfrom dataclasses import dataclass\nfrom typing import List, Sequence, Union\n\nREQUIRED_PRD_SECTIONS = (\"外部资料与实现约束\",)\n\n\nFORMAL_SECTION_MAX_LEVEL = 3\n\n\nPENDING_MARKER = \"【待确认】\"\n\n\n_HEADING_RE = re.compile(r\"^ {0,3}(#{1,6})\\s+(.*?)\\s*$\")\n\n\n_FENCE_RE = re.compile(r\"^ {0,3}(`{3,}|~{3,})\")\n\n\n@dataclass(frozen=True)\nclass Heading:\n    level: int\n    text: str\n    line_index: int\n\n\ndef iter_headings(source: Union[str, Sequence[str]]) -> List[Heading]:\n    \"\"\"提取 Markdown 标题，忽略围栏代码块内的标题示例。\"\"\"\n    lines = source.split(\"\\n\") if isinstance(source, str) else list(source)\n    headings: List[Heading] = []\n    fence = None\n    for index, line in enumerate(lines):\n        fence_match = _FENCE_RE.match(line)\n        if fence_match:\n            marker = fence_match.group(1)\n            if fence is None:\n                fence = marker\n            elif marker[0] == fence[0] and len(marker) >= len(fence):\n                fence = None\n            continue\n        if fence is not None:\n            continue\n        heading_match = _HEADING_RE.match(line)\n        if heading_match:\n            headings.append(\n                Heading(len(heading_match.group(1)), heading_match.group(2), index)\n            )\n    return headings\n\n\ndef pending_marker_lines(content: str) -> List[int]:\n    \"\"\"返回残留 `【待确认】` 的 1-based 行号，供报错直接定位。\"\"\"\n    return [\n        index + 1\n        for index, line in enumerate(content.split(\"\\n\"))\n        if PENDING_MARKER in line\n    ]\n",
  "repair.py": "\"\"\"Project original immutable failed-command receipts into the retained UT contract.\n\nThis private compatibility projection does not update the legacy writer/state tree.\nThe caller obtains the receipt from native.workflow, never from model evidence.\n\"\"\"\nimport json\nimport tempfile\nfrom pathlib import Path\nfrom hooks.utest_repair_contract import (\n    load_utest_plan, expand_plan_targets, public_target, shell_join_argv,\n    derive_verdict, derive_check_matrix, derive_unverified_checks,\n    derive_scenario_coverage, plan_scenario_refs, validate_source_bug,\n)\n\n\ndef check(request):\n    from check import safe_path\n    plan_bundle, receipt = request[\"plan\"], request[\"receipt\"]\n    output = receipt.get(\"output\", {})\n    if (receipt.get(\"status\") != \"failed\" or receipt.get(\"outputTruncated\")\n            or output.get(\"passed\") is not False or output.get(\"phase\") != \"test\"\n            or not isinstance(output.get(\"exitCode\"), int) or isinstance(output[\"exitCode\"], bool)\n            or output[\"exitCode\"] == 0 or output.get(\"logTruncated\")\n            or not output.get(\"testFiles\") or not output.get(\"taskIds\")):\n        raise ValueError(\"UT_REPAIR_REQUIRES_COMPLETE_FAILED_COMMAND_RECEIPT\")\n    with tempfile.TemporaryDirectory(prefix=\"autobiz-ut-attestation-\") as directory:\n        root = Path(directory)\n        for name, text in plan_bundle[\"files\"].items():\n            safe_path(name)\n            path = root / name\n            path.parent.mkdir(parents=True, exist_ok=True)\n            path.write_text(text, encoding=\"utf-8\")\n        plan = load_utest_plan(root)\n        targets = expand_plan_targets(plan)\n        if not set(output[\"taskIds\"]).issubset({target[\"taskId\"] for target in targets}):\n            raise ValueError(\"UT_REPAIR_TASK_NOT_IN_CURRENT_PLAN\")\n        selected = [target for target in targets if target[\"taskId\"] in output[\"taskIds\"]]\n        if any(target[\"validationLocations\"] != [{\"repo\": output.get(\"workspaceRef\"), \"cwd\": \".\"}] for target in selected):\n            raise ValueError(\"UT_REPAIR_REPOSITORY_MISMATCH\")\n        records = []\n        for target in targets:\n            if target[\"taskId\"] not in output[\"taskIds\"]:\n                continue\n            evidence_id = receipt[\"executionId\"] + \":\" + target[\"taskId\"]\n            command = shell_join_argv(output[\"argv\"])\n            target.update(result=\"FAIL\", evidenceIds=[evidence_id], command=command)\n            records.append({\"evidenceId\": evidence_id, \"taskId\": target[\"taskId\"],\n                \"taskDigest\": target[\"taskDigest\"], \"specRefs\": target[\"specRefs\"],\n                \"covers\": target[\"covers\"], \"changedFiles\": output[\"testFiles\"],\n                \"validation\": {\"commandId\": target[\"commandId\"], \"required\": True,\n                    \"covers\": target[\"covers\"], \"repo\": target[\"validationLocations\"][0][\"repo\"], \"cwd\": target[\"validationLocations\"][0][\"cwd\"],\n                    \"argv\": output[\"argv\"], \"command\": command, \"testFiles\": output[\"testFiles\"],\n                    \"result\": \"fail\", \"exitCode\": output[\"exitCode\"]}})\n        public = [public_target(target) for target in targets]\n        matrix = derive_check_matrix(public, targets)\n        result = {\"version\": 1, \"targets\": public, \"verdict\": derive_verdict(public, targets),\n            \"checks\": matrix, \"unverifiedChecks\": derive_unverified_checks(matrix),\n            \"scenarioCoverage\": derive_scenario_coverage(targets, public,\n                {record[\"evidenceId\"]: record for record in records}, scenario_refs=plan_scenario_refs(plan))}\n        (root / \"evidence\").mkdir()\n        (root / \"evidence/EVIDENCE.jsonl\").write_text(\n            \"\\n\".join(json.dumps(record, ensure_ascii=False) for record in records), encoding=\"utf-8\")\n        attestations = [validate_source_bug(root, result, target[\"taskId\"], target[\"commandId\"],\n            target[\"targetId\"], target[\"taskDigest\"], target[\"evidenceIds\"][-1])\n            for target in targets if target[\"taskId\"] in output[\"taskIds\"]]\n        return {\"passed\": True, \"errors\": [], \"warnings\": [], \"failedExecutionId\": receipt[\"executionId\"],\n            \"headCommit\": output[\"headCommit\"], \"workspaceRef\": output[\"workspaceRef\"],\n            \"argv\": output[\"argv\"], \"attestations\": attestations}\n"
}
